// Cyrus mod pages: the SERVER half. Generates/refreshes CyrusModPage rows from
// ModBuild chains (pure generator in ./doc.ts) and reads them for viewers.
// Plain module: called from lib/modbuilder/store.ts (API routes + worker sweep).
import type { CyrusModPage, ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { buildModDoc, pageVisibleTo, readModDoc, slugifyModName, uniqueSlug, type CyrusModDoc } from "./doc";
import { ensureCyrusGameMod, loadChain, rootOf } from "./registry";

/**
 * Create (first successful version) or refresh (every later version) the page
 * for a build's chain. Private by default. Never throws for the caller: a page
 * failure must not fail a build.
 */
export async function syncCyrusModPage(rootBuildId: string): Promise<CyrusModPage | null> {
  try {
    const chain = await loadChain(rootBuildId);
    if (!chain.length) return null;
    const doc = buildModDoc(chain);
    if (!doc) return null;
    const existing = await db.cyrusModPage.findUnique({ where: { rootBuildId } });
    const data = {
      title: doc.name.slice(0, 80),
      tagline: doc.tagline,
      latestBuildId: doc.currentBuildId,
      latestVersion: doc.versions.find((v) => v.buildId === doc.currentBuildId)?.version ?? null,
      doc: doc as unknown as Prisma.InputJsonValue,
    };
    let page: CyrusModPage;
    if (existing) {
      page = await db.cyrusModPage.update({ where: { id: existing.id }, data });
    } else {
      const base = slugifyModName(doc.name);
      const taken = new Set((await db.cyrusModPage.findMany({ where: { slug: { startsWith: base.slice(0, 40) } }, select: { slug: true } })).map((r) => r.slug));
      const fork = await db.cyrusFork.findUnique({ where: { buildId: rootBuildId } }).catch(() => null);
      try {
        page = await db.cyrusModPage.create({
          data: { rootBuildId, userId: chain[0].userId, slug: uniqueSlug(base, taken), ...data, ...(fork ? { forkOfPageId: fork.sourcePageId, forkOfBuildId: fork.sourceBuildId } : {}) },
        });
      } catch {
        // Two syncs raced (sweep + an open page): the other one created it.
        const again = await db.cyrusModPage.findUnique({ where: { rootBuildId } });
        if (!again) return null;
        page = await db.cyrusModPage.update({ where: { id: again.id }, data });
      }
    }
    // Keep the engine's GameMod (name/size/versions) in step when the mod has one.
    const gm = await db.gameMod.findFirst({ where: { source: "cyrus", sourceId: rootBuildId }, select: { id: true } });
    if (gm) await ensureCyrusGameMod(rootBuildId, chain).catch(() => null);
    return page;
  } catch (e) {
    console.error("[cyrus-mods] page sync failed", rootBuildId, (e as Error).message);
    return null;
  }
}

/** Hook for a build row that just changed (store.ts). Only a success creates/refreshes a page. */
export async function onBuildSettled(row: Pick<ModBuild, "id" | "rootBuildId" | "status">): Promise<void> {
  if (row.status !== "succeeded") return;
  await syncCyrusModPage(rootOf(row));
}

export type PageView = {
  id: string;
  slug: string;
  title: string;
  tagline: string | null;
  visibility: "PRIVATE" | "PUBLIC";
  license: string;
  hidden: boolean;
  hiddenReason: string | null;
  publishedAt: string | null;
  updatedAt: string;
  createdAt: string;
  creator: { id: string; name: string };
  isCreator: boolean;
  isAdmin: boolean;
  rootBuildId: string;
  doc: CyrusModDoc;
  forkOf: { slug: string; title: string } | null;
  forks: number;
  threads: { open: number; bugsOpen: number; total: number };
};

/** Public credit: the account's display name only — never any part of the email. */
export const displayUser = (u: { name: string | null } | null) => (u?.name?.trim() || "Nxeon customer").slice(0, 40);

export async function toPageView(page: CyrusModPage, viewer: { id: string; role?: string | null } | null): Promise<PageView | null> {
  const doc = readModDoc(page.doc);
  if (!doc) return null;
  const [creator, forkOf, forks, open, bugsOpen, total] = await Promise.all([
    db.user.findUnique({ where: { id: page.userId }, select: { name: true } }),
    page.forkOfPageId ? db.cyrusModPage.findUnique({ where: { id: page.forkOfPageId }, select: { slug: true, title: true, visibility: true, hiddenAt: true, userId: true } }) : null,
    db.cyrusFork.count({ where: { sourcePageId: page.id } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", hiddenAt: null } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, status: "OPEN", kind: "BUG", hiddenAt: null } }),
    db.cyrusModPost.count({ where: { pageId: page.id, parentId: null, hiddenAt: null } }),
  ]);
  return {
    id: page.id,
    slug: page.slug,
    title: page.title,
    tagline: page.tagline,
    visibility: page.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE",
    license: page.license,
    hidden: !!page.hiddenAt,
    hiddenReason: page.hiddenReason,
    publishedAt: page.publishedAt?.toISOString() ?? null,
    updatedAt: page.updatedAt.toISOString(),
    createdAt: page.createdAt.toISOString(),
    creator: { id: page.userId, name: displayUser(creator) },
    isCreator: !!viewer && viewer.id === page.userId,
    isAdmin: viewer?.role === "ADMIN",
    rootBuildId: page.rootBuildId,
    doc,
    // A fork's parent is only named when the viewer may see it.
    forkOf: forkOf && pageVisibleTo(forkOf, viewer) ? { slug: forkOf.slug, title: forkOf.title } : null,
    forks,
    threads: { open, bugsOpen, total },
  };
}

/** A page by slug, or null when it doesn't exist or this viewer may not see it. */
export async function pageForViewer(slug: string, viewer: { id: string; role?: string | null } | null): Promise<PageView | null> {
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  if (!page || !pageVisibleTo(page, viewer)) return null;
  return toPageView(page, viewer);
}

export type PageCard = { slug: string; title: string; tagline: string | null; creator: string; version: string | null; versions: number; mcVersions: string[]; commands: number; updatedAt: string; visibility: string; mine: boolean; bugsOpen: number };

/** The NxLabs "Cyrus Mods" listing: public pages, plus the viewer's own (private included). */
export async function listPageCards(viewer: { id: string } | null, opts: { q?: string; mineOnly?: boolean; take?: number } = {}): Promise<PageCard[]> {
  const q = (opts.q ?? "").trim().slice(0, 60);
  const visible: Prisma.CyrusModPageWhereInput = opts.mineOnly && viewer
    ? { userId: viewer.id }
    : { OR: [{ visibility: "PUBLIC", hiddenAt: null }, ...(viewer ? [{ userId: viewer.id }] : [])] };
  const where: Prisma.CyrusModPageWhereInput = q ? { AND: [visible, { OR: [{ title: { contains: q, mode: "insensitive" } }, { tagline: { contains: q, mode: "insensitive" } }] }] } : visible;
  const rows = await db.cyrusModPage.findMany({ where, orderBy: { updatedAt: "desc" }, take: Math.min(60, opts.take ?? 24) });
  const users = await db.user.findMany({ where: { id: { in: [...new Set(rows.map((r) => r.userId))] } }, select: { id: true, name: true } });
  const bugs = rows.length ? await db.cyrusModPost.groupBy({ by: ["pageId"], where: { pageId: { in: rows.map((r) => r.id) }, parentId: null, kind: "BUG", status: "OPEN", hiddenAt: null }, _count: { _all: true } }) : [];
  return rows.flatMap((r) => {
    const d = readModDoc(r.doc);
    if (!d) return [];
    return [{
      slug: r.slug,
      title: r.title,
      tagline: r.tagline,
      creator: displayUser(users.find((u) => u.id === r.userId) ?? null),
      version: r.latestVersion,
      versions: d.versions.length,
      mcVersions: d.compat.mcVersions,
      commands: d.commands.length,
      updatedAt: r.updatedAt.toISOString(),
      visibility: r.visibility,
      mine: !!viewer && r.userId === viewer.id,
      bugsOpen: bugs.find((b) => b.pageId === r.id)?._count._all ?? 0,
    }];
  });
}

/** Self-heal: make sure every finished chain the user owns has a page (old builds predate this). */
export async function backfillUserPages(userId: string): Promise<number> {
  const roots = await db.modBuild.findMany({ where: { userId, status: "succeeded" }, select: { id: true, rootBuildId: true }, take: 200 });
  const ids = [...new Set(roots.map((r) => r.rootBuildId ?? r.id))];
  const have = new Set((await db.cyrusModPage.findMany({ where: { rootBuildId: { in: ids } }, select: { rootBuildId: true } })).map((p) => p.rootBuildId));
  let n = 0;
  for (const id of ids) if (!have.has(id) && (await syncCyrusModPage(id))) n++;
  return n;
}

/** Public slugs for the sitemap (only used when launched). */
export async function publicPageSlugs(): Promise<{ slug: string; updatedAt: Date }[]> {
  return db.cyrusModPage.findMany({ where: { visibility: "PUBLIC", hiddenAt: null }, select: { slug: true, updatedAt: true }, orderBy: { updatedAt: "desc" }, take: 5000 });
}
// Cyrus mods <-> the mods engine: the GameMod row that stands for a Cyrus mod,
// and the jar source the engine's "cyrus" resolver reads from.
// Plain module (no next/* imports): the worker imports it too.
import type { GameMod, ModBuild } from "@prisma/client";
import { readFile } from "node:fs/promises";
import { db } from "../db";
import { CYRUS_SOURCE, type CyrusJar } from "../mods/installers/cyrus";
import { currentVersion, displayName, packageVersionFor, succeededVersions, readModDoc } from "./doc";
export { packageVersionFor } from "./doc";

export const cyrusModSlug = (rootBuildId: string) => `cyrus-${rootBuildId}`.toLowerCase().replace(/[^a-z0-9-]/g, "-").slice(0, 80);

/** Every build of a chain (root + its versions), oldest first. */
export async function loadChain(rootBuildId: string): Promise<ModBuild[]> {
  return db.modBuild.findMany({ where: { OR: [{ id: rootBuildId }, { rootBuildId }] }, orderBy: { createdAt: "asc" } });
}

/** The chain root of a build (self for v1 / old rows without rootBuildId). */
export const rootOf = (b: Pick<ModBuild, "id" | "rootBuildId">) => b.rootBuildId ?? b.id;

/**
 * The GameMod row the mods engine knows this Cyrus mod by (created on first
 * install, refreshed after every new version). Never listed in the catalogue:
 * active=false, and every catalogue query filters active=true.
 */
export async function ensureCyrusGameMod(rootBuildId: string, chain?: ModBuild[]): Promise<GameMod | null> {
  const builds = chain ?? (await loadChain(rootBuildId));
  const cur = currentVersion(builds);
  if (!cur) return null;
  const page = await db.cyrusModPage.findUnique({ where: { rootBuildId } }).catch(() => null);
  const doc = page ? readModDoc(page.doc) : null;
  const name = displayName(builds);
  const owner = await db.user.findUnique({ where: { id: builds[0].userId }, select: { name: true } }).catch(() => null);
  const data = {
    name,
    category: "Plugins",
    description: doc?.tagline ?? null,
    loaders: ["paper", "purpur"],
    gameVersions: [...new Set(succeededVersions(builds).map((b) => b.mcVersion))],
    serverSide: "required",
    fileBytes: cur.jarSize ?? null,
    license: page?.license ?? "MIT",
    authorName: owner?.name ?? null,
    url: page ? `/dashboard/nxlabs/cyrus/${page.slug}` : null,
  };
  return db.gameMod.upsert({
    where: { gameFamily_slug: { gameFamily: "minecraft", slug: cyrusModSlug(rootBuildId) } },
    create: { gameFamily: "minecraft", slug: cyrusModSlug(rootBuildId), source: CYRUS_SOURCE, sourceId: rootBuildId, active: false, impact: "light", ...data },
    update: data,
  });
}

/** Engine jar source: the build to place, checked against the server's owner. */
export async function loadCyrusJar(args: { rootBuildId: string; targetBuildId: string | null; serverId: string }): Promise<CyrusJar | { error: string }> {
  const [chain, server] = await Promise.all([
    loadChain(args.rootBuildId),
    db.server.findUnique({ where: { id: args.serverId }, select: { userId: true } }),
  ]);
  if (!chain.length || !server) return { error: "This Cyrus mod's build history wasn't found." };
  // Owner check: only the creator's own servers take their builds (forks are the forker's own copies).
  if (chain[0].userId !== server.userId) return { error: "This Cyrus mod belongs to another account." };
  const ok = succeededVersions(chain);
  const build = args.targetBuildId ? ok.find((b) => b.id === args.targetBuildId) : currentVersion(chain);
  if (!build) return { error: args.targetBuildId ? "That version isn't a finished build of this mod." : "This Cyrus mod has no finished version yet." };
  if (!build.jarPath || !build.jarName) return { error: "That version has no plugin file." };
  let bytes: Buffer;
  try {
    bytes = await readFile(build.jarPath);
  } catch {
    return { error: "The plugin file for that version is missing from storage. Rebuild it in Cyrus." };
  }
  return {
    build: { id: build.id, version: build.version, pluginName: build.pluginName, jarName: build.jarName, jarSha256: build.jarSha256, mcVersion: build.mcVersion },
    name: displayName(chain),
    packageVersion: packageVersionFor(build, chain),
    bytes,
  };
}

/**
 * The id the BUILD SERVICE knows a build by. A fork copy ("Build on this mod")
 * is a portal-side row; its source lives on the service under the original
 * build's id (CyrusFork.sourceBuildId, already resolved through earlier forks).
 */
export async function serviceBuildId(buildId: string): Promise<string> {
  const f = await db.cyrusFork.findUnique({ where: { buildId }, select: { sourceBuildId: true } }).catch(() => null);
  return f?.sourceBuildId ?? buildId;
}
// Cyrus mods on ONE server: what the Mods tab shows next to a Cyrus row
// (installed version, newer version, history with notes) and the pre-engine
// builder installs it can start tracking. Server-only (DB), no next/* imports.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { CYRUS_SOURCE } from "../mods/installers/cyrus";
import { buildModDoc, currentVersion, succeededVersions, versionLabel } from "./doc";
import { packageVersionFor } from "./registry";

export type CyrusRowInfo = {
  rootBuildId: string;
  /** The build on the server now (ServerMod.versionId), when known. */
  installedBuildId: string | null;
  installedLabel: string | null;
  /** The chain's current version (the creator's restored head, else the newest). */
  latestBuildId: string;
  latestLabel: string;
  /** Package version string of the latest (what ServerMod.version would read after updating). */
  latestPackageVersion: string;
  updateAvailable: boolean;
  versionCount: number;
  /** NxLabs page slug (the page exists for every finished chain). */
  pageSlug: string | null;
};

export type CyrusVersionRow = {
  buildId: string;
  label: string;
  version: string | null;
  mcVersion: string;
  at: string;
  notes: string;
  request: string;
  installed: boolean;
  latest: boolean;
  safety: "pass" | "warn" | "block" | null;
};

async function chainsFor(roots: string[]): Promise<Map<string, ModBuild[]>> {
  const rows = roots.length ? await db.modBuild.findMany({ where: { OR: [{ id: { in: roots } }, { rootBuildId: { in: roots } }] }, orderBy: { createdAt: "asc" } }) : [];
  const out = new Map<string, ModBuild[]>();
  for (const b of rows) {
    const r = b.rootBuildId ?? b.id;
    out.set(r, [...(out.get(r) ?? []), b]);
  }
  return out;
}

/** Per-ServerMod Cyrus facts for the rows that are Cyrus mods (keyed by GameMod id). */
export async function cyrusInfoForRows(rows: { modId: string; versionId: string | null; mod: { source: string; sourceId: string | null } }[]): Promise<Map<string, CyrusRowInfo>> {
  const cy = rows.filter((r) => r.mod.source === CYRUS_SOURCE && r.mod.sourceId);
  const out = new Map<string, CyrusRowInfo>();
  if (!cy.length) return out;
  const roots = [...new Set(cy.map((r) => r.mod.sourceId!))];
  const [chains, pages] = await Promise.all([
    chainsFor(roots),
    db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } }, select: { rootBuildId: true, slug: true } }),
  ]);
  for (const r of cy) {
    const chain = chains.get(r.mod.sourceId!) ?? [];
    const ok = succeededVersions(chain);
    const cur = currentVersion(chain);
    if (!cur) continue;
    const idx = (id: string | null) => ok.findIndex((b) => b.id === id);
    const label = (id: string | null) => {
      const i = idx(id);
      return i < 0 ? null : versionLabel({ n: i + 1, version: ok[i].version });
    };
    out.set(r.modId, {
      rootBuildId: r.mod.sourceId!,
      installedBuildId: r.versionId,
      installedLabel: label(r.versionId),
      latestBuildId: cur.id,
      latestLabel: label(cur.id) ?? "latest",
      latestPackageVersion: packageVersionFor(cur, chain),
      updateAvailable: !!r.versionId && r.versionId !== cur.id,
      versionCount: ok.length,
      pageSlug: pages.find((p) => p.rootBuildId === r.mod.sourceId)?.slug ?? null,
    });
  }
  return out;
}

/** Version history of a Cyrus mod with release notes, newest first, marked against what's on the server. */
export async function cyrusVersionHistory(rootBuildId: string, installedBuildId: string | null): Promise<CyrusVersionRow[]> {
  const chain = (await chainsFor([rootBuildId])).get(rootBuildId) ?? [];
  const doc = buildModDoc(chain);
  if (!doc) return [];
  return doc.versions.map((v) => ({
    buildId: v.buildId,
    label: versionLabel(v),
    version: v.version,
    mcVersion: v.mcVersion,
    at: v.at,
    notes: v.notes,
    request: v.request,
    installed: v.buildId === installedBuildId,
    latest: v.buildId === doc.currentBuildId,
    safety: v.safety,
  }));
}

export type UntrackedCyrus = { buildId: string; name: string; version: string | null; at: string };

/**
 * Builds a pre-engine builder install put on this server that the Mods tab
 * can't manage yet (no ServerMod row): newest per chain.
 */
export async function untrackedCyrusInstalls(serverId: string, userId: string): Promise<UntrackedCyrus[]> {
  const builds = await db.modBuild.findMany({ where: { userId, status: "succeeded" }, orderBy: { createdAt: "desc" }, take: 200 });
  const here = builds.filter((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (!here.length) return [];
  const tracked = new Set(
    (await db.serverMod.findMany({ where: { serverId, mod: { source: CYRUS_SOURCE } }, select: { mod: { select: { sourceId: true } } } })).map((r) => r.mod.sourceId),
  );
  const seen = new Set<string>();
  const out: UntrackedCyrus[] = [];
  for (const b of here) {
    const root = b.rootBuildId ?? b.id;
    if (tracked.has(root) || seen.has(root)) continue;
    seen.add(root);
    out.push({ buildId: b.id, name: b.pluginName ?? "Cyrus mod", version: b.version, at: ((b.lastInstall as { at?: string }).at ?? b.createdAt.toISOString()) });
  }
  return out;
}

// Cyrus mod community: the PURE rules (client-safe, unit-tested). Notes, bug
// reports and fixes are threads on a mod page; comments sit under a thread.
// The server actions (lib/actions-cyrus-mods.ts) enforce every rule here.

export const POST_KINDS = ["NOTE", "BUG", "FIX"] as const;
export type PostKind = (typeof POST_KINDS)[number];
export const KIND_LABEL: Record<PostKind, string> = { NOTE: "Note", BUG: "Bug report", FIX: "Fix" };

export const LIMITS = {
  titleMax: 120,
  bodyMin: 3,
  bodyMax: 5000,
  reasonMax: 300,
  /** Per user, rolling windows (checked against the DB, so they hold across processes). */
  threadsPerHour: 5,
  commentsPerHour: 30,
  reportsPerDay: 20,
  /** A post this many distinct viewers reported is hidden until a moderator looks. */
  autoHideReports: 3,
};

export type PostInput = { kind?: unknown; title?: unknown; body?: unknown; buildId?: unknown; parentId?: unknown };
export type CleanPost = { kind: PostKind; title: string | null; body: string; buildId: string | null; parentId: string | null };

const ctrl = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;

/** Validate a new thread/comment. `versionIds` = the page's version build ids. */
export function validatePost(input: PostInput, versionIds: string[]): { ok: true; post: CleanPost } | { ok: false; error: string } {
  const parentId = typeof input.parentId === "string" && /^[A-Za-z0-9_-]{1,40}$/.test(input.parentId) ? input.parentId : null;
  const kind = (typeof input.kind === "string" ? input.kind.toUpperCase() : "NOTE") as PostKind;
  if (!POST_KINDS.includes(kind)) return { ok: false, error: "Pick note, bug report or fix." };
  const body = typeof input.body === "string" ? input.body.replace(ctrl, "").replace(/\r\n/g, "\n").trim() : "";
  if (body.length < LIMITS.bodyMin) return { ok: false, error: "Write a little more." };
  if (body.length > LIMITS.bodyMax) return { ok: false, error: `Keep it under ${LIMITS.bodyMax.toLocaleString("en-US")} characters.` };
  let title: string | null = null;
  if (!parentId) {
    title = typeof input.title === "string" ? input.title.replace(ctrl, "").replace(/\s+/g, " ").trim() : "";
    if (title.length < 3) return { ok: false, error: "Give it a short title." };
    if (title.length > LIMITS.titleMax) return { ok: false, error: `Keep the title under ${LIMITS.titleMax} characters.` };
  }
  let buildId: string | null = null;
  if (input.buildId !== undefined && input.buildId !== null && input.buildId !== "") {
    if (typeof input.buildId !== "string" || !versionIds.includes(input.buildId)) return { ok: false, error: "Pick one of this mod's versions." };
    buildId = input.buildId;
  }
  if (kind === "BUG" && !parentId && !buildId && versionIds.length > 1) return { ok: false, error: "Say which version has the bug." };
  return { ok: true, post: { kind, title, body, buildId, parentId } };
}

export type Viewer = { id: string; role?: string | null } | null;
export type PageOwner = { userId: string };
export type PostOwner = { userId: string; parentId: string | null };

const isAdmin = (v: Viewer) => v?.role === "ADMIN";
/** The mod's creator and admins moderate a page's community. */
export const canModerate = (v: Viewer, page: PageOwner) => !!v && (v.id === page.userId || isAdmin(v));
/** Resolve / reopen a thread: its author, the creator, an admin. */
export const canResolve = (v: Viewer, page: PageOwner, post: PostOwner) => !!v && !post.parentId && (v.id === post.userId || canModerate(v, page));
/** Delete: the author (own post), the creator, an admin. */
export const canDelete = (v: Viewer, page: PageOwner, post: PostOwner) => !!v && (v.id === post.userId || canModerate(v, page));
/** Report: any signed-in viewer except the author. */
export const canReport = (v: Viewer, post: PostOwner) => !!v && v.id !== post.userId;

/** Who sees a hidden post: moderators, and its own author (marked hidden). */
export const hiddenVisibleTo = (v: Viewer, page: PageOwner, post: PostOwner) => !!v && (v.id === post.userId || canModerate(v, page));

/** Rate-limit decision from counts already read from the DB. */
export function rateLimited(kind: "thread" | "comment" | "report", recent: number): string | null {
  const max = kind === "thread" ? LIMITS.threadsPerHour : kind === "comment" ? LIMITS.commentsPerHour : LIMITS.reportsPerDay;
  if (recent < max) return null;
  return kind === "report" ? "You've sent a lot of reports today — thanks. Try again tomorrow." : `You're posting fast — try again in a while (up to ${max} ${kind === "thread" ? "new threads" : "comments"} an hour).`;
}

export function cleanReason(r: unknown): string | null {
  const s = typeof r === "string" ? r.replace(ctrl, "").replace(/\s+/g, " ").trim() : "";
  if (s.length < 3) return null;
  return s.slice(0, LIMITS.reasonMax);
}
// Cyrus mod pages: the PURE half (client-safe, unit-tested).
//
// A Cyrus mod is one ModBuild version chain (every version shares rootBuildId).
// Its NxLabs page is GENERATED from the chain's succeeded builds: nothing on it
// is hand-written or guessed. buildModDoc() turns the builds into the page body
// stored in CyrusModPage.doc; the server half (./pages.ts) calls it whenever a
// version finishes.
import type { MbCommand, MbConfig, MbPermission, ModBuildResult } from "../modbuilder/types";

/** Minimal ModBuild shape the generator reads (a Prisma ModBuild satisfies it). */
export type ChainBuild = {
  id: string;
  status: string;
  prompt: string;
  changeRequest: string | null;
  baseBuildId: string | null;
  rootBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  version: string | null;
  jarName: string | null;
  jarSize: number | null;
  jarSha256?: string | null;
  result: unknown;
  cyrus?: unknown;
  createdAt: Date;
  finishedAt: Date | null;
};

export type CyrusDocVersion = {
  buildId: string;
  /** 1-based position among the chain's succeeded versions, oldest first. */
  n: number;
  version: string | null;
  mcVersion: string;
  at: string;
  /** Release notes: the builder's own "what changed" summary, else the change request, else "First version". */
  notes: string;
  /** What the creator asked for (the change request; the original prompt for v1). */
  request: string;
  basedOn: string | null;
  jarName: string | null;
  jarSize: number | null;
  jarSha256: string | null;
  safety: "pass" | "warn" | "block" | null;
};

export type CyrusModDoc = {
  v: 1;
  name: string;
  pluginName: string | null;
  tagline: string | null;
  summary: string | null;
  howToUse: string[];
  limitations: string[];
  commands: MbCommand[];
  permissions: MbPermission[];
  config: MbConfig[];
  /** Server software + Minecraft versions the published builds target (newest first). */
  compat: { software: string[]; mcVersions: string[]; note: string };
  /** Newest first. */
  versions: CyrusDocVersion[];
  /** The version the page presents as current (the creator's restored head, else the newest). */
  currentBuildId: string | null;
  /** Source files of the current version (src/** only, no build output). */
  files: { path: string; size: number }[];
  generatedAt: string;
};

/** What a Cyrus plugin runs on: generated plugins target the Paper API (lib/modbuilder/install.ts MB_INSTALL_VARIANTS). */
