const clip = (s: unknown, n: number) => (typeof s === "string" ? s.trim().slice(0, n) : "");
const strArr = (a: unknown, max: number, len: number) => (Array.isArray(a) ? a.filter((x) => typeof x === "string").map((x) => (x as string).trim().slice(0, len)).filter(Boolean).slice(0, max) : []);

function cleanResult(raw: unknown): ModBuildResult | null {
  if (!raw || typeof raw !== "object") return null;
  return raw as ModBuildResult;
}

function metaOf(raw: unknown): { title?: string; headBuildId?: string } {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const r = raw as Record<string, unknown>;
  return {
    title: typeof r.title === "string" && r.title.trim() ? r.title.trim().slice(0, 60) : undefined,
    headBuildId: typeof r.headBuildId === "string" ? r.headBuildId : undefined,
  };
}

/** Succeeded builds of a chain, oldest first. */
export function succeededVersions<T extends ChainBuild>(chain: T[]): T[] {
  return chain.filter((b) => b.status === "succeeded" && !!b.jarName).sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
}

/** The build the chain presents as current: the restored head when it succeeded, else the newest success. */
export function currentVersion<T extends ChainBuild>(chain: T[]): T | null {
  const ok = succeededVersions(chain);
  if (!ok.length) return null;
  const root = chain.find((b) => b.id === (chain[0]?.rootBuildId ?? chain[0]?.id)) ?? chain.find((b) => b.rootBuildId === b.id || !b.baseBuildId);
  const head = metaOf(root?.cyrus).headBuildId;
  return ok.find((b) => b.id === head) ?? ok[ok.length - 1];
}

export function displayName(chain: ChainBuild[]): string {
  const root = chain.find((b) => !b.baseBuildId) ?? chain[0];
  const t = metaOf(root?.cyrus).title;
  const cur = currentVersion(chain);
  return t || cur?.pluginName || root?.pluginName || "Untitled Cyrus mod";
}

/** Generate the page body from a chain (pure). Returns null while no version has succeeded. */
export function buildModDoc(chain: ChainBuild[], now = new Date()): CyrusModDoc | null {
  const ok = succeededVersions(chain);
  const cur = currentVersion(chain);
  if (!cur) return null;
  const r = cleanResult(cur.result);
  const s = r?.summary ?? null;
  const versions: CyrusDocVersion[] = ok.map((b, i) => {
    const br = cleanResult(b.result);
    const changes = clip(br?.summary?.changes, 1200);
    return {
      buildId: b.id,
      n: i + 1,
      version: b.version,
      mcVersion: b.mcVersion,
      at: (b.finishedAt ?? b.createdAt).toISOString(),
      notes: changes || (b.changeRequest ? clip(b.changeRequest, 1200) : i === 0 ? "First version." : "Rebuilt."),
      request: clip(b.changeRequest ?? b.prompt, 2000),
      basedOn: b.baseBuildId,
      jarName: b.jarName,
      jarSize: b.jarSize,
      jarSha256: b.jarSha256 ?? null,
      safety: br?.safety?.verdict ?? null,
    };
  }).reverse();
  const mc = [...new Set(ok.map((b) => b.mcVersion))].sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
  return {
    v: 1,
    name: displayName(chain),
    pluginName: cur.pluginName,
    tagline: clip(s?.tagline, 200) || null,
    summary: clip(s?.text, 4000) || null,
    howToUse: strArr(s?.howToUse, 20, 400),
    limitations: strArr(s?.limitations, 20, 400),
    commands: (r?.commands ?? []).slice(0, 60),
    permissions: (r?.permissions ?? []).slice(0, 80),
    config: (r?.config ?? []).slice(0, 80),
    compat: {
      software: [...CYRUS_SOFTWARE],
      mcVersions: mc,
      note: `Built against the Paper API for Minecraft ${cur.mcVersion}. Runs on Paper and Purpur; not on Spigot, Folia, Fabric or Forge.`,
    },
    versions,
    currentBuildId: cur.id,
    files: (r?.files ?? []).filter((f) => /^src\//.test(f.path)).slice(0, 200),
    generatedAt: now.toISOString(),
  };
}

/** Read a stored doc defensively (old shapes, partial rows). */
export function readModDoc(raw: unknown): CyrusModDoc | null {
  if (!raw || typeof raw !== "object" || (raw as { v?: unknown }).v !== 1) return null;
  const d = raw as CyrusModDoc;
  if (!Array.isArray(d.versions)) return null;
  return d;
}

/** URL slug from a mod name: lowercase kebab, 3-48 chars. */
export function slugifyModName(name: string): string {
  const s = name
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48)
    .replace(/-+$/g, "");
  return s.length >= 3 ? s : `cyrus-mod${s ? `-${s}` : ""}`;
}

/** Pick a free slug: base, base-2, base-3 ... (taken = existing slugs). */
export function uniqueSlug(base: string, taken: Set<string>): string {
  if (!taken.has(base)) return base;
  for (let i = 2; i < 1000; i++) {
    const s = `${base.slice(0, 44)}-${i}`;
    if (!taken.has(s)) return s;
  }
  return `${base.slice(0, 36)}-${Date.now().toString(36)}`;
}

/** Version label shown everywhere: "v3 · 1.2.0". */
export function versionLabel(v: { n: number; version: string | null }): string {
  return v.version ? `v${v.n} · ${v.version.replace(/^v/i, "")}` : `v${v.n}`;
}

/**
 * Pure: may this viewer see this page? Creator: always (gate permitting).
 * Admin: always. Everyone else: only PUBLIC and not hidden.
 */
export function pageVisibleTo(
  page: { userId: string; visibility: string; hiddenAt: Date | string | null },
  viewer: { id: string; role?: string | null } | null,
): boolean {
  if (viewer && (viewer.id === page.userId || viewer.role === "ADMIN")) return true;
  return page.visibility === "PUBLIC" && !page.hiddenAt;
}

/**
 * Package version shown on the server and used by the engine's idempotency
 * check: the build's version string, disambiguated when another succeeded
 * version of the chain carries the same string (branches can repeat "1.1.0").
 */
export function packageVersionFor(build: { id: string; version: string | null }, chain: { id: string; version: string | null; status: string; jarName: string | null }[]): string {
  const v = (build.version || "1.0.0").replace(/^v/i, "");
  const dup = chain.some((b) => b.id !== build.id && b.status === "succeeded" && !!b.jarName && (b.version || "1.0.0").replace(/^v/i, "") === v);
  return dup ? `${v}+${build.id.slice(-6)}` : v;
}
/**
 * The ONE switch for every public/community Cyrus-mods surface (NxLabs
 * "Cyrus Mods" section, /mods/cyrus/**, /dashboard/nxlabs/cyrus/**, the
 * community layer, public source/jar downloads, fork).
 *
 * A viewer may see them when EITHER
 *   - Setting cyrus_mods_public_enabled is on (the owner's launch), OR
 *   - they are a private-preview account for "modbuilder" (lib/preview-access.ts;
 *     default: the owner's own customer account).
 * Everyone else gets a plain 404, exactly as if the route did not exist.
 *
 * Indexing: noindex + absent from the sitemap unless the PUBLIC flag is on.
 * A page is listed only when its creator made it PUBLIC and no admin hid it;
 * a creator always sees their own pages (private ones included) while they
 * pass the gate. Fails CLOSED on any DB error.
 */
import { notFound } from "next/navigation";
import { getSettingBool } from "../settings";
import { currentUser } from "../auth";
import { isPreviewUser } from "../preview-access";
export { pageVisibleTo } from "./doc";

export const CYRUS_MODS_PUBLIC_FLAG = "cyrus_mods_public_enabled";
export const CYRUS_PUBLIC_BASE = "/mods/cyrus";
export const CYRUS_PORTAL_BASE = "/dashboard/nxlabs/cyrus";

/** Pure decision (unit-tested). */
export function cyrusRouteDecision(flagOn: boolean, previewUser: boolean): "render" | "not-found" {
  return flagOn || previewUser ? "render" : "not-found";
}

export async function cyrusModsPublicEnabled(): Promise<boolean> {
  try {
    return await getSettingBool(CYRUS_MODS_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

export type CyrusAccess = { allowed: boolean; isPublic: boolean; preview: boolean };

export async function cyrusAccessFor(user: { email?: string | null } | null | undefined): Promise<CyrusAccess> {
  const isPublic = await cyrusModsPublicEnabled();
  const preview = !isPublic && (await isPreviewUser(user, "modbuilder"));
  return { allowed: cyrusRouteDecision(isPublic, preview) === "render", isPublic, preview };
}

async function safeUser() {
  try {
    return await currentUser();
  } catch {
    return null;
  }
}

/** Route guard: 404 unless the viewer may see Cyrus mods. Returns the viewer (may be null once launched). */
export async function requireCyrusAccess() {
  const user = await safeUser();
  const access = await cyrusAccessFor(user);
  if (!access.allowed) notFound();
  return { user, access };
}

/** Metadata for gated pages: names the page only when allowed; noindex until launch. */
export async function cyrusMetadata(title: string, description?: string) {
  const user = await safeUser();
  const a = await cyrusAccessFor(user);
  if (!a.allowed) return { title: "Page not found", robots: { index: false, follow: false } };
  return { title, description, robots: a.isPublic ? undefined : { index: false, follow: false } };
}

/** Sitemap paths: only when launched (the caller adds each public page). */
export function cyrusSitemapPaths(flagOn: boolean, slugs: string[]): string[] {
  return flagOn ? [CYRUS_PUBLIC_BASE, ...slugs.map((s) => `${CYRUS_PUBLIC_BASE}/${s}`)] : [];
}

"use server";

/**
 * Cyrus mod pages + community (server actions). Gated end to end by
 * lib/cyrus-mods/gate.ts (launch flag OR the modbuilder private preview): a
 * viewer outside the gate gets "Not found" from every action, exactly like the
 * routes. Pages are private until their creator publishes them; the rules for
 * who may post, resolve, report, hide and delete live in
 * lib/cyrus-mods/community.ts (pure, tested).
 */
import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { copyFile, mkdir } from "node:fs/promises";
import type { CyrusModPage, CyrusModPost, Prisma, User } from "@prisma/client";
import { db } from "./db";
import { currentUser, realUser } from "./auth";
import { cyrusAccessFor, pageVisibleTo } from "./cyrus-mods/gate";
import { isCyrusLicense, readModDoc, versionLabel } from "./cyrus-mods/doc";
import { canDelete, canModerate, canReport, canResolve, cleanReason, hiddenVisibleTo, LIMITS, rateLimited, validatePost, type PostKind } from "./cyrus-mods/community";
import { displayUser, syncCyrusModPage } from "./cyrus-mods/pages";
import { loadChain, serviceBuildId } from "./cyrus-mods/registry";
import { currentVersion, succeededVersions } from "./cyrus-mods/doc";
import { modBuilderUser } from "./modbuilder/access";
import { jarPathFor, MODBUILD_DIR } from "./modbuilder/store";

const NF = { error: "Not found." } as const;

/**
 * The viewer + gate. `user` is null for WRITES while an admin is viewing as a
 * customer (impersonation must never post, publish or fork in their name);
 * reads still see what the customer sees.
 */
async function requireViewer(mode: "read" | "write" = "write"): Promise<{ user: User | null; allowed: boolean }> {
  let user: User | null = null;
  let real: User | null = null;
  try {
    [user, real] = await Promise.all([currentUser(), realUser()]);
  } catch {
    user = null;
  }
  const a = await cyrusAccessFor(user);
  if (mode === "write" && user && (!real || real.id !== user.id)) return { user: null, allowed: a.allowed };
  return { user, allowed: a.allowed };
}

async function pageFor(slug: unknown, user: User | null): Promise<CyrusModPage | null> {
  if (typeof slug !== "string" || !/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  return page && pageVisibleTo(page, user) ? page : null;
}

function revalidate(slug: string) {
  revalidatePath(`/dashboard/nxlabs/cyrus/${slug}`);
  revalidatePath(`/mods/cyrus/${slug}`);
}

// ── community: read ─────────────────────────────────────────────────────────

export type PostView = {
  id: string;
  kind: PostKind;
  status: "OPEN" | "RESOLVED";
  title: string | null;
  body: string;
  buildId: string | null;
  version: string | null;
  author: string;
  byCreator: boolean;
  createdAt: string;
  resolvedAt: string | null;
  hidden: boolean;
  hiddenReason: string | null;
  mine: boolean;
  can: { resolve: boolean; delete: boolean; report: boolean; hide: boolean };
  reportedByMe: boolean;
  reportCount: number | null;
  comments: PostView[];
};

export type CommunityView = { threads: PostView[]; canPost: boolean; signInHint: string | null; versions: { buildId: string; label: string }[]; moderator: boolean };

export async function getCommunity(slug: string): Promise<{ error?: string; view?: CommunityView }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed) return NF;
  const page = await pageFor(slug, user);
  if (!page) return NF;
  const doc = readModDoc(page.doc);
  const labels = new Map((doc?.versions ?? []).map((v) => [v.buildId, versionLabel(v)]));
  const posts = await db.cyrusModPost.findMany({ where: { pageId: page.id }, orderBy: { createdAt: "asc" }, take: 600 });
  const authors = await db.user.findMany({ where: { id: { in: [...new Set(posts.map((p) => p.userId))] } }, select: { id: true, name: true } });
  const mine = user ? new Set((await db.cyrusModReport.findMany({ where: { userId: user.id, postId: { in: posts.map((p) => p.id) } }, select: { postId: true } })).map((r) => r.postId)) : new Set<string>();
  const mod = canModerate(user, page);
  const toView = (p: CyrusModPost): PostView => ({
    id: p.id,
    kind: (["NOTE", "BUG", "FIX"].includes(p.kind) ? p.kind : "NOTE") as PostKind,
    status: p.status === "RESOLVED" ? "RESOLVED" : "OPEN",
    title: p.title,
    body: p.hiddenAt && !hiddenVisibleTo(user, page, p) ? "" : p.body,
    buildId: p.buildId,
    version: p.buildId ? labels.get(p.buildId) ?? null : null,
    author: displayUser(authors.find((a) => a.id === p.userId) ?? null),
    byCreator: p.userId === page.userId,
    createdAt: p.createdAt.toISOString(),
    resolvedAt: p.resolvedAt?.toISOString() ?? null,
    hidden: !!p.hiddenAt,
    hiddenReason: mod ? p.hiddenReason : p.hiddenAt ? "Hidden by a moderator" : null,
    mine: !!user && p.userId === user.id,
    can: { resolve: canResolve(user, page, p), delete: canDelete(user, page, p), report: canReport(user, p) && !mine.has(p.id), hide: mod },
    reportedByMe: mine.has(p.id),
    reportCount: mod ? p.reportCount : null,
    comments: [],
  });
  const visible = posts.filter((p) => !p.hiddenAt || hiddenVisibleTo(user, page, p));
  const threads = visible.filter((p) => !p.parentId).map(toView);
  const byId = new Map(threads.map((t) => [t.id, t]));
  for (const c of visible.filter((p) => p.parentId)) byId.get(c.parentId!)?.comments.push(toView(c));
  threads.reverse(); // newest thread first; comments oldest first
  return {
    view: {
      threads,
      canPost: !!user && !!user.emailVerifiedAt,
      signInHint: !user ? "Sign in to post notes, bug reports and fixes." : !user.emailVerifiedAt ? "Verify your email to post." : null,
      versions: (doc?.versions ?? []).map((v) => ({ buildId: v.buildId, label: versionLabel(v) })),
      moderator: mod,
    },
  };
}

// ── community: write ────────────────────────────────────────────────────────

export async function createCyrusPost(slug: string, input: { kind?: string; title?: string; body?: string; buildId?: string | null; parentId?: string | null }): Promise<{ ok?: true; error?: string; id?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed) return NF;
  if (!user) return { error: "Sign in to post." };
  if (!user.emailVerifiedAt) return { error: "Verify your email to post." };
  const page = await pageFor(slug, user);
  if (!page) return NF;
  const doc = readModDoc(page.doc);
  const v = validatePost(input, (doc?.versions ?? []).map((x) => x.buildId));
  if (!v.ok) return { error: v.error };
  if (v.post.parentId) {
    const parent = await db.cyrusModPost.findUnique({ where: { id: v.post.parentId } });
    if (!parent || parent.pageId !== page.id || parent.parentId) return { error: "That thread no longer exists." };
    if (parent.hiddenAt && !canModerate(user, page)) return { error: "That thread is hidden." };
  }
  const since = new Date(Date.now() - 3600_000);
  const recent = await db.cyrusModPost.count({ where: { userId: user.id, createdAt: { gte: since }, parentId: v.post.parentId ? { not: null } : null } });
  const limited = rateLimited(v.post.parentId ? "comment" : "thread", recent);
  if (limited) return { error: limited };
  const p = await db.cyrusModPost.create({ data: { pageId: page.id, userId: user.id, ...v.post } });
  await db.auditLog.create({ data: { userId: user.id, action: "cyrusmods.post", detail: `${page.slug} ${p.id} ${v.post.kind}${v.post.parentId ? ` reply-to=${v.post.parentId}` : ""}` } }).catch(() => {});
  revalidate(page.slug);
  return { ok: true, id: p.id };
}

async function postAndPage(postId: unknown, user: User | null) {
  if (typeof postId !== "string" || !/^[A-Za-z0-9_-]{1,40}$/.test(postId)) return null;
  const post = await db.cyrusModPost.findUnique({ where: { id: postId } });
  if (!post) return null;
  const page = await db.cyrusModPage.findUnique({ where: { id: post.pageId } });
  if (!page || !pageVisibleTo(page, user)) return null;
  return { post, page };
}

export async function setCyrusPostStatus(postId: string, status: "OPEN" | "RESOLVED"): Promise<{ ok?: true; error?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const pp = await postAndPage(postId, user);
  if (!pp) return NF;
  if (!canResolve(user, pp.page, pp.post)) return { error: "Only the author, the mod's creator or Nxeon can change this." };
  if (status !== "OPEN" && status !== "RESOLVED") return { error: "Bad status." };
  await db.cyrusModPost.update({ where: { id: pp.post.id }, data: { status, resolvedAt: status === "RESOLVED" ? new Date() : null, resolvedById: status === "RESOLVED" ? user.id : null } });
  revalidate(pp.page.slug);
  return { ok: true };
}

export async function reportCyrusPost(postId: string, reason: string): Promise<{ ok?: true; error?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const pp = await postAndPage(postId, user);
  if (!pp) return NF;
  if (!canReport(user, pp.post)) return { error: "You can't report your own post." };
  const why = cleanReason(reason);
  if (!why) return { error: "Say briefly what's wrong with it." };
  const today = await db.cyrusModReport.count({ where: { userId: user.id, createdAt: { gte: new Date(Date.now() - 86400_000) } } });
  const limited = rateLimited("report", today);
  if (limited) return { error: limited };
  try {
    await db.cyrusModReport.create({ data: { postId: pp.post.id, userId: user.id, reason: why } });
  } catch {
    return { error: "You've already reported this." };
  }
  const count = await db.cyrusModReport.count({ where: { postId: pp.post.id, resolvedAt: null } });
  const autoHide = count >= LIMITS.autoHideReports && !pp.post.hiddenAt;
  await db.cyrusModPost.update({ where: { id: pp.post.id }, data: { reportCount: count, ...(autoHide ? { hiddenAt: new Date(), hiddenReason: `Hidden after ${count} reports — waiting for review` } : {}) } });
  await db.auditLog.create({ data: { userId: user.id, action: "cyrusmods.report", detail: `${pp.page.slug} ${pp.post.id}: ${why}`.slice(0, 900) } }).catch(() => {});
  revalidate(pp.page.slug);
  return { ok: true };
}

export async function hideCyrusPost(postId: string, hidden: boolean, reason?: string): Promise<{ ok?: true; error?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const pp = await postAndPage(postId, user);
  if (!pp) return NF;
  if (!canModerate(user, pp.page)) return { error: "Only the mod's creator or Nxeon can hide posts." };
  await db.cyrusModPost.update({ where: { id: pp.post.id }, data: hidden ? { hiddenAt: new Date(), hiddenById: user.id, hiddenReason: cleanReason(reason) ?? "Hidden by a moderator" } : { hiddenAt: null, hiddenById: null, hiddenReason: null } });
  if (!hidden) await db.cyrusModReport.updateMany({ where: { postId: pp.post.id, resolvedAt: null }, data: { resolvedAt: new Date() } });
  await db.auditLog.create({ data: { userId: user.id, action: hidden ? "cyrusmods.hide" : "cyrusmods.unhide", detail: `${pp.page.slug} ${pp.post.id}` } }).catch(() => {});
  revalidate(pp.page.slug);
  return { ok: true };
}

export async function deleteCyrusPost(postId: string): Promise<{ ok?: true; error?: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const pp = await postAndPage(postId, user);
  if (!pp) return NF;
  if (!canDelete(user, pp.page, pp.post)) return { error: "You can only delete your own posts." };
  const ids = [pp.post.id, ...(pp.post.parentId ? [] : (await db.cyrusModPost.findMany({ where: { parentId: pp.post.id }, select: { id: true } })).map((c) => c.id))];
  await db.$transaction([db.cyrusModReport.deleteMany({ where: { postId: { in: ids } } }), db.cyrusModPost.deleteMany({ where: { id: { in: ids } } })]);
  await db.auditLog.create({ data: { userId: user.id, action: "cyrusmods.delete", detail: `${pp.page.slug} ${ids.join(",")} by ${pp.post.userId === user.id ? "author" : user.role === "ADMIN" ? "admin" : "creator"}` } }).catch(() => {});
  revalidate(pp.page.slug);
  return { ok: true };
}

