/** Public NxLabs → Cyrus Mods. 404 (and noindex, not in the sitemap) until Setting cyrus_mods_public_enabled, except for preview accounts. */
export default async function CyrusModsPublic({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  const { user, access } = await requireCyrusAccess();
  const q = String((await searchParams).q ?? "").slice(0, 60);
