            </p>
          </div>
          <div className="flex flex-none flex-wrap gap-2 sm:flex-col sm:items-stretch">
            {canFork ? <ForkButton slug={p.slug} label={p.isCreator ? "Open in Cyrus" : "Build on this mod"} /> : (
