"use client";

import { CY_CTA } from "./cta";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { adminHideCyrusPage, refreshCyrusPage, setCyrusPageLicense, setCyrusPageVisibility } from "@/lib/actions-cyrus-mods";
import { CYRUS_LICENSES } from "@/lib/cyrus-mods/doc";
import type { PageView } from "@/lib/cyrus-mods/pages";

/**
 * Creator controls: publish (explicit, private by default), licence, regenerate.
 * Admin: hide/unhide the whole page. Shown only to the creator and admins.
 */
export function CyrusOwnerPanel({ p }: { p: PageView }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [confirmPublish, setConfirmPublish] = useState(false);
  const router = useRouter();
  const run = (fn: () => Promise<{ error?: string }>, ok: string) =>
    start(async () => {
      setMsg(null);
      const r = await fn().catch(() => ({ error: "Couldn't reach Nxeon." }));
      setMsg(r.error ? { ok: false, text: r.error } : { ok: true, text: ok });
      router.refresh();
    });
  const pub = p.visibility === "PUBLIC";
  return (
    <section className="rounded-[16px] border border-violet/35 bg-violet/[0.05] p-4" aria-label="Your mod page" data-testid="cyrus-owner-panel">
      <div className="flex flex-wrap items-start gap-4">
        <div className="min-w-[min(100%,260px)] flex-1">
          <p className="text-[13.5px] font-extrabold text-tx">{p.isCreator ? "Your mod page" : "Moderation"}</p>
          <p className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">
            {p.isCreator
              ? pub ? "Public: anyone on NxLabs can read it, download the source and build on it." : "Private: only you can see this page. It updates itself every time you build a new version."
              : `Created by ${p.creator.name}. ${pub ? "Public." : "Private."}`}
          </p>
        </div>
        {p.isCreator && (
          <div className="flex flex-wrap items-center gap-2">
            <label className="flex items-center gap-2 whitespace-nowrap text-[12px] text-tx-dim">
              Licence
              <select value={p.license} disabled={pending} onChange={(e) => run(() => setCyrusPageLicense(p.slug, e.target.value), "Licence saved.")} className="input h-9 !w-auto py-1 text-[12.5px]">
                {CYRUS_LICENSES.map((l) => <option key={l.id} value={l.id}>{l.label}</option>)}
              </select>
            </label>
            <button type="button" disabled={pending} onClick={() => run(() => refreshCyrusPage(p.slug), "Regenerated from your builds.")} className="rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim hover:text-tx disabled:opacity-50">
              <Icon name="refresh" size={11} tone="inherit" className="mr-1 inline" />Regenerate
            </button>
            {pub ? (
              <button type="button" disabled={pending} onClick={() => run(() => setCyrusPageVisibility(p.slug, "PRIVATE"), "Back to private.")} className="rounded-[10px] border border-rim-hi bg-well px-3.5 py-1.5 text-[12.5px] font-semibold text-tx hover:border-violet/50 disabled:opacity-50">Make private</button>
            ) : (
              <button type="button" disabled={pending} onClick={() => setConfirmPublish(true)} className={`${CY_CTA} px-4 py-1.5 text-[12.5px] disabled:opacity-50`}>Publish to NxLabs…</button>
            )}
          </div>
        )}
        {p.isAdmin && (
          <button type="button" disabled={pending} onClick={() => run(() => adminHideCyrusPage(p.slug, !p.hidden, "Hidden by Nxeon"), p.hidden ? "Page visible again." : "Page hidden.")} className="rounded-[10px] border border-rose/40 bg-rose/10 px-3 py-1.5 text-[12px] font-semibold text-rose disabled:opacity-50">
            {p.hidden ? "Unhide page" : "Hide page (admin)"}
          </button>
        )}
      </div>
      {confirmPublish && (
        <div className="mt-3 rounded-[12px] border border-rim-hi bg-surface p-3.5" role="alertdialog" aria-label="Publish this mod">
          <p className="text-[13px] font-bold text-tx">Publish {p.title} to NxLabs?</p>
          <ul className="mt-1.5 flex list-disc flex-col gap-0.5 pl-5 text-[12px] leading-relaxed text-tx-dim">
            <li>Anyone can read the page and download the plugin and its full source, under {p.license}.</li>
            <li>Others can build their own versions on top of it (yours stays yours).</li>
            <li>Your display name is shown as the creator. Your email never is.</li>
            <li>You can make it private again at any time; copies already downloaded stay out there.</li>
          </ul>
          <div className="mt-3 flex gap-2">
            <button type="button" disabled={pending} onClick={() => { setConfirmPublish(false); run(() => setCyrusPageVisibility(p.slug, "PUBLIC"), "Published."); }} className={`${CY_CTA} px-4 py-1.5 text-[12.5px]`}>Publish</button>
            <button type="button" onClick={() => setConfirmPublish(false)} className="rounded-[10px] border border-rim-hi px-3 py-1.5 text-[12.5px] font-semibold text-tx-dim hover:text-tx">Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className={"mt-2 text-[12px] " + (msg.ok ? "text-mint" : "text-rose")} role="status">{msg.text}</p>}
    </section>
  );
}
"use client";

import { CY_CTA } from "./cta";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { forkCyrusMod } from "@/lib/actions-cyrus-mods";

/** "Build on this mod": opens Cyrus with this version as the base (a private copy for anyone but the creator). */
export function ForkButton({ slug, buildId, label = "Build on this mod", small = false }: { slug: string; buildId?: string; label?: string; small?: boolean }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const router = useRouter();
  const go = async () => {
    setBusy(true);
    setErr(null);
    const r = await forkCyrusMod(slug, buildId ?? null).catch(() => ({ error: "Couldn't reach Nxeon." }) as { error: string; href?: string });
    setBusy(false);
    if (r.error || !r.href) { setErr(r.error ?? "Couldn't start that."); return; }
    router.push(r.href);
  };
  return (
    <span className="inline-flex flex-col">
      <button type="button" onClick={go} disabled={busy}
        className={small ? "font-semibold text-violet hover:underline disabled:opacity-50" : `${CY_CTA} px-4 py-2 text-[12.5px] disabled:opacity-60`}>
        {busy ? "Opening Cyrus…" : label}
      </button>
      {err && <span className="mt-1 max-w-[240px] text-[11.5px] text-rose" role="alert">{err}</span>}
    </span>
  );
}
"use client";

import { useEffect, useState } from "react";

/** Overview / Versions / Community on a Cyrus mod page; the hash (#versions, #community) deep-links a tab. */
export function CyrusModTabs({ tabs }: { tabs: { key: string; label: string; node: React.ReactNode }[] }) {
  const [on, setOn] = useState(tabs[0]?.key);
  useEffect(() => {
    const h = window.location.hash.slice(1);
    if (tabs.some((t) => t.key === h)) setOn(h);
  }, [tabs]);
  const pick = (k: string) => {
    setOn(k);
    const url = new URL(window.location.href);
    url.hash = k === tabs[0]?.key ? "" : k;
    window.history.replaceState(window.history.state, "", url);
  };
  return (
    <div className="flex flex-col gap-4">
      <div className="flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-surface p-1" role="tablist" aria-label="Mod page">
        {tabs.map((t) => (
          <button key={t.key} type="button" role="tab" aria-selected={on === t.key} id={`cy-tab-${t.key}`} aria-controls={`cy-panel-${t.key}`} onClick={() => pick(t.key)}
            className={"flex-1 whitespace-nowrap rounded-[10px] px-3 py-2 text-[13px] font-bold transition " + (on === t.key ? "bg-[linear-gradient(120deg,#2f7eef,#8c3ae9)] text-[#fff]" : "text-tx-dim hover:bg-well hover:text-tx")}>
            {t.label}
          </button>
        ))}
      </div>
      {tabs.map((t) => (
        <div key={t.key} role="tabpanel" id={`cy-panel-${t.key}`} aria-labelledby={`cy-tab-${t.key}`} hidden={on !== t.key}>{t.node}</div>
      ))}
    </div>
  );
}
