// Cyrus: group a user's builds into projects (pure, client-safe, unit-tested).
// A project = one root build plus every change built on it (rootBuildId).
import { isTerminal, type ModBuildView } from "../modbuilder/types";
import { readCyrusMeta, type CyrusMeta } from "./meta";

export type CyrusProject = {
  rootId: string;
  /** Oldest first. */
  builds: ModBuildView[];
  latest: ModBuildView;
  /** The current version: the restored head if set, else the newest succeeded build. */
  head: ModBuildView | null;
  running: ModBuildView | null;
  meta: CyrusMeta;
  title: string;
  updatedAt: string;
};

export const viewMeta = (b: ModBuildView): CyrusMeta => readCyrusMeta(b.cyrus);

export function projectTitle(meta: CyrusMeta, head: ModBuildView | null, latest: ModBuildView): string {
  if (meta.title) return meta.title;
  const name = head?.pluginName || latest.pluginName;
  if (name) return spaced(name);
  return draftTitle(latest.prompt);
}

/** "DailyRewards" -> "Daily Rewards" (plugin names are PascalCase identifiers). */
export function spaced(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/_/g, " ").trim();
}

/** A short working title from the prompt, for builds that have no plugin name yet. */
export function draftTitle(prompt: string): string {
  let p = prompt.replace(/\s+/g, " ").trim();
  for (let i = 0; i < 3; i++) p = p.replace(/^(a|an|the|make|build|create|i want|please|me)\s+/i, "").replace(/^\/(?=\w)/, "");
  const cut = p.split(/[.:;!?]| - |, (?=[a-z])/)[0] || p;
  const words = cut.split(" ").slice(0, 5).join(" ");
  const t = words.length > 34 ? words.slice(0, 33).trimEnd() + "…" : words;
  return t ? t[0].toUpperCase() + t.slice(1) : "Untitled mod";
}

export function groupProjects(builds: ModBuildView[]): CyrusProject[] {
  const byRoot = new Map<string, ModBuildView[]>();
  for (const b of builds) {
    const r = b.rootBuildId || b.id;
    if (!byRoot.has(r)) byRoot.set(r, []);
    byRoot.get(r)!.push(b);
  }
  const out: CyrusProject[] = [];
  for (const [rootId, list] of byRoot) {
    list.sort((x, y) => x.createdAt.localeCompare(y.createdAt));
    const root = list.find((b) => b.id === rootId) ?? list[0];
    const meta = viewMeta(root);
    const latest = list[list.length - 1];
    const succeeded = list.filter((b) => b.status === "succeeded");
    const head = (meta.headBuildId && succeeded.find((b) => b.id === meta.headBuildId)) || succeeded[succeeded.length - 1] || null;
    const running = [...list].reverse().find((b) => !isTerminal(b.status)) ?? null;
    const updatedAt = list.reduce((m, b) => (b.finishedAt && b.finishedAt > m ? b.finishedAt : b.createdAt > m ? b.createdAt : m), "");
    out.push({ rootId, builds: list, latest, head, running, meta, title: projectTitle(meta, head, latest), updatedAt });
  }
  // Running first, then favourites, then most recent activity.
  out.sort((a, b) => (+!!b.running - +!!a.running) || (+!!b.meta.favourite - +!!a.meta.favourite) || b.updatedAt.localeCompare(a.updatedAt));
  return out;
}

/** 1-based version number of a build inside its project (every build counts, failed ones too). */
export function versionNumber(p: CyrusProject, buildId: string): number {
  return p.builds.findIndex((b) => b.id === buildId) + 1;
}

/** The project a build belongs to. */
export function projectOf(projects: CyrusProject[], buildId: string | null): CyrusProject | null {
  if (!buildId) return null;
  return projects.find((p) => p.builds.some((b) => b.id === buildId)) ?? null;
}

/** Stable small hash for per-project glyphs. */
export function hashSeed(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
// Cyrus metadata kept in ModBuild.cyrus (additive Json column). Client-safe.
//
// Per BUILD:   model (which Cyrus model was picked), attachments (pasted images).
// Per PROJECT: kept on the project's ROOT build only: title, favourite, notes,
//              headBuildId (the version the owner "restored" / marked current).
import { isCyrusModel, type CyrusModelId } from "./models";

export type CyrusAttachment = { n: number; name: string; type: string; size: number };

export type CyrusMeta = {
  model?: CyrusModelId;
  attachments?: CyrusAttachment[];
  title?: string;
  favourite?: boolean;
  notes?: string;
  headBuildId?: string;
};

export const CYRUS_NOTES_MAX = 4000;
export const CYRUS_TITLE_MAX = 60;

/** Read whatever is in the column into a clean CyrusMeta (never throws). */
export function readCyrusMeta(raw: unknown): CyrusMeta {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const r = raw as Record<string, unknown>;
  const out: CyrusMeta = {};
  if (isCyrusModel(r.model)) out.model = r.model;
  if (Array.isArray(r.attachments)) {
    out.attachments = r.attachments
      .filter((a): a is Record<string, unknown> => !!a && typeof a === "object")
      .map((a) => ({ n: Number(a.n) || 0, name: String(a.name ?? "image").slice(0, 120), type: String(a.type ?? ""), size: Number(a.size) || 0 }))
      .filter((a) => a.n > 0 && /^image\/(png|jpeg|webp|gif)$/.test(a.type))
      .slice(0, 8);
  }
  if (typeof r.title === "string" && r.title.trim()) out.title = r.title.trim().slice(0, CYRUS_TITLE_MAX);
  if (r.favourite === true) out.favourite = true;
  if (typeof r.notes === "string" && r.notes) out.notes = r.notes.slice(0, CYRUS_NOTES_MAX);
  if (typeof r.headBuildId === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(r.headBuildId)) out.headBuildId = r.headBuildId;
  return out;
}

export type ProjectPatch = { title?: string | null; favourite?: boolean; notes?: string; headBuildId?: string | null };

/**
 * Validate a PATCH body for project meta. Returns the patch or an error string.
 * `allowedHeads` = ids of the project's succeeded builds (a head must be one).
 */
export function parseProjectPatch(body: unknown, allowedHeads: string[]): { ok: true; patch: ProjectPatch } | { ok: false; error: string } {
  if (!body || typeof body !== "object") return { ok: false, error: "Bad request" };
  const b = body as Record<string, unknown>;
  const patch: ProjectPatch = {};
  if ("title" in b) {
    if (b.title === null || b.title === "") patch.title = null;
    else if (typeof b.title === "string") {
      const t = b.title.replace(/[\u0000-\u001f]/g, "").trim();
      if (t.length > CYRUS_TITLE_MAX) return { ok: false, error: `Keep the name under ${CYRUS_TITLE_MAX} characters.` };
      patch.title = t || null;
    } else return { ok: false, error: "Bad title" };
  }
  if ("favourite" in b) {
    if (typeof b.favourite !== "boolean") return { ok: false, error: "Bad favourite" };
    patch.favourite = b.favourite;
  }
  if ("notes" in b) {
    if (typeof b.notes !== "string") return { ok: false, error: "Bad notes" };
    if (b.notes.length > CYRUS_NOTES_MAX) return { ok: false, error: `Notes are limited to ${CYRUS_NOTES_MAX.toLocaleString("en-US")} characters.` };
    patch.notes = b.notes;
  }
  if ("headBuildId" in b) {
    if (b.headBuildId === null) patch.headBuildId = null;
    else if (typeof b.headBuildId === "string" && allowedHeads.includes(b.headBuildId)) patch.headBuildId = b.headBuildId;
    else return { ok: false, error: "You can only restore a version that finished building." };
  }
  if (!Object.keys(patch).length) return { ok: false, error: "Nothing to change" };
  return { ok: true, patch };
}

/** Apply a patch to stored meta (pure). */
export function applyProjectPatch(meta: CyrusMeta, p: ProjectPatch): CyrusMeta {
  const out: CyrusMeta = { ...meta };
  if (p.title !== undefined) { if (p.title) out.title = p.title; else delete out.title; }
  if (p.favourite !== undefined) { if (p.favourite) out.favourite = true; else delete out.favourite; }
  if (p.notes !== undefined) { if (p.notes) out.notes = p.notes; else delete out.notes; }
  if (p.headBuildId !== undefined) { if (p.headBuildId) out.headBuildId = p.headBuildId; else delete out.headBuildId; }
  return out;
}
// Cyrus mod categories: the middle branch of the web (Cyrus core -> game -> category -> mod).
// Deterministic keyword classifier over the build's own words (title, plugin name, tagline,
// summary, prompt); anything unmatched falls back to "Other". Pure, tested in test/cyrus.test.ts.

export type CyrusCategoryId = "worldgen" | "biomes" | "structures" | "gameplay" | "visuals" | "utility" | "other";

export type CyrusCategory = { id: CyrusCategoryId; name: string; icon: string; hue: string; words: RegExp };

/** Order = order on the web (left to right around the live game). Hues are the branch colours. */
export const CYRUS_CATEGORIES: CyrusCategory[] = [
  { id: "worldgen", name: "World Generation", icon: "tree", hue: "#3cf0c8", words: /\b(world ?gen|terrain|ores?|dimension|caves?|generat\w*|islands?|continents?|seed|mountains?|drops?|loot)\b/i },
  { id: "biomes", name: "Biomes", icon: "flower", hue: "#d94aff", words: /\b(biomes?|forests?|deserts?|jungle|swamp|weather|seasons?|flora|fauna|animals?|mobs?)\b/i },
  { id: "structures", name: "Structures", icon: "pickaxe", hue: "#2f7bff", words: /\b(structures?|villages?|dungeons?|towers?|castles?|houses?|buildings?|arenas?|zones?|regions?|claims?|protect\w*|grief)\b/i },
  { id: "gameplay", name: "Gameplay", icon: "gamecube", hue: "#ff3fd8", words: /\b(game|mini-?game|quests?|boss\w*|economy|coins?|shop|pay|pvp|combat|spleef|rewards?|streaks?|levels?|skills?|parkour|kits?|duels?)\b/i },
  { id: "visuals", name: "Visuals", icon: "visuals", hue: "#a42bff", words: /\b(scoreboards?|sidebar|particles?|titles?|hud|cosmetics?|colou?rs?|holograms?|tab ?list|nametags?|chat format|welcome|join messages?|display)\b/i },
  { id: "utility", name: "Utility", icon: "wrench", hue: "#2ee0f5", words: /\b(commands?|homes?|spawn|teleport\w*|tpa|heal|feed|admin|tools?|backpacks?|warps?|chat|messages?|msg|mute|permissions?|utility)\b/i },
  { id: "other", name: "Other", icon: "cube", hue: "#7a6bff", words: /$^/ },
];

export const cyrusCategory = (id: string) => CYRUS_CATEGORIES.find((c) => c.id === id) ?? CYRUS_CATEGORIES[CYRUS_CATEGORIES.length - 1];

/** Pick the category whose words appear most in the text (title words count double). */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  const title = parts.title || "";
  const text = parts.text || "";
  let best: CyrusCategoryId = "other", score = 0;
  for (const c of CYRUS_CATEGORIES) {
    if (c.id === "other") continue;
    const g = new RegExp(c.words.source, "gi");
    const n = (title.match(g)?.length ?? 0) * 2 + (text.match(g)?.length ?? 0);
    if (n > score) { score = n; best = c.id; }
  }
  return best;
}

/** Template category -> web category (templates fill empty branches, clearly marked). */
export const TEMPLATE_CATEGORY: Record<string, CyrusCategoryId> = { Gameplay: "gameplay", Economy: "gameplay", Social: "visuals", Admin: "utility", World: "worldgen" };

// Cyrus v5 <-> Nxeon: turns the account's real builds (ModBuild rows, grouped into projects by
// lib/cyrus/projects.ts) into the studio's network model (Mod + ModVersion, lib/cyrus/types.ts).
// Pure and client-safe; unit-tested in test/cyrus.test.ts.
//
// A real project lives on the Minecraft branch (the only game the build service compiles today).
// Its versions are its builds; their files load lazily from the build service
// (/api/mod-builder/builds/:id/source). Notes, favourite and the restored head stay in the DB
// (PATCH /api/mod-builder/projects/:rootId), exactly as before.
import { isTerminal, type ModBuildView } from "../modbuilder/types";
import { CATEGORIES, CATEGORY_BY_KEY } from "./data";
import { languageForPath } from "./engine/kit";
import { groupProjects, viewMeta, type CyrusProject } from "./projects";
import type { CategoryKey, Game, Mod, ModFile, ModVersion, ModelId } from "./types";

export const REAL_PREFIX = "nx-";
export const realModId = (rootId: string) => `${REAL_PREFIX}${rootId}`;
export const isRealModId = (id: string | undefined | null): id is string => !!id && id.startsWith(REAL_PREFIX);
export const rootOfRealMod = (id: string) => id.slice(REAL_PREFIX.length);

/** The category branches a real game may grow: its own plus at most this many more. */
const MAX_EXTRA_CATEGORIES = 2;
const FALLBACK: CategoryKey = "mechanics";

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const hasWord = (text: string, word: string) => new RegExp(`(^|[^a-z0-9])${escapeRe(word)}(s|es)?([^a-z0-9]|$)`).test(text);

/** Same keyword scoring the forge router uses (lib/cyrus/engine routePrompt), over the build's own words. */
export function scoreCategory(text: string): CategoryKey | null {
  const p = text.toLowerCase();
  let best: CategoryKey | null = null;
  let bestScore = 0;
  for (const c of CATEGORIES) {
    let score = 0;
    for (const k of c.keywords) if (hasWord(p, k)) score += k.length;
    if (score > bestScore) { bestScore = score; best = c.key; }
  }
  return best;
}

const projectText = (p: CyrusProject) => {
  const head = p.head ?? p.latest;
  const s = head.result?.summary;
  return [p.title, head.pluginName, s?.tagline, s?.text, p.builds[0]?.prompt].filter(Boolean).join(" \n ");
};

/**
 * Category per project, keeping the branch readable: the game's own categories, plus up to two
 * more for whatever else the account builds; anything beyond folds into Mechanics.
 */
export function categoriesFor(projects: CyrusProject[], game: Game): Map<string, CategoryKey> {
  const raw = new Map<string, CategoryKey>();
  for (const p of projects) raw.set(p.rootId, scoreCategory(projectText(p)) ?? FALLBACK);
  const own = new Set(game.categories);
  const extraCount = new Map<CategoryKey, number>();
  for (const c of raw.values()) if (!own.has(c)) extraCount.set(c, (extraCount.get(c) ?? 0) + 1);
  let extras = [...extraCount.entries()].sort((a, b) => b[1] - a[1]).map(([c]) => c);
  if (extras.length > MAX_EXTRA_CATEGORIES) {
    const keep = extras.filter((c) => c !== FALLBACK).slice(0, MAX_EXTRA_CATEGORIES - (own.has(FALLBACK) ? 0 : 1));
    extras = own.has(FALLBACK) ? keep : [FALLBACK, ...keep];
  }
  const allowed = new Set<CategoryKey>([...own, ...extras]);
  const out = new Map<string, CategoryKey>();
  for (const [id, c] of raw) out.set(id, allowed.has(c) ? c : FALLBACK);
  return out;
}

const modelOf = (b: ModBuildView): ModelId => viewMeta(b).model ?? "saka";

/** Only the files a server owner cares about (same filter the v4 studio used). */
export const visibleSource = (files: { path: string; size: number }[]) =>
  files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json");

export function versionOf(b: ModBuildView, n: number): ModVersion {
  const s = b.result?.summary;
  return {
    id: b.id,
    label: `v${n}`,
    createdAt: Date.parse(b.createdAt),
    model: modelOf(b),
    credits: 0,
    prompt: b.changeRequest || b.prompt,
    summary: s?.changes || s?.tagline || (b.status === "failed" ? b.error || "This version didn't build." : b.changeRequest || b.prompt),
    files: [],
    additions: 0,
    deletions: 0,
    real: {
      buildId: b.id,
      status: b.status,
      mcVersion: b.mcVersion,
      jarName: b.jarName,
      jarSize: b.jarSize,
      error: b.error,
      attempts: b.attempts,
      durationMs: b.durationMs,
      paths: visibleSource(b.result?.files ?? []),
    },
  };
}

/** Cyrus's notes for a real build, from what the build service reported. */
export function realNotes(b: ModBuildView | null): string {
  if (!b) return "";
  if (b.status === "failed") return `# Didn't build\n\n${b.error || "The build stopped before it finished."}\n\nTokens held for a failed build go back to you.`;
  if (!isTerminal(b.status)) return "# Building\n\nCyrus is writing, compiling and safety-checking this version right now.";
  const r = b.result;
  const s = r?.summary;
  const out: string[] = [`# ${b.pluginName || "Your plugin"}${b.version ? ` v${b.version}` : ""}`];
  if (s?.text) out.push("", s.text);
  if (s?.howToUse?.length) out.push("", "## How to use", ...s.howToUse.map((x) => `- ${x}`));
  if (r?.commands?.length) out.push("", "## Commands", ...r.commands.map((c) => `- \`${c.usage}\` ${c.description}${c.permission ? ` (\`${c.permission}\`)` : ""}`));
  if (r?.permissions?.length) out.push("", "## Permissions", ...r.permissions.map((p) => `- \`${p.node}\` ${p.description} (default: ${p.default})`));
  if (r?.config?.length) out.push("", "## Config", ...r.config.map((c) => `- \`${c.key}\` ${c.description} (default \`${c.default}\`)`));
  if (s?.limitations?.length) out.push("", "## Limits", ...s.limitations.map((x) => `- ${x}`));
  const safety = r?.safety?.verdict;
  out.push("", "## Build", `- Paper ${b.mcVersion} · built in ${Math.max(1, Math.round((b.durationMs ?? 0) / 1000))}s${b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}`);
  if (safety) out.push(`- Safety check: **${safety === "pass" ? "passed" : safety === "warn" ? "passed with notes" : "blocked"}** (no internet, no system access)`);
  return out.join("\n");
}

export type RealModel = {
  projects: CyrusProject[];
  mods: Mod[];
  versions: Record<string, ModVersion[]>;
  active: Record<string, string>;
  notes: Record<string, string>;
  aiNotes: Record<string, string>;
};

/** Every project of the account as a mod on `game`'s branch (newest activity first). */
export function deriveReal(builds: ModBuildView[], game: Game): RealModel {
  const projects = groupProjects(builds);
  const cats = categoriesFor(projects, game);
  const out: RealModel = { projects, mods: [], versions: {}, active: {}, notes: {}, aiNotes: {} };
  for (const p of projects) {
    const id = realModId(p.rootId);
    const head = p.head;
    const s = (head ?? p.latest).result?.summary;
    out.mods.push({
      id,
      gameId: game.id,
      category: cats.get(p.rootId) ?? FALLBACK,
      name: p.title,
      summary: s?.tagline || s?.text?.split(/(?<=\.)\s/)[0] || p.builds[0].prompt.slice(0, 140),
      tags: [],
      createdAt: Date.parse(p.updatedAt || p.latest.createdAt),
      versions: [],
      real: { rootId: p.rootId, running: !!p.running, failed: !head && !p.running, headBuildId: head?.id ?? null, favourite: !!p.meta.favourite },
    });
    out.versions[id] = p.builds.map((b, i) => versionOf(b, i + 1));
    out.active[id] = (head ?? p.latest).id;
    out.notes[id] = p.meta.notes ?? "";
    out.aiNotes[id] = realNotes(head ?? p.latest);
  }
  return out;
}

/** A source file as the studio's ModFile. */
export const toModFile = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/** Is CATEGORY_BY_KEY aware of this key (guards stale data). */
export const knownCategory = (k: string): k is CategoryKey => k in CATEGORY_BY_KEY;
