export const CORE_ID = "core";

export const useStore = create<CyrusState>()(
  persist(
    (set, get) => ({
      theme: "dark",
      userMods: [],
      userVersions: {},
      activeVersion: {},
      notes: {},
      aiNotes: {},
      model: "katara",
      mcVersion: MB_DEFAULT_VERSION,
      setMcVersion: (mcVersion) => set({ mcVersion }),
      layout: {},
      customGames: [],
      addGameOpen: false,
      coreStyle: "particles",

      selection: { level: "core" },
      focus: { kind: "overview", tick: 0 },
      panelOpen: false,
      panelTab: "code",
      activeFile: null,
      navOpen: false,
      paletteOpen: false,
      job: null,
      toasts: [],
      promptFocusTick: 0,
      prefill: null,

      userId: null,
      realBuilds: [],
      real: EMPTY_REAL,
      realFiles: {},
      servers: [],
      online: true,
      setReal: (builds) => set({ realBuilds: builds, real: deriveReal(builds, REAL_GAME) }),
      upsertReal: (list) => {
        const m = new Map(get().realBuilds.map((b) => [b.id, b]));
        for (const b of list) m.set(b.id, { ...m.get(b.id), ...b });
        get().setReal([...m.values()]);
      },
      refreshReal: async () => {
        const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
        if (!r?.ok) return;
        const j = (await r.json().catch(() => null)) as { builds?: ModBuildView[] } | null;
        if (j?.builds) get().upsertReal(j.builds);
      },
      loadRealFiles: async (buildId, paths, opts) => {
        const cur = get().realFiles[buildId];
        if (!opts?.force && (cur === "loading" || Array.isArray(cur))) return;
        if (!Array.isArray(cur)) set((s) => ({ realFiles: { ...s.realFiles, [buildId]: "loading" } }));
        const files = await Promise.all(
          paths.map(async (path) => {
            const r = await fetch(`/api/mod-builder/builds/${buildId}/source?path=${encodeURIComponent(path)}`).catch(() => null);
            return r?.ok ? toModFile(path, await r.text()) : null;
          }),
        );
        const ok = files.filter((f): f is ModFile => !!f);
        set((s) => ({ realFiles: { ...s.realFiles, [buildId]: ok.length || !paths.length ? ok : "error" } }));
      },
      seedRealFiles: (buildId, files) => set((s) => ({ realFiles: { ...s.realFiles, [buildId]: files } })),
      patchProject: async (rootId, patch) => {
        // optimistic: the project's meta lives on its root build
        const apply = (builds: ModBuildView[]) =>
          builds.map((b) => (b.id === rootId ? { ...b, cyrus: { ...((b.cyrus as object) ?? {}), ...patch } } : b));
        get().setReal(apply(get().realBuilds));
        try {
          const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(patch) });
          const j = await r.json().catch(() => ({}));
          if (!r.ok) {
            void get().refreshReal();
            return (j as { error?: string }).error || "Couldn't save.";
          }
          get().setReal(get().realBuilds.map((b) => (b.id === rootId ? { ...b, cyrus: (j as { meta?: unknown }).meta ?? b.cyrus } : b)));
          return null;
        } catch {
          return "Couldn't save.";
        }
      },
      pickIdea: (modId) => {
        const mod = findMod(modId);
        if (!mod?.ideaPrompt) return;
        get().select({ level: "category", gameId: mod.gameId, category: mod.category });
        set((s) => ({ prefill: { text: mod.ideaPrompt!, tick: (s.prefill?.tick ?? 0) + 1 } }));
      },

      setTheme: (theme) => {
        // The portal owns the theme. Press its own toggle (top bar) so its icon, its transition
        // and its saved choice ("nx-theme") all stay in step; CyrusApp mirrors data-theme back.
        const current = document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";
        if (current === theme) return;
        const portal = document.querySelector<HTMLButtonElement>("button.nx-theme-toggle");
        if (portal) { portal.click(); return; }
        try { localStorage.setItem("nx-theme", theme); } catch { /* private mode */ }
        if (theme === "light") document.documentElement.setAttribute("data-theme", "light");
        else document.documentElement.removeAttribute("data-theme");
        set({ theme });
      },
      toggleTheme: () => get().setTheme(get().theme === "dark" ? "light" : "dark"),

      select: (sel, opts) => {
        const focusKind = opts?.focus ?? (sel.level === "core" ? "overview" : "node");
        const id =
          sel.level === "mod"
            ? sel.modId
            : sel.level === "category"
              ? `${sel.gameId}:${sel.category}`
              : sel.level === "game"
                ? sel.gameId
                : CORE_ID;
        set((s) => ({
          selection: sel,
          focus: { kind: focusKind, id, tick: s.focus.tick + 1 },
          panelOpen: opts?.openPanel ?? (sel.level === "mod" ? true : s.panelOpen),
          activeFile: sel.level === "mod" && sel.modId !== s.selection.modId ? null : s.activeFile,
        }));
      },

      goUp: () => {
        const { selection, select } = get();
        if (selection.level === "mod") select({ level: "category", gameId: selection.gameId, category: selection.category });
        else if (selection.level === "category") select({ level: "game", gameId: selection.gameId });
        else select({ level: "core" });
      },

      setModel: (model) => set({ model }),
      setPanelOpen: (panelOpen) => set({ panelOpen }),
      setPanelTab: (panelTab) => set({ panelTab, panelOpen: true }),
      setActiveFile: (activeFile) => set({ activeFile }),
      setNavOpen: (navOpen) => set({ navOpen }),
      setPaletteOpen: (paletteOpen) => set({ paletteOpen }),
      recenter: () => set((s) => ({ focus: { kind: "overview", tick: s.focus.tick + 1 } })),

      toast: (t) => {
        const id = Math.random().toString(36).slice(2);
        set((s) => ({ toasts: [...s.toasts.slice(-3), { ...t, id }] }));
        window.setTimeout(() => get().dismissToast(id), t.tone === "error" ? 6000 : 4200);
      },
      dismissToast: (id) => set((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })),

      setNote: (modId, text) => {
        if (isRealModId(modId)) {
          // saved on the project (DB), debounced
          set((s) => ({ real: { ...s.real, notes: { ...s.real.notes, [modId]: text } } }));
          window.clearTimeout(noteTimers.get(modId));
          noteTimers.set(modId, window.setTimeout(() => void get().patchProject(rootOfRealMod(modId), { notes: text }), 700));
          return;
        }
        set((s) => ({ notes: { ...s.notes, [modId]: text } }));
      },
      restoreVersion: (modId, versionId) => {
        if (isRealModId(modId)) {
          const v = get().real.versions[modId]?.find((x) => x.id === versionId);
          if (v?.real?.status !== "succeeded") {
            get().toast({ tone: "error", title: "Can't restore this version", body: "Only versions that built can be made current." });
            return;
          }
          void get().patchProject(rootOfRealMod(modId), { headBuildId: versionId }).then((e) => {
            if (e) get().toast({ tone: "error", title: "Couldn't restore", body: e });
          });
          return;
        }
        set((s) => ({ activeVersion: { ...s.activeVersion, [modId]: versionId } }));
      },
      focusPrompt: () => set((s) => ({ promptFocusTick: s.promptFocusTick + 1 })),
      setNodeHome: (id, hx, hy) => set((s) => ({ layout: { ...s.layout, [id]: [Math.round(hx), Math.round(hy)] } })),
      resetLayout: () => set({ layout: {} }),
      setAddGameOpen: (addGameOpen) => set({ addGameOpen }),
      setCoreStyle: (coreStyle) => set({ coreStyle }),
      addGame: (game) => set((s) => ({ customGames: [...s.customGames, { ...game, custom: true }] })),
      removeGame: (id) =>
        set((s) => {
          const game = s.customGames.find((g) => g.id === id);
          if (!game) return {};
          const gone = new Set(s.userMods.filter((m) => m.gameId === id).map((m) => m.id));
          const layout = { ...s.layout };
          delete layout[id];
          for (const key of game.categories) delete layout[categoryNodeId(id, key)];
          const strip = <T,>(rec: Record<string, T>) => Object.fromEntries(Object.entries(rec).filter(([k]) => !gone.has(k)));
          return {
            customGames: s.customGames.filter((g) => g.id !== id),
            userMods: s.userMods.filter((m) => m.gameId !== id),
            userVersions: strip(s.userVersions),
            activeVersion: strip(s.activeVersion),
            notes: strip(s.notes),
            aiNotes: strip(s.aiNotes),
            layout,
            selection: s.selection.gameId === id ? ({ level: "core" } as Selection) : s.selection,
          };
        }),
    }),
    {
      name: "cyrus-state-v1",
      storage: createJSONStorage(() => localStorage),
      skipHydration: true,
      partialize: (s) => ({
        userMods: s.userMods,
        userVersions: s.userVersions,
        activeVersion: s.activeVersion,
        notes: s.notes,
        aiNotes: s.aiNotes,
        model: s.model,
        mcVersion: s.mcVersion,
        layout: s.layout,
        customGames: s.customGames,
        coreStyle: s.coreStyle,
      }),
    },
  ),
);

/* ───────────── Derived helpers ───────────── */

/** Built-in or user-added game by id. */
export function getGame(id: GameId | undefined): Game | undefined {
  if (!id) return undefined;
  return GAME_BY_ID[id] ?? useStore.getState().customGames.find((g) => g.id === id);
}

export function useGames(): Game[] {
  const custom = useStore((s) => s.customGames);
  return useMemo(() => [...GAMES, ...custom], [custom]);
}

export function useGame(id: GameId | undefined): Game | undefined {
  const games = useGames();
  return useMemo(() => (id ? games.find((g) => g.id === id) : undefined), [games, id]);
}

const seedCache = new Map<string, ModVersion[]>();

/** Real versions carry their loaded files (empty until loadRealFiles has them). */
function withRealFiles(list: ModVersion[] | undefined, files: CyrusState["realFiles"]): ModVersion[] {
  return (list ?? []).map((v) => {
    const f = v.real ? files[v.real.buildId] : undefined;
    return Array.isArray(f) ? { ...v, files: f } : v;
  });
}

export function versionsOf(mod: Mod | undefined, userVersions: Record<string, ModVersion[]>): ModVersion[] {
  if (!mod) return [];
  if (mod.real) {
    const s = useStore.getState();
    return withRealFiles(s.real.versions[mod.id], s.realFiles);
  }
  let base: ModVersion[] = [];
  if (mod.seed) {
    base = seedCache.get(mod.id) ?? seedVersions(mod);
    seedCache.set(mod.id, base);
  }
  return [...base, ...(userVersions[mod.id] ?? [])];
}

/** Pills a category shows before "+N more" (components/cyrus/cosmos/graph.ts VISIBLE_MODS). */
const VISIBLE = 3;

/** Seeds + the account's real projects + local template mods. Ideas on a real game only fill
 *  the room the real projects leave in their category, so they never push a real mod off. */
export function combineMods(realMods: Mod[], userMods: Mod[]): Mod[] {
  const realPer = new Map<string, number>();
  for (const m of realMods) realPer.set(`${m.gameId}:${m.category}`, (realPer.get(`${m.gameId}:${m.category}`) ?? 0) + 1);
  const ideaPer = new Map<string, number>();
  const seeds = SEED_MODS.filter((m) => {
    if (!m.idea) return true;
    const k = `${m.gameId}:${m.category}`;
    const n = ideaPer.get(k) ?? 0;
    if (n + (realPer.get(k) ?? 0) >= VISIBLE) return false;
    ideaPer.set(k, n + 1);
    return true;
  });
  return [...seeds, ...realMods, ...userMods];
}

export function useAllMods(): Mod[] {
  const userMods = useStore((s) => s.userMods);
  const realMods = useStore((s) => s.real.mods);
  return useMemo(() => combineMods(realMods, userMods), [realMods, userMods]);
}

export function findMod(id: string | undefined): Mod | undefined {
  if (!id) return undefined;
  const s = useStore.getState();
  return SEED_MODS.find((m) => m.id === id) ?? s.real.mods.find((m) => m.id === id) ?? s.userMods.find((m) => m.id === id);
}

export function useMod(id: string | undefined) {
  const userMods = useStore((s) => s.userMods);
  const realMods = useStore((s) => s.real.mods);
  return useMemo(
    () => (id ? (SEED_MODS.find((m) => m.id === id) ?? realMods.find((m) => m.id === id) ?? userMods.find((m) => m.id === id)) : undefined),
    [id, userMods, realMods],
  );
}

export function useModVersions(mod: Mod | undefined) {
  const userVersions = useStore((s) => s.userVersions);
  const activeVersion = useStore((s) => s.activeVersion);
  const real = useStore((s) => s.real);
  const realFiles = useStore((s) => s.realFiles);
  return useMemo(() => {
    const versions = mod?.real ? withRealFiles(real.versions[mod.id], realFiles) : versionsOf(mod, userVersions);
    const activeMap = mod?.real ? real.active : activeVersion;
    const activeId = mod ? (activeMap[mod.id] ?? versions[versions.length - 1]?.id) : undefined;
    const active = versions.find((v) => v.id === activeId) ?? versions[versions.length - 1];
    return { versions, active };
  }, [mod, userVersions, activeVersion, real, realFiles]);
}

/** Notes for any mod: the DB-backed ones for real projects, local ones otherwise. */
export function useModNotes(modId: string): { mine: string; cyrus: string | undefined } {
  const mine = useStore((s) => (isRealModId(modId) ? s.real.notes[modId] : s.notes[modId]) ?? "");
  const cyrus = useStore((s) => (isRealModId(modId) ? s.real.aiNotes[modId] : s.aiNotes[modId]));
  return { mine, cyrus };
}

