// Cyrus: line diff between two versions of a file (pure, unit-tested).
// Myers O(ND) with a size guard; plugins are small (the service caps source at 1.5 MB).

export type DiffOp = { t: "eq" | "add" | "del"; a: number | null; b: number | null; text: string };

const MAX_LINES = 12000;
const MAX_D = 4000;

export function splitLines(s: string): string[] {
  if (!s) return [];
  const lines = s.replace(/\r\n?/g, "\n").split("\n");
  if (lines[lines.length - 1] === "") lines.pop();
  return lines;
}

export function diffLines(oldText: string, newText: string): DiffOp[] {
  const A = splitLines(oldText);
  const B = splitLines(newText);
  // Trim common prefix/suffix first: most version diffs touch a few lines.
  let pre = 0;
  while (pre < A.length && pre < B.length && A[pre] === B[pre]) pre++;
  let suf = 0;
  while (suf < A.length - pre && suf < B.length - pre && A[A.length - 1 - suf] === B[B.length - 1 - suf]) suf++;
  const a = A.slice(pre, A.length - suf);
  const b = B.slice(pre, B.length - suf);
  const mid = a.length + b.length > MAX_LINES ? replaceAll(a, b) : myers(a, b) ?? replaceAll(a, b);
  const out: DiffOp[] = [];
  for (let i = 0; i < pre; i++) out.push({ t: "eq", a: i + 1, b: i + 1, text: A[i] });
  for (const op of mid) out.push({ ...op, a: op.a === null ? null : op.a + pre, b: op.b === null ? null : op.b + pre });
  for (let i = 0; i < suf; i++) {
    const ai = A.length - suf + i, bi = B.length - suf + i;
    out.push({ t: "eq", a: ai + 1, b: bi + 1, text: A[ai] });
  }
  return out;
}

function replaceAll(a: string[], b: string[]): DiffOp[] {
  return [...a.map((text, i) => ({ t: "del" as const, a: i + 1, b: null, text })), ...b.map((text, i) => ({ t: "add" as const, a: null, b: i + 1, text }))];
}

/** Classic Myers with a stored trace; null when the edit distance exceeds MAX_D. 1-based line numbers. */
function myers(a: string[], b: string[]): DiffOp[] | null {
  const n = a.length, m = b.length, max = n + m;
