function safeImageSrc(u: string | null | undefined): string | null {
  if (!u) return null;
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\/\//.test(t)) return `https:${t}`;
  return null;
}

/**
 * Only http(s) or same-site root-relative allowed for links; else "#".
 * `^\/(?!\/|\\)` — a bare leading `/` only, NOT `//host/...` (a browser
 * treats a protocol-relative URL as a full off-site navigation, same
 * scheme as the current page) or `/\host/...` (older browsers normalize a
 * leading backslash the same way) — both would otherwise slip through as
 * "site-relative" and skip the `target="_blank" rel="noopener noreferrer"`
 * treatment external links get below, silently sending a visitor off-site
 * with the referrer/opener still attached (found in review, 2026-09-24).
 */
function safeLinkHref(u: string | null | undefined): string {
  if (!u) return "#";
  const t = u.trim();
  if (/^https:\/\//i.test(t)) return t;
  if (/^http:\/\//i.test(t)) return `https://${t.slice(7)}`;
  if (/^\/(?!\/|\\)/.test(t)) return t;
  return "#";
}

function extractAttr(attrs: string, name: string): string | null {
  const m = attrs.match(new RegExp(`${name}\\s*=\\s*"([^"]*)"`, "i")) ?? attrs.match(new RegExp(`${name}\\s*=\\s*'([^']*)'`, "i"));
  return m ? m[1] : null;
}

/** Simple wrap tags: no attributes ever kept, just the tag shell restored. */
const WRAP_TAG_MAP: Record<string, { open: string; close: string }> = {
  center: { open: '<div class="text-center">', close: "</div>" },
  details: { open: "<details>", close: "</details>" },
  summary: { open: '<summary class="cursor-pointer font-medium text-white">', close: "</summary>" },
  sub: { open: "<sub>", close: "</sub>" },
  sup: { open: "<sup>", close: "</sup>" },
  small: { open: '<span class="text-xs">', close: "</span>" },
  b: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
  strong: { open: "<strong class=\"font-semibold text-white\">", close: "</strong>" },
  i: { open: "<em>", close: "</em>" },
  em: { open: "<em>", close: "</em>" },
  u: { open: "<u>", close: "</u>" },
  s: { open: "<s>", close: "</s>" },
  strike: { open: "<s>", close: "</s>" },
  code: { open: `<code class="${CLS.code}">`, close: "</code>" },
  blockquote: { open: `<blockquote class="${CLS.blockquote}">`, close: "</blockquote>" },
  // Block-level structural tags — real Modrinth bodies routinely use these
  // directly as raw HTML instead of markdown syntax (confirmed live:
  // bookshelf-lib's whole body is <p>/<h3>/<ul>/<li>, not "# " / "- ").
  // h1-h6 are handled separately below (all collapse to h3 — HEADING POLICY).
  p: { open: `<p class="${CLS.p}">`, close: "</p>" },
  ul: { open: `<ul class="${CLS.ul}">`, close: "</ul>" },
  ol: { open: `<ol class="${CLS.ol}">`, close: "</ol>" },
  li: { open: `<li class="${CLS.li}">`, close: "</li>" },
  div: { open: "<div>", close: "</div>" },
};
const VOID_TAGS = new Set(["br", "hr"]);
/** Tags whose OPENING form means "this whole paragraph run IS a raw HTML
