 * file header for why this order is what makes it safe). Handles simple
 * wrap tags, void tags (br/hr), and the two attribute-carrying tags
 * (img/a) via strict extraction + revalidation, never verbatim echo.
 *
 * REDOS SAFETY (2026-09-24 fix, found by an adversarial review before this
 * ever ran against real data): every regex below uses AT MOST ONE
 * variable-length quantifier between two fixed anchors (`&lt;tag` ... `&gt;`
 * or `&lt;/tag&gt;`). The ORIGINAL version chained several adjustable-length
 * pieces back to back — e.g. `\s+([^&]*?)\/?\s*&gt;` had `\s+`, a lazy
 * `[^&]*?`, and a trailing `\s*` all able to match the SAME run of space
 * characters. On adversarial input with no closing `&gt;` at all (trivial
 * for a mod author to publish: `<img` followed by thousands of spaces),
 * the regex engine tried every way of splitting that run of spaces across
 * the three quantifiers before giving up — confirmed live: a 6,000-char
 * adversarial string (exactly this module's own truncation length) pegged
 * a CPU core for minutes. Collapsing each pattern to one greedy quantifier
 * (`[^&]*` with NO leading `\s+`/trailing `\s*` competing for the same
 * characters) makes every one of these a single, unambiguous linear scan —
 * there is nothing left to backtrack between.
 */
function restoreSafeHtml(escaped: string): string {
  let s = escaped;

  // Void tags: &lt;br&gt; / &lt;br/&gt; / &lt;br /&gt; / &lt;hr ...&gt; — one
  // greedy group swallows whatever's between the tag name and `&gt;`
  // (slash, spaces, anything-but-&); always discarded, so its exact shape
  // never matters.
  s = s.replace(/&lt;(br|hr)\b[^&]*&gt;/gi, (_m, tag: string) => `<${tag.toLowerCase()} />`);

  // img — attribute-carrying, strictly re-templated. One greedy group.
  s = s.replace(/&lt;img\b([^&]*)&gt;/gi, (_m, attrs: string) => {
    const src = safeImageSrc(extractAttr(attrs, "src"));
    if (!src) return "";
    const alt = extractAttr(attrs, "alt") ?? "";
    return `<img src="${escAttr(src)}" alt="${escAttr(alt)}" loading="lazy" class="${CLS.img}" />`;
  });

  // a — attribute-carrying, strictly re-templated. One greedy group.
  // Opening + closing handled separately.
  s = s.replace(/&lt;a\b([^&]*)&gt;/gi, (_m, attrs: string) => {
    const href = safeLinkHref(extractAttr(attrs, "href"));
    const external = href.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttr(href)}"${external ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>`;
  });
  s = s.replace(/&lt;\/a\s*&gt;/gi, "</a>");

