    // see that helper's own doc comment for why a second full `esc()` pass
    // here would both double-encode AND (found in review, 2026-09-24) is
    // NOT what was neutralizing the `"` that lets a crafted URL break out
    // of this attribute — omitting it here entirely was the real bug.
    return `<img class="${CLS.img}" src="${escAttrPostEscaped(safe)}" alt="${escAttrPostEscaped(alt)}" loading="lazy" />`;
  });
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = safeLinkHref(u);
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${escAttrPostEscaped(safe)}"${ext ? ' target="_blank" rel="noopener noreferrer nofollow ugc"' : ""}>${t}</a>`;
  });
  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
  return s;
