// ---------------------------------------------------------------------------
// Cyrus v6 community (2026-10-08, branch feature/cyrus-v6-community). ADDITIVE ONLY:
// new tables, no relations, nothing changed on existing tables, no unique constraint on a
// populated table. Writers: lib/actions-cyrus-community.ts, lib/cyrus-mods/{social,media}.ts,
// app/api/nxlabs/cyrus/[slug]/media. Rules (pure, tested): lib/cyrus-mods/{listing,remix,tested}.ts.
// Docs: docs/DOCUMENTATION.md "Cyrus community (v6)". Deploy: a plain `prisma db push` creates
// the 11 tables below and touches nothing else (no data loss prompt expected).
// ---------------------------------------------------------------------------

/// The creator's own customisation of a Cyrus mod page (NxLabs "Edit listing"). One row per
/// page, created on first save. No row = the generated page exactly as before.
model CyrusModListing {
  /// CyrusModPage.id
  pageId          String    @id
  /// The creator (CyrusModPage.userId) at the time of the save.
  userId          String
  /// Short line under the title. Overrides the generated tagline when set.
  tagline         String?
  /// Long description, markdown. Rendered by lib/mod-markdown.ts renderModMarkdown (escape-first
  /// allow-list) with embedded images stripped: photos go through the gallery instead.
  description     String?   @db.Text
  /// Universal category id the creator picked when the auto-sorter got it wrong.
  category        String?
  tags            String[]  @default([])
  /// [{ label, url }] https links only (lib/cyrus-mods/listing.ts validateListing).
  links           Json?
  /// Creator release notes per version, { [buildId]: markdown }. Shown above the generated notes.
  changelog       Json?
  /// CyrusModMedia ids (kind icon / banner).
  iconMediaId     String?
  bannerMediaId   String?
  /// OPEN (default) = anyone with Cyrus may remix it into their own Cyrus; CLOSED = only the
  /// creator builds on it. The source download and its licence are unaffected either way.
  remixPolicy     String    @default("OPEN")
  /// A community version (a remix's ModBuild id) the creator pinned on the original page.
  endorsedBuildId String?
  endorsedAt      DateTime?
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt

  @@index([userId])
}

/// Images on a Cyrus mod page: gallery photos, the icon and the banner. Stored re-encoded as
/// WebP (EXIF dropped) under MODBUILD_DIR/nxlabs-media/<aa>/<key>.webp, served by
/// /api/nxlabs/cyrus/media/<id> with the page's own visibility rule.
model CyrusModMedia {
  id        String    @id @default(cuid())
  pageId    String
  userId    String
  /// photo | icon | banner
  kind      String    @default("photo")
  /// sha256 of the stored WebP.
  key       String
  width     Int?
  height    Int?
  bytes     Int?
  caption   String?
  sort      Int       @default(0)
  /// Moderation (admin, or 3 distinct reports).
  hiddenAt  DateTime?
  createdAt DateTime  @default(now())

  @@index([pageId, kind, sort])
}

/// Remix lineage: one row per remix ("Remix in my Cyrus"), next to the CyrusFork row the copy
/// already gets. CyrusFork keeps the BUILD SERVICE id; this keeps the exact version remixed and
/// the chain up to the original, so credit survives remixes of remixes.
model CyrusRemix {
  /// The remix's root ModBuild (= CyrusFork.buildId).
  buildId           String   @id
  userId            String
  /// The page that was remixed and the exact version of it.
  parentPageId      String
  parentBuildId     String
  parentRootBuildId String
  /// The top of the chain (the first non-remix mod).
  originPageId      String
  /// 1 = remix of an original, 2 = remix of a remix, ...
  depth             Int      @default(1)
  /// Portal-side re-scan of the copied code at remix time (lib/cyrus-mods/rescan.ts):
  /// { verdict, findings[], files, checksumOk, at }.
  scan              Json?
  createdAt         DateTime @default(now())

  @@index([parentPageId])
  @@index([originPageId])
  @@index([userId])
}

/// A star (like) on a Cyrus mod page. Any signed-in account except the creator.
model CyrusModStar {
  userId    String
  pageId    String
  createdAt DateTime @default(now())

  @@id([userId, pageId])
  @@index([pageId])
}

