input.content:
// Cyrus mod listings: the PURE half of "Open in NxLabs" (client-safe, unit-tested).
//
// A Cyrus mod page (CyrusModPage) is generated from its builds. The creator customises it on top:
// title, tagline, long description (markdown), icon, banner, photo gallery, tags, links, per-version
// changelog notes, category, visibility and whether others may remix it. That customisation lives in
// CyrusModListing / CyrusModMedia; this file holds the input type, the validation and the read-side
// helpers. The writer is lib/actions-cyrus-community.ts saveModListing().
//
// MERGE NOTE (Cyrus v6): the routing agent's post-forge dialog uses a `ModListingInput` from
// lib/cyrus/listing.ts. This type is the superset (title, category, icon, brief description are the
// same field names); when both land, lib/cyrus/listing.ts should re-export this one.
import { renderModMarkdown, truncateMarkdown } from "../mod-markdown";
import { CYRUS_TITLE_MAX } from "../cyrus/meta";

export const REMIX_POLICIES = ["OPEN", "CLOSED"] as const;
export type RemixPolicy = (typeof REMIX_POLICIES)[number];
/**
 * Default: OPEN. Every Cyrus mod already ships its full source under an open licence (MIT by
 * default), so anyone could rebuild it by hand; "OPEN" just makes that one click inside Cyrus and
 * keeps the credit chain intact. A creator who wants their page to stay theirs picks CLOSED.
 */
export const DEFAULT_REMIX_POLICY: RemixPolicy = "OPEN";
export const isRemixPolicy = (x: unknown): x is RemixPolicy => typeof x === "string" && (REMIX_POLICIES as readonly string[]).includes(x);

export const LISTING_LIMITS = {
  titleMin: 3,
  titleMax: CYRUS_TITLE_MAX,
  taglineMax: 160,
  descriptionMax: 20_000,
  tags: 8,
  tagMin: 2,
  tagMax: 24,
  links: 6,
  linkLabelMax: 40,
  linkUrlMax: 300,
  changelogMax: 4000,
  photos: 12,
  captionMax: 140,
  imageBytes: 8 * 1024 * 1024,
};

export type ListingLink = { label: string; url: string };

/** What the editor (and the routing agent's post-forge dialog) sends. Every field is optional: only sent fields change. */
export type ModListingInput = {
  title?: string | null;
  /** The "brief description" shown under the title and on cards. */
  tagline?: string | null;
  /** Long description, markdown. */
  description?: string | null;
  category?: string | null;
  tags?: string[];
  links?: ListingLink[];
  /** { [versionBuildId]: notes } — empty string clears a version's note. */
  changelog?: Record<string, string>;
  visibility?: "PUBLIC" | "PRIVATE";
  remixPolicy?: RemixPolicy;
  /** CyrusModMedia ids of this page (kind icon / banner), or null to clear. */
  iconMediaId?: string | null;
  bannerMediaId?: string | null;
  /** Gallery order: this page's photo ids, first = cover. */
  photoOrder?: string[];
  captions?: Record<string, string>;
};

export type CleanListing = {
  title?: string;
  tagline?: string | null;
  description?: string | null;
  category?: string | null;
  tags?: string[];
  links?: ListingLink[];
  changelog?: Record<string, string>;
  visibility?: "PUBLIC" | "PRIVATE";
  remixPolicy?: RemixPolicy;
  iconMediaId?: string | null;
  bannerMediaId?: string | null;
  photoOrder?: string[];
  captions?: Record<string, string>;
};

export type ListingContext = {
  /** Succeeded version build ids of the mod. */
  versionIds: string[];
  /** Category ids the mod store knows (universal categories). */
  categories: string[];
  /** This page's media, by id. */
  media: { id: string; kind: string }[];
};

const ctrl = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
const line = (s: unknown) => (typeof s === "string" ? s.replace(ctrl, "").replace(/[\r\n\t]+/g, " ").replace(/\s+/g, " ").trim() : "");
const text = (s: unknown) => (typeof s === "string" ? s.replace(ctrl, "").replace(/\r\n?/g, "\n").replace(/\n{4,}/g, "\n\n\n").trim() : "");
const idRe = /^[A-Za-z0-9_-]{1,64}$/;

/** "Boss Fights!" -> "boss-fights". Empty when nothing usable is left. */
export function normaliseTag(t: unknown): string {
  return line(t).toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, LISTING_LIMITS.tagMax).replace(/-+$/g, "");
}

/** https only (http is upgraded), no credentials in the URL, no javascript:/data:. */
export function cleanLinkUrl(u: unknown): string | null {
  const s = line(u);
  if (!s || s.length > LISTING_LIMITS.linkUrlMax) return null;
  let url: URL;
  try {
    url = new URL(/^https?:\/\//i.test(s) ? s : `https://${s}`);
  } catch {
    return null;
  }
  if (url.protocol === "http:") url.protocol = "https:";
  if (url.protocol !== "https:" || url.username || url.password || !url.hostname.includes(".")) return null;
  return url.toString();
}

type Result = { ok: true; clean: CleanListing } | { ok: false; error: string; field: string };

/** Validate an editor save. Only the fields present in `input` are checked and returned. */
export function validateListing(input: ModListingInput | null | undefined, ctx: ListingContext): Result {
  if (!input || typeof input !== "object") return { ok: false, error: "Nothing to save.", field: "form" };
  const out: CleanListing = {};
  const L = LISTING_LIMITS;
  if ("title" in input && input.title !== undefined) {
    const t = line(input.title);
    if (t.length < L.titleMin) return { ok: false, error: "Give the mod a name (at least 3 characters).", field: "title" };
    if (t.length > L.titleMax) return { ok: false, error: `Keep the name under ${L.titleMax} characters.`, field: "title" };
    out.title = t;
  }
  if ("tagline" in input && input.tagline !== undefined) {
    const t = line(input.tagline);
    if (t.length > L.taglineMax) return { ok: false, error: `Keep the short description under ${L.taglineMax} characters.`, field: "tagline" };
    out.tagline = t || null;
  }
  if ("description" in input && input.description !== undefined) {
    const d = text(input.description);
    if (d.length > L.descriptionMax) return { ok: false, error: `The description is limited to ${L.descriptionMax.toLocaleString("en-US")} characters.`, field: "description" };
    out.description = d || null;
  }
  if ("category" in input && input.category !== undefined) {
    if (input.category === null || input.category === "") out.category = null;
    else if (typeof input.category === "string" && ctx.categories.includes(input.category)) out.category = input.category;
    else return { ok: false, error: "Pick one of the listed categories.", field: "category" };
  }
  if ("tags" in input && input.tags !== undefined) {
    if (!Array.isArray(input.tags)) return { ok: false, error: "Bad tags.", field: "tags" };
    const tags = [...new Set(input.tags.map(normaliseTag).filter((t) => t.length >= L.tagMin))];
    if (tags.length > L.tags) return { ok: false, error: `Up to ${L.tags} tags.`, field: "tags" };
    out.tags = tags;
  }
  if ("links" in input && input.links !== undefined) {
    if (!Array.isArray(input.links)) return { ok: false, error: "Bad links.", field: "links" };
    const links: ListingLink[] = [];
    for (const l of input.links) {
      if (!l || typeof l !== "object") continue;
      const label = line((l as ListingLink).label).slice(0, L.linkLabelMax);
      const rawUrl = line((l as ListingLink).url);
      if (!label && !rawUrl) continue;
      const url = cleanLinkUrl(rawUrl);
      if (!url) return { ok: false, error: `"${rawUrl.slice(0, 60) || label}" isn't a valid https link.`, field: "links" };
      links.push({ label: label || new URL(url).hostname, url });
    }
    if (links.length > L.links) return { ok: false, error: `Up to ${L.links} links.`, field: "links" };
    out.links = links;
  }
  if ("changelog" in input && input.changelog !== undefined) {
    if (!input.changelog || typeof input.changelog !== "object" || Array.isArray(input.changelog)) return { ok: false, error: "Bad changelog.", field: "changelog" };
    const cl: Record<string, string> = {};
    for (const [id, v] of Object.entries(input.changelog)) {
      if (!ctx.versionIds.includes(id)) return { ok: false, error: "A changelog note points at a version this mod doesn't have.", field: "changelog" };
      const t = text(v);
      if (t.length > L.changelogMax) return { ok: false, error: `Keep each version's notes under ${L.changelogMax.toLocaleString("en-US")} characters.`, field: "changelog" };
      if (t) cl[id] = t;
    }
    out.changelog = cl;
  }
  if ("visibility" in input && input.visibility !== undefined) {
    if (input.visibility !== "PUBLIC" && input.visibility !== "PRIVATE") return { ok: false, error: "Bad visibility.", field: "visibility" };
    out.visibility = input.visibility;
  }
  if ("remixPolicy" in input && input.remixPolicy !== undefined) {
    if (!isRemixPolicy(input.remixPolicy)) return { ok: false, error: "Bad remix setting.", field: "remixPolicy" };
    out.remixPolicy = input.remixPolicy;
  }
  const mediaOf = (id: unknown, kind: string) => typeof id === "string" && idRe.test(id) && ctx.media.some((m) => m.id === id && m.kind === kind);
  for (const [field, kind] of [["iconMediaId", "icon"], ["bannerMediaId", "banner"]] as const) {
    if (field in input && input[field] !== undefined) {
      const v = input[field];
      if (v === null || v === "") out[field] = null;
      else if (mediaOf(v, kind)) out[field] = v as string;
      else return { ok: false, error: `That ${kind} isn't one of this page's images.`, field };
    }
  }
  if ("photoOrder" in input && input.photoOrder !== undefined) {
    if (!Array.isArray(input.photoOrder)) return { ok: false, error: "Bad photo order.", field: "photos" };
    const ids = [...new Set(input.photoOrder)];
    if (!ids.every((id) => mediaOf(id, "photo"))) return { ok: false, error: "A photo in the gallery isn't one of this page's images.", field: "photos" };
    if (ids.length > L.photos) return { ok: false, error: `Up to ${L.photos} photos.`, field: "photos" };
    out.photoOrder = ids as string[];
  }
  if ("captions" in input && input.captions !== undefined) {
    if (!input.captions || typeof input.captions !== "object" || Array.isArray(input.captions)) return { ok: false, error: "Bad captions.", field: "photos" };
    const caps: Record<string, string> = {};
    for (const [id, c] of Object.entries(input.captions)) {
      if (!ctx.media.some((m) => m.id === id)) return { ok: false, error: "A caption points at an image this page doesn't have.", field: "photos" };
      caps[id] = line(c).slice(0, L.captionMax);
    }
    out.captions = caps;
  }
  if (!Object.keys(out).length) return { ok: false, error: "Nothing to save.", field: "form" };
  return { ok: true, clean: out };
}

/** Stored links / changelog read back defensively. */
export function readLinks(raw: unknown): ListingLink[] {
  if (!Array.isArray(raw)) return [];
  return raw.flatMap((l) => {
    if (!l || typeof l !== "object") return [];
    const url = cleanLinkUrl((l as ListingLink).url);
