  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(raw as Record<string, unknown>)) if (idRe.test(k) && typeof v === "string" && v.trim()) out[k] = v.slice(0, LISTING_LIMITS.changelogMax);
