// Cyrus remixes: the PURE rules (client-safe, unit-tested).
//
// "Remix in my Cyrus" makes the viewer their own copy of one published version (jar + generated docs,
// CyrusFork + CyrusRemix rows) and opens it in Cyrus, seeded with the original's prompt history. The
// remix gets its own page (private until its creator publishes it); once public, its versions show
// under "Community versions" on every page above it in the chain, and the credit line
// ("Remixed from X by Y") follows it down the chain.
import type { RemixPolicy } from "./listing";

export type RemixViewer = { id: string; role?: string | null } | null;
export type RemixPage = { userId: string; visibility: string; hiddenAt: Date | string | null };

export type RemixDecision =
  | { ok: true; mode: "own" | "remix" }
  | { ok: false; reason: "sign-in" | "no-cyrus" | "not-found" | "closed" | "unsafe"; message: string };

/**
 * May this viewer remix this page? `hasCyrus` = they pass the Cyrus studio gate (private preview
 * today). `scanVerdict` = the source version's safety verdict (a blocked build is never remixable).
 */
export function remixDecision(args: { viewer: RemixViewer; page: RemixPage; policy: RemixPolicy | null | undefined; hasCyrus: boolean; scanVerdict?: string | null }): RemixDecision {
  const { viewer, page } = args;
  if (!viewer) return { ok: false, reason: "sign-in", message: "Sign in to remix this mod in your Cyrus." };
  if (!args.hasCyrus) return { ok: false, reason: "no-cyrus", message: "Cyrus is in private preview. Remixing opens up when it launches." };
  if (viewer.id === page.userId) return { ok: true, mode: "own" };
  if (page.visibility !== "PUBLIC" || page.hiddenAt) return { ok: false, reason: "not-found", message: "Not found." };
  if ((args.policy ?? "OPEN") === "CLOSED") return { ok: false, reason: "closed", message: "The creator has turned off remixing for this mod. You can still download its source under its licence." };
  if (args.scanVerdict === "block") return { ok: false, reason: "unsafe", message: "This version didn't pass the safety check, so it can't be remixed." };
  return { ok: true, mode: "remix" };
}

/** A node in the remix lineage: one Cyrus mod page. */
export type LineageNode = {
  pageId: string;
  slug: string;
  title: string;
  creator: string;
  parentPageId: string | null;
  /** Label of the parent's version this was remixed from ("v2 · 1.1.0"), when known. */
  baseLabel?: string | null;
  /** May the current viewer see this page? */
  visible: boolean;
  createdAt?: string;
  stars?: number;
  versions?: number;
};

export type Credit = { pageId: string; slug: string | null; title: string | null; creator: string; baseLabel: string | null };

/** Ancestors of a page, immediate parent first, up to the original. Cycle- and depth-safe. Invisible pages keep their creator's name (credit) but not their title or link. */
export function creditChain(pageId: string, nodes: Map<string, LineageNode>, max = 25): Credit[] {
  const out: Credit[] = [];
  const seen = new Set<string>([pageId]);
  let cur = nodes.get(pageId);
  while (cur?.parentPageId && out.length < max) {
    const base = cur.baseLabel ?? null;
    const parent = nodes.get(cur.parentPageId);
    if (!parent || seen.has(parent.pageId)) break;
    seen.add(parent.pageId);
    out.push(parent.visible ? { pageId: parent.pageId, slug: parent.slug, title: parent.title, creator: parent.creator, baseLabel: base } : { pageId: parent.pageId, slug: null, title: null, creator: parent.creator, baseLabel: base });
    cur = parent;
  }
  return out;
}

/** "Remixed from Frost Blade by Ana" (+ " · originally Ice Core by Bo" when deeper). */
export function creditLine(chain: Credit[]): string | null {
  if (!chain.length) return null;
  const name = (c: Credit) => (c.title ? `${c.title} by ${c.creator}` : `a mod by ${c.creator} that is no longer public`);
  const first = `Remixed from ${name(chain[0])}`;
  return chain.length > 1 ? `${first} · originally ${name(chain[chain.length - 1])}` : first;
}

export type TreeNode = LineageNode & { depth: number; children: TreeNode[]; anonymous: boolean };

/**
 * The remix tree under `rootPageId`. Pages the viewer can't see are dropped unless a visible remix
 * hangs below them (then they show as an anonymous "private remix" so the branch still reads).
 */
export function buildRemixTree(rootPageId: string, nodes: LineageNode[], opts: { maxDepth?: number; maxNodes?: number } = {}): TreeNode | null {
  const maxDepth = opts.maxDepth ?? 8;
  const maxNodes = opts.maxNodes ?? 250;
  const byParent = new Map<string, LineageNode[]>();
  for (const n of nodes) if (n.parentPageId) byParent.set(n.parentPageId, [...(byParent.get(n.parentPageId) ?? []), n]);
  const root = nodes.find((n) => n.pageId === rootPageId);
  if (!root) return null;
  let count = 0;
  const seen = new Set<string>();
  const walk = (n: LineageNode, depth: number): TreeNode | null => {
    if (seen.has(n.pageId) || count >= maxNodes) return null;
    seen.add(n.pageId);
    count++;
    const kids = depth >= maxDepth ? [] : (byParent.get(n.pageId) ?? [])
      .slice()
      .sort((a, b) => (b.stars ?? 0) - (a.stars ?? 0) || (a.createdAt ?? "").localeCompare(b.createdAt ?? ""))
      .map((c) => walk(c, depth + 1))
      .filter((c): c is TreeNode => !!c);
    if (!n.visible && depth > 0 && !kids.length) return null;
    return { ...n, depth, children: kids, anonymous: !n.visible && depth > 0 };
  };
  return walk(root, 0);
}

export const treeSize = (t: TreeNode | null): number => (t ? 1 + t.children.reduce((s, c) => s + treeSize(c), 0) : 0);

/** The top of a page's chain: its origin when it is a remix, else itself. */
export function originOf(pageId: string, nodes: Map<string, LineageNode>): string {
  const chain = creditChain(pageId, nodes);
  return chain.length ? chain[chain.length - 1].pageId : pageId;
}

/** Depth of a new remix of `parentPageId` (1 for a remix of an original). */
export const remixDepth = (parentPageId: string, nodes: Map<string, LineageNode>) => creditChain(parentPageId, nodes).length + 1;

export type PromptStep = { prompt: string; changeRequest: string | null; status: string; createdAt: Date | string };

/**
 * The notes a new remix opens with in Cyrus (the project's Notes tab, editable): where it came from
 * and how the original was made, so the next change request starts from the same understanding.
 * Capped at `max` characters (CyrusMeta notes limit).
 */
export function remixNotes(args: { title: string; creator: string; baseLabel: string; license: string; slug: string; steps: PromptStep[] }, max = 4000): string {
  const head = [
    `# Remixed from ${args.title}`,
    "",
    `By ${args.creator}, based on ${args.baseLabel}. Licence: ${args.license}. The original's licence and credit travel with this code.`,
    `Original page: /dashboard/nxlabs/cyrus/${args.slug}`,
    "",
    "When you publish your changes, they appear under Community versions on the original's page.",
    "",
    "## How the original was made",
  ];
  const steps = args.steps.filter((s) => s.status === "succeeded");
  const lines = steps.map((s, i) => `${i + 1}. ${(i === 0 ? s.prompt : s.changeRequest || s.prompt).replace(/\s+/g, " ").trim()}`);
  let out = head.join("\n");
  for (const l of lines) {
    const next = `${out}\n${l.length > 600 ? l.slice(0, 597) + "…" : l}`;
    if (next.length > max - 40) { out += `\n… and ${lines.length - lines.indexOf(l)} more step(s).`; break; }
    out = next;
  }
  return out.slice(0, max);
}

/** Title of a fresh remix in the remixer's Cyrus. */
export const remixTitle = (title: string) => `${title.replace(/\s+\((fork|remix)\)$/i, "")} (remix)`.slice(0, 60);

