// "Community-tested": the objective status that earns a Cyrus mod the laurel badge. PURE + tested.
//
// Computed every time from real data, never set by hand and never stored as a flag:
//   installs     ServerMod rows of this mod that are on a server right now, counted per DISTINCT
//                account, the creator's own servers excluded;
//   ratings      CyrusModRating rows (only accounts that installed it may rate; never the creator);
//   bugs         open, visible BUG threads about the current version (or about no version);
//   versions     the current version's Minecraft target vs. the newest version Cyrus builds for;
//   safety       the current version's build-service safety verdict;
//   time         how long the current version has been out.
// A mod earns the laurel only when EVERY check passes. The page shows the checklist, so a creator
// can see exactly what is missing.

export const COMMUNITY_TESTED = {
  minInstallers: 5,
  minRatings: 3,
  minAverage: 4.0,
  minDaysOut: 7,
} as const;

export type TestedInput = {
  isPublic: boolean;
  /** Distinct accounts (not the creator) with it on a server now. */
  installers: number;
  ratings: { count: number; average: number | null };
  /** Open BUG threads on the current version (or untagged). */
  openBugs: number;
  currentMc: string | null;
  /** Newest Minecraft version Cyrus builds for (lib/modbuilder/types MB_VERSIONS[0]). */
  newestMc: string;
  safety: "pass" | "warn" | "block" | null;
  currentAt: string | null;
  now?: Date;
};

export type TestedCheck = { id: "public" | "installs" | "ratings" | "bugs" | "version" | "safety" | "time"; label: string; ok: boolean; detail: string };
export type TestedStatus = { earned: boolean; checks: TestedCheck[]; passed: number };

const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;

export function evaluateCommunityTested(i: TestedInput): TestedStatus {
  const C = COMMUNITY_TESTED;
  const now = i.now ?? new Date();
  const days = i.currentAt ? Math.floor((now.getTime() - Date.parse(i.currentAt)) / 86_400_000) : 0;
  const avg = i.ratings.average;
  const checks: TestedCheck[] = [
    { id: "public", label: "Published on NxLabs", ok: i.isPublic, detail: i.isPublic ? "Public" : "Private pages can't be community-tested" },
    { id: "installs", label: `On ${C.minInstallers}+ other people's servers`, ok: i.installers >= C.minInstallers, detail: `${plural(i.installers, "account")} running it now` },
    { id: "ratings", label: `${C.minRatings}+ ratings from installers, ${C.minAverage.toFixed(1)}+ average`, ok: i.ratings.count >= C.minRatings && avg !== null && avg >= C.minAverage, detail: i.ratings.count ? `${plural(i.ratings.count, "rating")}, ${avg?.toFixed(1)} average` : "No ratings yet" },
    { id: "bugs", label: "No open bug reports on the current version", ok: i.openBugs === 0, detail: i.openBugs ? `${plural(i.openBugs, "open bug report")}` : "None open" },
    { id: "version", label: `Built for the newest Minecraft (${i.newestMc})`, ok: !!i.currentMc && compareMc(i.currentMc, i.newestMc) >= 0, detail: i.currentMc ? `Current version targets ${i.currentMc}` : "No finished version" },
    { id: "safety", label: "Passed the safety check", ok: i.safety === "pass" || i.safety === "warn", detail: i.safety === "pass" ? "Passed" : i.safety === "warn" ? "Passed with notes" : i.safety === "block" ? "Blocked" : "Not scanned" },
    { id: "time", label: `Current version out for ${C.minDaysOut}+ days`, ok: days >= C.minDaysOut, detail: `${plural(Math.max(0, days), "day")} so far` },
  ];
  const passed = checks.filter((c) => c.ok).length;
  return { earned: passed === checks.length, checks, passed };
}

/** Numeric Minecraft version compare: "1.21.11" > "1.21.8". */
export function compareMc(a: string, b: string): number {
  const pa = a.split(".").map((x) => parseInt(x, 10) || 0);
  const pb = b.split(".").map((x) => parseInt(x, 10) || 0);
  for (let k = 0; k < Math.max(pa.length, pb.length); k++) {
    const d = (pa[k] ?? 0) - (pb[k] ?? 0);
    if (d) return d < 0 ? -1 : 1;
  }
  return 0;
}

export type CompatTag = { label: string; tone: "ok" | "old" | "info"; title: string };

/**
 * "Works with" tags from facts only: what the versions were compiled and scanned against, plus an
 * out-of-date warning when the current version targets an older Minecraft than Cyrus builds for.
 */
export function compatTags(args: { currentMc: string | null; builtFor: string[]; newestMc: string; software: string[] }): CompatTag[] {
  const out: CompatTag[] = [];
  if (args.currentMc) out.push({ label: `Works with MC ${args.currentMc}`, tone: compareMc(args.currentMc, args.newestMc) >= 0 ? "ok" : "info", title: `The current version was compiled against the Paper API for Minecraft ${args.currentMc} and passed the safety check.` });
  for (const v of args.builtFor) if (v !== args.currentMc) out.push({ label: `Earlier builds: MC ${v}`, tone: "info", title: `Older versions of this mod were built for Minecraft ${v}.` });
  for (const s of args.software) out.push({ label: s, tone: "info", title: `Runs on ${s} servers.` });
  if (args.currentMc && compareMc(args.currentMc, args.newestMc) < 0) out.push({ label: `Needs an update for ${args.newestMc}`, tone: "old", title: `Cyrus now builds for Minecraft ${args.newestMc}; this mod's current version targets ${args.currentMc}.` });
  return out;
}

/** Average of 1-5 scores, one decimal; null for none. */
export function averageScore(scores: number[]): number | null {
  const ok = scores.filter((s) => Number.isInteger(s) && s >= 1 && s <= 5);
  if (!ok.length) return null;
  return Math.round((ok.reduce((a, b) => a + b, 0) / ok.length) * 10) / 10;
}

export const isScore = (x: unknown): x is number => typeof x === "number" && Number.isInteger(x) && x >= 1 && x <= 5;

/** Who may rate: signed in, not the creator, and has (or had) it on one of their own servers. */
export function rateDecision(args: { viewerId: string | null; creatorId: string; installedByViewer: boolean }): { ok: true } | { ok: false; message: string } {
  if (!args.viewerId) return { ok: false, message: "Sign in to rate." };
  if (args.viewerId === args.creatorId) return { ok: false, message: "You can't rate your own mod." };
  if (!args.installedByViewer) return { ok: false, message: "Install it on one of your servers first. Ratings come from people who ran it." };
  return { ok: true };
}

/** ServerMod statuses that mean "it is on that server right now". */
export const ON_SERVER_STATUSES = ["INSTALLED", "DISABLED", "UPDATING", "INSTALLING"];

/** Distinct installer accounts, the creator excluded. */
export function countInstallers(rows: { userId: string }[], creatorId: string): number {
  return new Set(rows.map((r) => r.userId).filter((u) => u !== creatorId)).size;
}

