// Re-scan of remixed code (PURE, unit-tested). Runs in the portal when someone remixes a Cyrus mod,
// BEFORE their copy exists and before any build of it.
//
// The build service's scanner (services/modbuilder/scan.js) has two layers: a bytecode scan (javap,
// needs a JDK, so it only runs on the build VM) and source heuristics. The jar a remix copies was
// already bytecode-scanned when it was built; this re-scan proves the copy is that same jar
// (sha256 against ModBuild.jarSha256) and re-runs the SOURCE heuristics on the version's code. The
// rules below are a line-for-line port of scanSource() — keep them in step with scan.js. Every
// later change request on the remix is a normal build, so the service scans it in full again.
export type ScanFinding = { severity: "block" | "warn"; rule: string; where: string; message: string; evidence: string };
export type RescanResult = { verdict: "pass" | "warn" | "block"; findings: ScanFinding[]; files: number; checksumOk: boolean | null; at: string };

const uuidRe = /"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"/;
const absPathRe = /"(\/(etc|root|home|proc|sys|var|tmp|opt|usr|bin|dev)\b[^"]*|[A-Za-z]:\\\\[^"]*|[^"]*\.\.[/\\][^"]*|~\/[^"]*)"/;
const nameCheckRe = /getName\(\)\s*\.\s*equals(IgnoreCase)?\s*\(\s*"[^"]+"\s*\)|"[^"]+"\s*\.\s*equals(IgnoreCase)?\s*\([^)]*getName\(\)/;
const blobRe = /"[A-Za-z0-9+/=]{200,}"/;
const secretRe = /sk-ant-[A-Za-z0-9_-]{10,}/;

/** scanSource() from services/modbuilder/scan.js, over text instead of files on disk. */
export function scanSourceText(files: { path: string; text: string }[]): ScanFinding[] {
  const findings: ScanFinding[] = [];
  for (const f of files) {
    if (!f.path.endsWith(".java")) continue;
    const lines = f.text.split("\n");
    const privileged = /setOp\s*\(\s*true|addAttachment|dispatchCommand|setPermission/.test(f.text);
    lines.forEach((l, i) => {
      const at = `${f.path}:${i + 1}`;
      if (absPathRe.test(l) && /File|Path|Files|FileWriter|FileReader|Stream/.test(l)) findings.push({ severity: "block", rule: "file-outside", where: at, message: "reads or writes files outside the plugin's own folder", evidence: l.trim().slice(0, 200) });
      if (blobRe.test(l)) findings.push({ severity: "block", rule: "encoded-blob", where: at, message: "contains a large encoded blob (possible hidden payload)", evidence: l.trim().slice(0, 80) + "…" });
      if (uuidRe.test(l)) findings.push({ severity: privileged ? "block" : "warn", rule: "hardcoded-uuid", where: at, message: privileged ? "gives special rights to a hard-coded player" : "contains a hard-coded player ID", evidence: l.trim().slice(0, 200) });
      if (nameCheckRe.test(l) && privileged) findings.push({ severity: "block", rule: "hardcoded-name", where: at, message: "gives special rights to a hard-coded player name", evidence: l.trim().slice(0, 200) });
    });
  }
  // The portal never hands a key to the model, but a copied tree must not carry one either.
  for (const f of files) if (secretRe.test(f.text)) findings.push({ severity: "block", rule: "secret", where: f.path, message: "contains what looks like an API key", evidence: "(redacted)" });
  const seen = new Set<string>();
  return findings.filter((x) => {
    const k = `${x.severity}|${x.rule}|${x.where}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
