/**
 * Combine: the build's own verdict, the re-run source heuristics and the jar checksum.
 * A checksum mismatch, a stored block or any block finding blocks the remix.
 */
export function rescanVerdict(args: { stored: "pass" | "warn" | "block" | null | undefined; findings: ScanFinding[]; checksumOk: boolean | null; files: number; now?: Date }): RescanResult {
  const block = args.stored === "block" || args.checksumOk === false || args.findings.some((f) => f.severity === "block");
  const warn = args.stored === "warn" || args.findings.some((f) => f.severity === "warn");
  const findings = args.checksumOk === false ? [{ severity: "block" as const, rule: "checksum", where: "jar", message: "the plugin file doesn't match the one that was scanned", evidence: "sha256 mismatch" }, ...args.findings] : args.findings;
  return { verdict: block ? "block" : warn ? "warn" : "pass", findings: findings.slice(0, 50), files: args.files, checksumOk: args.checksumOk, at: (args.now ?? new Date()).toISOString() };
}

/** Which of a build's files the re-scan reads (source and resources; never build output). */
export function rescanPaths(files: { path: string; size: number }[], maxFiles = 80, maxBytes = 1_500_000): string[] {
  let total = 0;
  const out: string[] = [];
  for (const f of files) {
    if (!/^src\/main\/(java|resources)\//.test(f.path) || !/\.(java|yml|yaml|json|properties|txt)$/.test(f.path)) continue;
    if (out.length >= maxFiles || total + f.size > maxBytes) break;
    total += f.size;
    out.push(f.path);
  }
  return out;
}

