// Cyrus mod page images (icon, banner, gallery photos): the SERVER half. Every upload is decoded and
// re-encoded to WebP with sharp (EXIF/GPS dropped, animation flattened, size-capped), stored
// content-addressed next to the jars (MODBUILD_DIR/nxlabs-media/<aa>/<sha256>.webp) and served by
// /api/nxlabs/cyrus/media/<CyrusModMedia.id> with the page's own visibility rule.
import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile, access } from "node:fs/promises";
import { join, dirname } from "node:path";
import sharp from "sharp";
import { MODBUILD_DIR } from "../modbuilder/store";
import { sniffImage } from "../cyrus/uploads";
import { LISTING_LIMITS, MEDIA_KINDS, type MediaKind } from "./listing";

export const MEDIA_DIR = join(MODBUILD_DIR, "nxlabs-media");
const KEY_RE = /^[a-f0-9]{64}$/;

export function mediaPath(key: string): string {
  if (!KEY_RE.test(key)) throw new Error("bad media key");
  return join(MEDIA_DIR, key.slice(0, 2), `${key}.webp`);
}

export type StoredImage = { key: string; width: number | null; height: number | null; bytes: number };

export async function storeListingImage(bytes: Uint8Array, kind: MediaKind): Promise<{ ok: true; image: StoredImage } | { ok: false; error: string }> {
  if (!bytes.length) return { ok: false, error: "That image is empty." };
  if (bytes.length > LISTING_LIMITS.imageBytes) return { ok: false, error: "Images can be up to 8 MB." };
  if (!sniffImage(bytes)) return { ok: false, error: "Use a PNG, JPG, WebP or GIF image." };
  const k = MEDIA_KINDS[kind];
  let out: Buffer;
  let info: sharp.OutputInfo;
  try {
    const r = await sharp(Buffer.from(bytes), { limitInputPixels: 40_000_000, animated: false })
      .rotate()
      .resize({ width: k.width, height: "height" in k ? k.height : undefined, fit: k.fit, withoutEnlargement: kind === "photo" })
      .webp({ quality: kind === "icon" ? 86 : 80 })
      .toBuffer({ resolveWithObject: true });
    out = r.data;
    info = r.info;
  } catch {
    return { ok: false, error: "That file couldn't be read as an image." };
  }
  const key = createHash("sha256").update(out).digest("hex");
  const p = mediaPath(key);
  try {
    await access(p);
  } catch {
    await mkdir(dirname(p), { recursive: true, mode: 0o750 });
    const tmp = `${p}.${process.pid}.${Date.now()}.tmp`;
    await writeFile(tmp, out, { mode: 0o640 });
    await rename(tmp, p);
  }
  return { ok: true, image: { key, width: info.width ?? null, height: info.height ?? null, bytes: out.length } };
}

export async function readListingImage(key: string): Promise<Buffer | null> {
  try {
    return await readFile(mediaPath(key));
  } catch {
    return null;
  }
}

