// Cyrus community: the SERVER read side (NxLabs pages, cards, profiles, collections, the Cyrus
// library). Every number here is counted from real rows; nothing is estimated or seeded.
// Plain module (no next/* imports). Writers: lib/actions-cyrus-community.ts.
import type { CyrusModListing, CyrusModMedia, CyrusModPage } from "@prisma/client";
import { randomBytes } from "node:crypto";
import { db } from "../db";
import { MB_VERSIONS } from "../modbuilder/types";
import { CYRUS_SOURCE } from "../mods/installers/cyrus";
import { pageVisibleTo, readModDoc, slugifyModName, versionLabel, type CyrusModDoc } from "./doc";
import { displayUser } from "./pages";
import { DEFAULT_REMIX_POLICY, isRemixPolicy, listingHtml, listingMediaUrl, readChangelog, readLinks, type ListingLink, type RemixPolicy } from "./listing";
import { buildRemixTree, creditChain, creditLine, remixDecision, type Credit, type LineageNode, type RemixDecision, type TreeNode } from "./remix";
import { averageScore, compatTags, countInstallers, evaluateCommunityTested, ON_SERVER_STATUSES, rateDecision, type CompatTag, type TestedStatus } from "./tested";

type Viewer = { id: string; role?: string | null } | null;
export const NEWEST_MC: string = MB_VERSIONS[0];

// ── listing + media ─────────────────────────────────────────────────────────

export type MediaView = { id: string; url: string; kind: "photo" | "icon" | "banner"; caption: string | null; width: number | null; height: number | null; hidden: boolean };
export type ListingView = {
  tagline: string | null;
  description: string | null;
  descriptionHtml: string;
  category: string | null;
  tags: string[];
  links: ListingLink[];
  changelog: Record<string, string>;
  remixPolicy: RemixPolicy;
  icon: MediaView | null;
  banner: MediaView | null;
  photos: MediaView[];
  endorsedBuildId: string | null;
  customised: boolean;
};

const mediaView = (m: CyrusModMedia): MediaView => ({ id: m.id, url: listingMediaUrl(m.id), kind: m.kind === "icon" || m.kind === "banner" ? m.kind : "photo", caption: m.caption, width: m.width, height: m.height, hidden: !!m.hiddenAt });

export function toListingView(listing: CyrusModListing | null, media: CyrusModMedia[], canSeeHidden: boolean): ListingView {
  const visible = media.filter((m) => !m.hiddenAt || canSeeHidden);
  const byId = new Map(visible.map((m) => [m.id, m]));
  const icon = listing?.iconMediaId ? byId.get(listing.iconMediaId) : undefined;
  const banner = listing?.bannerMediaId ? byId.get(listing.bannerMediaId) : undefined;
  return {
    tagline: listing?.tagline ?? null,
    description: listing?.description ?? null,
    descriptionHtml: listingHtml(listing?.description),
    category: listing?.category ?? null,
    tags: listing?.tags ?? [],
    links: readLinks(listing?.links),
    changelog: readChangelog(listing?.changelog),
    remixPolicy: isRemixPolicy(listing?.remixPolicy) ? listing!.remixPolicy as RemixPolicy : DEFAULT_REMIX_POLICY,
    icon: icon ? mediaView(icon) : null,
    banner: banner ? mediaView(banner) : null,
    photos: visible.filter((m) => m.kind === "photo").sort((a, b) => a.sort - b.sort || a.createdAt.getTime() - b.createdAt.getTime()).map(mediaView),
    endorsedBuildId: listing?.endorsedBuildId ?? null,
    customised: !!listing,
  };
}

export async function listingsFor(pageIds: string[]): Promise<{ listings: Map<string, CyrusModListing>; media: Map<string, CyrusModMedia[]> }> {
  if (!pageIds.length) return { listings: new Map(), media: new Map() };
  const [ls, ms] = await Promise.all([
    db.cyrusModListing.findMany({ where: { pageId: { in: pageIds } } }),
    db.cyrusModMedia.findMany({ where: { pageId: { in: pageIds } }, orderBy: [{ sort: "asc" }, { createdAt: "asc" }], take: 40 * pageIds.length }),
  ]);
  const media = new Map<string, CyrusModMedia[]>();
  for (const m of ms) media.set(m.pageId, [...(media.get(m.pageId) ?? []), m]);
  return { listings: new Map(ls.map((l) => [l.pageId, l])), media };
}

// ── stats (batched) ─────────────────────────────────────────────────────────

export type PageStats = {
  stars: number;
  /** Distinct accounts (creator excluded) with it on a server now. */
  installers: number;
  /** Servers with it on now (any account, the creator's included). */
  servers: number;
  serversOnCurrent: number;
  ratings: { count: number; average: number | null };
  remixes: number;
  libraryAdds: number;
  openBugsCurrent: number;
};

export async function statsFor(pages: Pick<CyrusModPage, "id" | "rootBuildId" | "userId" | "latestBuildId">[]): Promise<Map<string, PageStats>> {
  const out = new Map<string, PageStats>();
  if (!pages.length) return out;
  const ids = pages.map((p) => p.id);
  const roots = pages.map((p) => p.rootBuildId);
  const [stars, ratings, remixes, lib, bugs, installs] = await Promise.all([
    db.cyrusModStar.groupBy({ by: ["pageId"], where: { pageId: { in: ids } }, _count: { _all: true } }),
    db.cyrusModRating.findMany({ where: { pageId: { in: ids } }, select: { pageId: true, score: true, userId: true } }),
    db.cyrusFork.groupBy({ by: ["sourcePageId"], where: { sourcePageId: { in: ids } }, _count: { _all: true } }),
    db.cyrusLibraryItem.groupBy({ by: ["pageId"], where: { pageId: { in: ids } }, _count: { _all: true } }),
    db.cyrusModPost.findMany({ where: { pageId: { in: ids }, parentId: null, kind: "BUG", status: "OPEN", hiddenAt: null }, select: { pageId: true, buildId: true }, take: 5000 }),
    db.serverMod.findMany({
      where: { status: { in: ON_SERVER_STATUSES }, mod: { source: CYRUS_SOURCE, sourceId: { in: roots } } },
      select: { serverId: true, versionId: true, mod: { select: { sourceId: true } }, server: { select: { userId: true } } },
      take: 20000,
    }),
  ]);
  for (const p of pages) {
    const mine = installs.filter((r) => r.mod.sourceId === p.rootBuildId);
    const rs = ratings.filter((r) => r.pageId === p.id && r.userId !== p.userId);
    out.set(p.id, {
      stars: stars.find((s) => s.pageId === p.id)?._count._all ?? 0,
      installers: countInstallers(mine.map((r) => ({ userId: r.server.userId })), p.userId),
      servers: new Set(mine.map((r) => r.serverId)).size,
      serversOnCurrent: new Set(mine.filter((r) => !!p.latestBuildId && r.versionId === p.latestBuildId).map((r) => r.serverId)).size,
      ratings: { count: rs.length, average: averageScore(rs.map((r) => r.score)) },
      remixes: remixes.find((r) => r.sourcePageId === p.id)?._count._all ?? 0,
      libraryAdds: lib.find((l) => l.pageId === p.id)?._count._all ?? 0,
      openBugsCurrent: bugs.filter((b) => b.pageId === p.id && (!b.buildId || b.buildId === p.latestBuildId)).length,
    });
  }
  return out;
}

export function testedFor(page: Pick<CyrusModPage, "visibility" | "hiddenAt">, doc: CyrusModDoc, s: PageStats, now = new Date()): TestedStatus {
  const cur = doc.versions.find((v) => v.buildId === doc.currentBuildId) ?? doc.versions[0];
  return evaluateCommunityTested({
    isPublic: page.visibility === "PUBLIC" && !page.hiddenAt,
    installers: s.installers,
    ratings: s.ratings,
    openBugs: s.openBugsCurrent,
    currentMc: cur?.mcVersion ?? null,
    newestMc: NEWEST_MC,
    safety: cur?.safety ?? null,
    currentAt: cur?.at ?? null,
    now,
  });
}

// ── lineage ─────────────────────────────────────────────────────────────────

type Fam = { page: CyrusModPage; parentPageId: string | null; parentBuildId: string | null; scan: string | null };

/** Parent of a page: its CyrusRemix row, else (legacy forks) CyrusModPage.forkOf*. */
async function parentsOf(pages: CyrusModPage[]): Promise<Map<string, { parentPageId: string; parentBuildId: string | null; scan: string | null }>> {
  const out = new Map<string, { parentPageId: string; parentBuildId: string | null; scan: string | null }>();
  if (!pages.length) return out;
  const rx = await db.cyrusRemix.findMany({ where: { buildId: { in: pages.map((p) => p.rootBuildId) } } });
  for (const p of pages) {
    const r = rx.find((x) => x.buildId === p.rootBuildId);
    const scan = r?.scan && typeof r.scan === "object" ? String((r.scan as { verdict?: unknown }).verdict ?? "") || null : null;
    if (r) out.set(p.id, { parentPageId: r.parentPageId, parentBuildId: r.parentBuildId, scan });
    else if (p.forkOfPageId) out.set(p.id, { parentPageId: p.forkOfPageId, parentBuildId: p.forkOfBuildId, scan: null });
  }
  return out;
}

/** Walk up from a page to the original (max 25 levels). Returns the ancestors, parent first. */
async function ancestorsOf(page: CyrusModPage): Promise<Fam[]> {
  const out: Fam[] = [];
  const seen = new Set([page.id]);
  let cur = page;
  for (let i = 0; i < 25; i++) {
    const par = (await parentsOf([cur])).get(cur.id);
    if (!par || seen.has(par.parentPageId)) break;
    const parent = await db.cyrusModPage.findUnique({ where: { id: par.parentPageId } });
    if (!parent) break;
    seen.add(parent.id);
    const pp = (await parentsOf([parent])).get(parent.id);
    out.push({ page: parent, parentPageId: pp?.parentPageId ?? null, parentBuildId: pp?.parentBuildId ?? null, scan: pp?.scan ?? null });
    cur = parent;
  }
  return out;
}

/** Every page below `rootId` (BFS by level over CyrusRemix + legacy CyrusFork), bounded. */
async function descendantsOf(rootId: string, maxDepth = 8, maxNodes = 250): Promise<Fam[]> {
  const out: Fam[] = [];
  const seen = new Set([rootId]);
  let level = [rootId];
  for (let d = 0; d < maxDepth && level.length && out.length < maxNodes; d++) {
    const [rx, forks] = await Promise.all([
      db.cyrusRemix.findMany({ where: { parentPageId: { in: level } }, take: maxNodes }),
      db.cyrusFork.findMany({ where: { sourcePageId: { in: level } }, take: maxNodes }),
    ]);
    const roots = [...new Set([...rx.map((r) => r.buildId), ...forks.map((f) => f.buildId)])];
    const pages = roots.length ? await db.cyrusModPage.findMany({ where: { rootBuildId: { in: roots } } }) : [];
    const next: string[] = [];
    for (const p of pages) {
      if (seen.has(p.id)) continue;
      seen.add(p.id);
      const r = rx.find((x) => x.buildId === p.rootBuildId);
      const f = forks.find((x) => x.buildId === p.rootBuildId);
      const scan = r?.scan && typeof r.scan === "object" ? String((r.scan as { verdict?: unknown }).verdict ?? "") || null : null;
      out.push({ page: p, parentPageId: r?.parentPageId ?? f?.sourcePageId ?? p.forkOfPageId, parentBuildId: r?.parentBuildId ?? p.forkOfBuildId, scan });
      next.push(p.id);
    }
    level = next;
  }
  return out;
}

const labelIn = (doc: CyrusModDoc | null, buildId: string | null) => {
  const v = buildId ? doc?.versions.find((x) => x.buildId === buildId) : undefined;
  return v ? versionLabel(v) : null;
};

// ── community versions ──────────────────────────────────────────────────────

export type CommunityVersion = { buildId: string; label: string; notes: string; at: string; mcVersion: string; safety: "pass" | "warn" | "block" | null; openBugs: number };
export type CommunityVersionGroup = {
  pageId: string;
  slug: string;
  title: string;
  creator: string;
  creatorHandle: string | null;
  depth: number;
  /** Set for remixes of remixes: the remix in between. */
  via: { slug: string; title: string } | null;
  /** The version of THIS page the chain started from. */
  baseBuildId: string | null;
  baseLabel: string | null;
  scan: string | null;
  stars: number;
  installers: number;
  versions: CommunityVersion[];
  updatedAt: string;
};

// ── the whole community view of one page ────────────────────────────────────

export type CommunityView = {
  listing: ListingView;
  stats: PageStats;
  tested: TestedStatus;
  compat: CompatTag[];
  credit: Credit[];
  creditLine: string | null;
  creatorHandle: string | null;
  versions: CommunityVersionGroup[];
  endorsed: { group: CommunityVersionGroup; version: CommunityVersion } | null;
  tree: TreeNode | null;
  viewer: {
    signedIn: boolean;
    isCreator: boolean;
    starred: boolean;
    inLibrary: boolean;
    myRating: number | null;
    rate: { ok: true } | { ok: false; message: string };
    remix: RemixDecision;
  };
};

export async function communityFor(page: CyrusModPage, viewer: Viewer, opts: { hasCyrus: boolean }): Promise<CommunityView | null> {
  const doc = readModDoc(page.doc);
  if (!doc) return null;
  const isCreator = !!viewer && viewer.id === page.userId;
  const canSeeHidden = isCreator || viewer?.role === "ADMIN";

  const [ancestors, descendants] = await Promise.all([ancestorsOf(page), descendantsOf(page.id)]);
  const selfPar = (await parentsOf([page])).get(page.id);
  const family: Fam[] = [{ page, parentPageId: selfPar?.parentPageId ?? null, parentBuildId: selfPar?.parentBuildId ?? null, scan: selfPar?.scan ?? null }, ...ancestors, ...descendants];
  const origin = ancestors.length ? ancestors[ancestors.length - 1].page : page;
  // The tree is rooted at the original; walk down from it only when this page is a remix.
  const originDesc = origin.id === page.id ? descendants : await descendantsOf(origin.id);
  for (const f of originDesc) if (!family.some((x) => x.page.id === f.page.id)) family.push(f);

  const allPages = family.map((f) => f.page);
  const userIds = [...new Set(allPages.map((p) => p.userId))];
  const [users, creators, statsMap, { listings, media }] = await Promise.all([
    db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, name: true } }),
    db.cyrusCreator.findMany({ where: { userId: { in: userIds } }, select: { userId: true, handle: true } }),
    statsFor(allPages),
    listingsFor([page.id]),
  ]);
  const nameOf = (id: string) => displayUser(users.find((u) => u.id === id) ?? null);
  const handleOf = (id: string) => creators.find((c) => c.userId === id)?.handle ?? null;
  const docs = new Map(allPages.map((p) => [p.id, readModDoc(p.doc)]));
  const famBy = new Map(family.map((f) => [f.page.id, f]));
  const nodes = new Map<string, LineageNode>(family.map((f) => {
    const parentDoc = f.parentPageId ? docs.get(f.parentPageId) ?? null : null;
    return [f.page.id, {
      pageId: f.page.id,
      slug: f.page.slug,
      title: f.page.title,
      creator: nameOf(f.page.userId),
      parentPageId: f.parentPageId,
      baseLabel: labelIn(parentDoc, f.parentBuildId),
      visible: pageVisibleTo(f.page, viewer),
      createdAt: f.page.createdAt.toISOString(),
      stars: statsMap.get(f.page.id)?.stars ?? 0,
      versions: docs.get(f.page.id)?.versions.length ?? 0,
    }];
  }));

  const credit = creditChain(page.id, nodes);
  const tree = buildRemixTree(origin.id, [...nodes.values()]);
  const stats = statsMap.get(page.id)!;
  const listing = toListingView(listings.get(page.id) ?? null, media.get(page.id) ?? [], canSeeHidden);

  // Community versions: every PUBLISHED remix below this page with at least one version of its own.
  const bugRows = descendants.length ? await db.cyrusModPost.findMany({ where: { pageId: { in: descendants.map((d) => d.page.id) }, parentId: null, kind: "BUG", status: "OPEN", hiddenAt: null }, select: { pageId: true, buildId: true }, take: 5000 }) : [];
  const groups: CommunityVersionGroup[] = [];
  for (const d of descendants) {
    if (d.page.visibility !== "PUBLIC" || d.page.hiddenAt) continue;
    const dd = docs.get(d.page.id);
    if (!dd) continue;
    const own = dd.versions.filter((v) => v.buildId !== d.page.rootBuildId); // the copy itself is identical to its base
    if (!own.length) continue;
    // Which version of THIS page the chain started from, and the remix in between (if any).
    let step: Fam | undefined = d;
    let via: Fam | null = null;
    let depth = 1;
    while (step && step.parentPageId && step.parentPageId !== page.id && depth < 25) {
      via = famBy.get(step.parentPageId) ?? null;
      step = via ?? undefined;
      depth++;
    }
    const baseBuildId = step?.parentPageId === page.id ? step.parentBuildId : null;
    const s = statsMap.get(d.page.id);
    groups.push({
      pageId: d.page.id,
      slug: d.page.slug,
      title: d.page.title,
      creator: nameOf(d.page.userId),
      creatorHandle: handleOf(d.page.userId),
      depth,
      via: depth > 1 && via && pageVisibleTo(via.page, viewer) ? { slug: via.page.slug, title: via.page.title } : null,
      baseBuildId,
      baseLabel: labelIn(doc, baseBuildId),
      scan: d.scan,
      stars: s?.stars ?? 0,
      installers: s?.installers ?? 0,
      updatedAt: d.page.updatedAt.toISOString(),
      versions: own.map((v) => ({ buildId: v.buildId, label: versionLabel(v), notes: v.notes, at: v.at, mcVersion: v.mcVersion, safety: v.safety, openBugs: bugRows.filter((b) => b.pageId === d.page.id && b.buildId === v.buildId).length })),
    });
  }
  groups.sort((a, b) => a.depth - b.depth || b.stars - a.stars || b.updatedAt.localeCompare(a.updatedAt));
  let endorsed: CommunityView["endorsed"] = null;
  if (listing.endorsedBuildId) {
    for (const g of groups) {
      const v = g.versions.find((x) => x.buildId === listing.endorsedBuildId);
      if (v) { endorsed = { group: g, version: v }; break; }
    }
  }

  const cur = doc.versions.find((v) => v.buildId === doc.currentBuildId) ?? doc.versions[0];
  const [starred, inLib, myRating, installedByViewer] = viewer
    ? await Promise.all([
        db.cyrusModStar.findUnique({ where: { userId_pageId: { userId: viewer.id, pageId: page.id } } }).then((x) => !!x),
        db.cyrusLibraryItem.findUnique({ where: { userId_pageId: { userId: viewer.id, pageId: page.id } } }).then((x) => !!x),
        db.cyrusModRating.findUnique({ where: { userId_pageId: { userId: viewer.id, pageId: page.id } } }).then((x) => x?.score ?? null),
        db.serverMod.count({ where: { mod: { source: CYRUS_SOURCE, sourceId: page.rootBuildId }, server: { userId: viewer.id } } }).then((n) => n > 0),
      ])
    : [false, false, null, false];

  return {
    listing,
    stats,
    tested: testedFor(page, doc, stats),
    compat: compatTags({ currentMc: cur?.mcVersion ?? null, builtFor: doc.compat.mcVersions, newestMc: NEWEST_MC, software: doc.compat.software, serversOnCurrent: stats.serversOnCurrent }),
    credit,
    creditLine: creditLine(credit),
    creatorHandle: handleOf(page.userId),
    versions: groups,
    endorsed,
    tree: tree && tree.children.length ? tree : null,
    viewer: {
      signedIn: !!viewer,
      isCreator,
      starred,
      inLibrary: inLib,
      myRating,
      rate: rateDecision({ viewerId: viewer?.id ?? null, creatorId: page.userId, installedByViewer }),
      remix: remixDecision({ viewer, page, policy: listing.remixPolicy, hasCyrus: opts.hasCyrus, scanVerdict: cur?.safety ?? null }),
    },
  };
}

// ── creators ────────────────────────────────────────────────────────────────

const HANDLE_RE = /^[a-z0-9-]{3,40}$/;
export const isHandle = (h: unknown): h is string => typeof h === "string" && HANDLE_RE.test(h);

/** The creator's public handle, created on first need ("ana-k3f9"). Never derived from the email. */
export async function ensureCreatorHandle(userId: string): Promise<string> {
  const have = await db.cyrusCreator.findUnique({ where: { userId } });
  if (have) return have.handle;
  const u = await db.user.findUnique({ where: { id: userId }, select: { name: true } });
  const base = slugifyModName(displayUser(u)).replace(/^cyrus-mod-?/, "").slice(0, 24) || "creator";
  for (let i = 0; i < 5; i++) {
    const handle = `${base}-${randomBytes(2).toString("hex")}`;
    try {
      return (await db.cyrusCreator.create({ data: { userId, handle } })).handle;
    } catch {
      const again = await db.cyrusCreator.findUnique({ where: { userId } });
      if (again) return again.handle;
    }
  }
  throw new Error("could not allocate a creator handle");
}

export type CreatorView = {
  handle: string;
  name: string;
  bio: string | null;
  isMe: boolean;
  since: string;
  mods: { slug: string; title: string; tagline: string | null; iconUrl: string | null; stars: number; installers: number; tested: boolean; versions: number; remixOf: boolean }[];
  totals: { mods: number; stars: number; installers: number; remixesOfTheirMods: number };
  collections: { slug: string; title: string; count: number }[];
};

export async function creatorProfile(handle: string, viewer: Viewer): Promise<CreatorView | null> {
  if (!isHandle(handle)) return null;
  const c = await db.cyrusCreator.findUnique({ where: { handle } });
  if (!c) return null;
  const isMe = viewer?.id === c.userId;
  const [u, pages, cols] = await Promise.all([
    db.user.findUnique({ where: { id: c.userId }, select: { name: true } }),
    db.cyrusModPage.findMany({ where: isMe ? { userId: c.userId } : { userId: c.userId, visibility: "PUBLIC", hiddenAt: null }, orderBy: { updatedAt: "desc" }, take: 60 }),
    db.cyrusCollection.findMany({ where: isMe ? { userId: c.userId } : { userId: c.userId, visibility: "PUBLIC", hiddenAt: null }, orderBy: { updatedAt: "desc" }, take: 30 }),
  ]);
  const [stats, { listings, media }, counts] = await Promise.all([
    statsFor(pages),
    listingsFor(pages.map((p) => p.id)),
    cols.length ? db.cyrusCollectionItem.groupBy({ by: ["collectionId"], where: { collectionId: { in: cols.map((x) => x.id) } }, _count: { _all: true } }) : Promise.resolve([]),
  ]);
  const mods = pages.flatMap((p) => {
    const d = readModDoc(p.doc);
    if (!d) return [];
    const s = stats.get(p.id)!;
    const lv = toListingView(listings.get(p.id) ?? null, media.get(p.id) ?? [], isMe);
    return [{ slug: p.slug, title: p.title, tagline: p.tagline, iconUrl: lv.icon?.url ?? null, stars: s.stars, installers: s.installers, tested: testedFor(p, d, s).earned, versions: d.versions.length, remixOf: !!p.forkOfPageId }];
  });
  return {
    handle: c.handle,
    name: displayUser(u),
    bio: c.bio,
    isMe,
    since: c.createdAt.toISOString(),
    mods,
    totals: { mods: mods.length, stars: mods.reduce((a, m) => a + m.stars, 0), installers: mods.reduce((a, m) => a + m.installers, 0), remixesOfTheirMods: pages.reduce((a, p) => a + (stats.get(p.id)?.remixes ?? 0), 0) },
    collections: cols.map((x) => ({ slug: x.slug, title: x.title, count: (counts as { collectionId: string; _count: { _all: number } }[]).find((k) => k.collectionId === x.id)?._count._all ?? 0 })),
  };
}

// ── collections ─────────────────────────────────────────────────────────────

export const collectionVisibleTo = (c: { userId: string; visibility: string; hiddenAt: Date | null }, v: Viewer) => !!v && (v.id === c.userId || v.role === "ADMIN") || (c.visibility === "PUBLIC" && !c.hiddenAt);

export type CollectionView = {
  slug: string;
  title: string;
  description: string | null;
  visibility: "PUBLIC" | "PRIVATE";
  isMine: boolean;
  owner: { name: string; handle: string | null };
  items: { slug: string; title: string; tagline: string | null; creator: string; iconUrl: string | null; note: string | null; stars: number; tested: boolean }[];
  /** Items the viewer can no longer see (made private / hidden by their creators). */
  unavailable: number;
};

export async function collectionView(slug: string, viewer: Viewer): Promise<CollectionView | null> {
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const c = await db.cyrusCollection.findUnique({ where: { slug } });
  if (!c || !collectionVisibleTo(c, viewer)) return null;
  const items = await db.cyrusCollectionItem.findMany({ where: { collectionId: c.id }, orderBy: [{ sort: "asc" }, { createdAt: "asc" }], take: 100 });
  const pages = items.length ? await db.cyrusModPage.findMany({ where: { id: { in: items.map((i) => i.pageId) } } }) : [];
  const visible = pages.filter((p) => pageVisibleTo(p, viewer));
  const [owner, handle, users, stats, { listings, media }] = await Promise.all([
    db.user.findUnique({ where: { id: c.userId }, select: { name: true } }),
    db.cyrusCreator.findUnique({ where: { userId: c.userId }, select: { handle: true } }),
    db.user.findMany({ where: { id: { in: [...new Set(visible.map((p) => p.userId))] } }, select: { id: true, name: true } }),
    statsFor(visible),
    listingsFor(visible.map((p) => p.id)),
  ]);
  return {
    slug: c.slug,
    title: c.title,
    description: c.description,
    visibility: c.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE",
    isMine: viewer?.id === c.userId,
    owner: { name: displayUser(owner), handle: handle?.handle ?? null },
    items: items.flatMap((i) => {
      const p = visible.find((x) => x.id === i.pageId);
      const d = p ? readModDoc(p.doc) : null;
      if (!p || !d) return [];
      const s = stats.get(p.id)!;
      return [{ slug: p.slug, title: p.title, tagline: p.tagline, creator: displayUser(users.find((u) => u.id === p.userId) ?? null), iconUrl: toListingView(listings.get(p.id) ?? null, media.get(p.id) ?? [], false).icon?.url ?? null, note: i.note, stars: s.stars, tested: testedFor(p, d, s).earned }];
    }),
    unavailable: items.length - visible.length,
  };
}

export async function myCollections(userId: string, pageId?: string): Promise<{ id: string; slug: string; title: string; visibility: string; count: number; has: boolean }[]> {
  const cols = await db.cyrusCollection.findMany({ where: { userId }, orderBy: { updatedAt: "desc" }, take: 50 });
  if (!cols.length) return [];
  const items = await db.cyrusCollectionItem.findMany({ where: { collectionId: { in: cols.map((c) => c.id) } }, select: { collectionId: true, pageId: true } });
  return cols.map((c) => ({ id: c.id, slug: c.slug, title: c.title, visibility: c.visibility, count: items.filter((i) => i.collectionId === c.id).length, has: !!pageId && items.some((i) => i.collectionId === c.id && i.pageId === pageId) }));
}

// ── the Cyrus library ("Add to my Cyrus") ───────────────────────────────────

export type LibraryEntry = {
  pageId: string;
  slug: string;
  title: string;
  tagline: string | null;
  summary: string | null;
  creator: string;
  license: string;
  iconUrl: string | null;
  category: string | null;
  currentBuildId: string | null;
  versions: { buildId: string; label: string; mcVersion: string; notes: string; at: string; jarName: string | null; jarSize: number | null; safety: string | null }[];
  files: { path: string; size: number }[];
  remix: RemixDecision;
  addedAt: string;
};

export async function libraryFor(user: { id: string; role?: string | null }, hasCyrus: boolean): Promise<LibraryEntry[]> {
  const items = await db.cyrusLibraryItem.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 60 });
  if (!items.length) return [];
  const pages = (await db.cyrusModPage.findMany({ where: { id: { in: items.map((i) => i.pageId) } } })).filter((p) => pageVisibleTo(p, user));
  const [users, { listings, media }] = await Promise.all([
    db.user.findMany({ where: { id: { in: [...new Set(pages.map((p) => p.userId))] } }, select: { id: true, name: true } }),
    listingsFor(pages.map((p) => p.id)),
  ]);
  return items.flatMap((i) => {
    const p = pages.find((x) => x.id === i.pageId);
    const d = p ? readModDoc(p.doc) : null;
    if (!p || !d) return [];
    const lv = toListingView(listings.get(p.id) ?? null, media.get(p.id) ?? [], false);
    const cur = d.versions.find((v) => v.buildId === d.currentBuildId);
    return [{
      pageId: p.id,
      slug: p.slug,
      title: p.title,
      tagline: lv.tagline ?? d.tagline,
      summary: d.summary,
      creator: displayUser(users.find((u) => u.id === p.userId) ?? null),
      license: p.license,
      iconUrl: lv.icon?.url ?? null,
      category: lv.category,
      currentBuildId: d.currentBuildId,
      versions: d.versions.map((v) => ({ buildId: v.buildId, label: versionLabel(v), mcVersion: v.mcVersion, notes: v.notes, at: v.at, jarName: v.jarName, jarSize: v.jarSize, safety: v.safety })),
      files: d.files,
      remix: remixDecision({ viewer: user, page: p, policy: lv.remixPolicy, hasCyrus, scanVerdict: cur?.safety ?? null }),
      addedAt: i.createdAt.toISOString(),
    }];
  });
}

