"use server";

/**
 * Cyrus v6 community (server actions): NxLabs listing editor, remix ("Remix in my Cyrus"),
 * community versions (endorse), stars, ratings, "Add to my Cyrus", collections, creator profiles,
 * reports, and installing a published community mod on your own server.
 *
 * Gated end to end like every Cyrus-mods surface (lib/cyrus-mods/gate.ts): outside the gate every
 * action answers "Not found." WRITES are refused while an admin views as a customer. The pure rules
 * live in lib/cyrus-mods/{listing,remix,tested,rescan}.ts (unit-tested).
 */
import { revalidatePath } from "next/cache";
import { createHash, randomBytes } from "node:crypto";
import { copyFile, mkdir, readFile } from "node:fs/promises";
import type { CyrusModPage, Prisma, User } from "@prisma/client";
import { db } from "./db";
import { currentUser, realUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { cyrusAccessFor, pageVisibleTo } from "./cyrus-mods/gate";
import { currentVersion, readModDoc, slugifyModName, succeededVersions, uniqueSlug, versionLabel } from "./cyrus-mods/doc";
import { cleanReason, LIMITS, rateLimited } from "./cyrus-mods/community";
import { displayUser, syncCyrusModPage } from "./cyrus-mods/pages";
import { ensureCyrusGameMod, loadChain, serviceBuildId } from "./cyrus-mods/registry";
import { validateListing, type ModListingInput } from "./cyrus-mods/listing";
import { remixDecision, remixNotes, remixTitle } from "./cyrus-mods/remix";
import { rescanPaths, rescanVerdict, scanSourceText } from "./cyrus-mods/rescan";
import { isScore, rateDecision } from "./cyrus-mods/tested";
import { communityFor, ensureCreatorHandle, isHandle, libraryFor, myCollections, type LibraryEntry } from "./cyrus-mods/social";
import { applyProjectPatch, readCyrusMeta } from "./cyrus/meta";
import { CATEGORIES } from "./cyrus/data";
import { modBuilderUser } from "./modbuilder/access";
import { svcSource } from "./modbuilder/client";
import { jarPathFor, MODBUILD_DIR } from "./modbuilder/store";
import { modBuilderServers } from "./modbuilder/install";
import { enqueueModOp } from "./mods/queue";
import { SANDBOX } from "./sandbox";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";

type R<T = object> = Promise<({ ok: true } & T) | { ok?: undefined; error: string }>;
const NF = { error: "Not found." } as const;
const SLUG_RE = /^[a-z0-9-]{3,60}$/;
const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;

/** Same contract as lib/actions-cyrus-mods.ts: `user` is null for writes while impersonating. */
async function requireViewer(mode: "read" | "write" = "write"): Promise<{ user: User | null; allowed: boolean }> {
  let user: User | null = null;
  let real: User | null = null;
  try {
    [user, real] = await Promise.all([currentUser(), realUser()]);
  } catch {
    user = null;
  }
  const a = await cyrusAccessFor(user);
  if (mode === "write" && user && (!real || real.id !== user.id)) return { user: null, allowed: a.allowed };
  return { user, allowed: a.allowed };
}

async function pageBySlug(slug: unknown, user: User | null): Promise<CyrusModPage | null> {
  if (typeof slug !== "string" || !SLUG_RE.test(slug)) return null;
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  return page && pageVisibleTo(page, user) ? page : null;
}

function revalidate(slug: string) {
  revalidatePath(`/dashboard/nxlabs/cyrus/${slug}`);
  revalidatePath(`/mods/cyrus/${slug}`);
  revalidatePath("/dashboard/nxlabs/cyrus");
}

const audit = (userId: string, action: string, detail: string) => db.auditLog.create({ data: { userId, action, detail: detail.slice(0, 900) } }).catch(() => {});

/** Does the viewer pass the Cyrus studio gate themselves (not impersonated)? */
async function hasCyrus(user: User | null): Promise<boolean> {
  if (!user) return false;
  const mb = await modBuilderUser().catch(() => null);
  return !!mb && mb.id === user.id;
}

/** The project (any of its builds) -> its page, created when it doesn't exist yet. Owner only. */
async function ownProjectPage(idOrBuild: unknown, user: User): Promise<CyrusModPage | null> {
  if (typeof idOrBuild !== "string" || !ID_RE.test(idOrBuild)) return null;
  const b = await db.modBuild.findUnique({ where: { id: idOrBuild }, select: { id: true, rootBuildId: true, userId: true } });
  if (!b || b.userId !== user.id) return null;
  const root = b.rootBuildId ?? b.id;
  return (await db.cyrusModPage.findUnique({ where: { rootBuildId: root } })) ?? (await syncCyrusModPage(root));
}

// ── Open in NxLabs ──────────────────────────────────────────────────────────

/** From a Cyrus project: its NxLabs listing (the page is created on the spot if it doesn't exist yet). */
export async function openInNxLabs(projectIdOrBuildId: string): R<{ href: string; editHref: string; slug: string }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return { error: "This mod gets its NxLabs page when its first version finishes building." };
  return { ok: true, href: `/dashboard/nxlabs/cyrus/${page.slug}`, editHref: `/dashboard/nxlabs/cyrus/${page.slug}/edit`, slug: page.slug };
}

// ── the listing editor ──────────────────────────────────────────────────────

/**
 * Save the creator's customisation of a Cyrus mod page. `projectIdOrBuildId` = the project's root
 * build id or any build of it. Only the fields present in `input` change.
 */
export async function saveModListing(projectIdOrBuildId: string, input: ModListingInput): R<{ slug: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return NF;
  const rl = checkRateLimit(`cyrus:listing:${user.id}`, { max: 40, windowMs: 10 * 60_000 });
  if (!rl.ok) return { error: `Saving a lot. Try again in ${rl.retryAfterSec}s.` };
  const doc = readModDoc(page.doc);
  const media = await db.cyrusModMedia.findMany({ where: { pageId: page.id }, select: { id: true, kind: true } });
  const v = validateListing(input, { versionIds: (doc?.versions ?? []).map((x) => x.buildId), categories: CATEGORIES.map((c) => c.key), media });
  if (!v.ok) return { error: v.error };
  const c = v.clean;
  const prev = await db.cyrusModListing.findUnique({ where: { pageId: page.id } });

  const listingData: Prisma.CyrusModListingUncheckedCreateInput = { pageId: page.id, userId: user.id };
  if (c.tagline !== undefined) listingData.tagline = c.tagline;
  if (c.description !== undefined) listingData.description = c.description;
  if (c.category !== undefined) listingData.category = c.category;
  if (c.tags !== undefined) listingData.tags = c.tags;
  if (c.links !== undefined) listingData.links = c.links as unknown as Prisma.InputJsonValue;
  if (c.changelog !== undefined) listingData.changelog = c.changelog as unknown as Prisma.InputJsonValue;
  if (c.remixPolicy !== undefined) listingData.remixPolicy = c.remixPolicy;
  if (c.iconMediaId !== undefined) listingData.iconMediaId = c.iconMediaId;
  if (c.bannerMediaId !== undefined) listingData.bannerMediaId = c.bannerMediaId;
  const { pageId: _p, ...update } = listingData;
  void _p;

  const ops: Prisma.PrismaPromise<unknown>[] = [db.cyrusModListing.upsert({ where: { pageId: page.id }, create: listingData, update })];
  const pageData: Prisma.CyrusModPageUpdateInput = {};
  if (c.title !== undefined) pageData.title = c.title;
  if (c.tagline !== undefined) pageData.tagline = c.tagline || doc?.tagline || null;
  if (c.visibility !== undefined) {
    pageData.visibility = c.visibility;
    if (c.visibility === "PUBLIC" && !page.publishedAt) pageData.publishedAt = new Date();
  }
  if (Object.keys(pageData).length) ops.push(db.cyrusModPage.update({ where: { id: page.id }, data: pageData }));
  if (c.photoOrder) c.photoOrder.forEach((id, i) => ops.push(db.cyrusModMedia.update({ where: { id }, data: { sort: i } })));
  if (c.captions) for (const [id, cap] of Object.entries(c.captions)) ops.push(db.cyrusModMedia.update({ where: { id }, data: { caption: cap || null } }));
  // A replaced icon / banner is removed (the gallery keeps its own photos).
  for (const [field, kind] of [["iconMediaId", "icon"], ["bannerMediaId", "banner"]] as const) {
    if (c[field] !== undefined) ops.push(db.cyrusModMedia.deleteMany({ where: { pageId: page.id, kind, ...(c[field] ? { id: { not: c[field]! } } : {}) } }));
  }
  if (c.title !== undefined) {
    const root = await db.modBuild.findUnique({ where: { id: page.rootBuildId }, select: { cyrus: true } });
    const meta = applyProjectPatch(readCyrusMeta(root?.cyrus), { title: c.title });
    ops.push(db.modBuild.update({ where: { id: page.rootBuildId }, data: { cyrus: meta as unknown as Prisma.InputJsonValue } }));
  }
  await db.$transaction(ops);
  if (c.title !== undefined) await syncCyrusModPage(page.rootBuildId); // regenerates doc.name + the engine's GameMod name
  if (c.visibility === "PUBLIC") await ensureCreatorHandle(user.id).catch(() => null);
  await audit(user.id, "cyrusmods.listing", `${page.slug} ${Object.keys(c).join(",")}${prev ? "" : " (first)"}`);
  revalidate(page.slug);
  return { ok: true, slug: page.slug };
}

