    if (!c?.versions.some((g) => g.versions.some((v) => v.buildId === buildId))) return { error: "That isn't one of this mod's published community versions." };
  }
  await db.cyrusModListing.upsert({ where: { pageId: page.id }, create: { pageId: page.id, userId: user.id, endorsedBuildId: buildId, endorsedAt: buildId ? new Date() : null }, update: { endorsedBuildId: buildId, endorsedAt: buildId ? new Date() : null } });
  await audit(user.id, "cyrusmods.endorse", `${page.slug} ${buildId ?? "none"}`);
  revalidate(page.slug);
  return { ok: true };
}

