}

// ── collections ─────────────────────────────────────────────────────────────

const cleanLine = (s: unknown, max: number) => (typeof s === "string" ? s.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max) : "");

export async function createCyrusCollection(input: { title: string; description?: string; visibility?: "PUBLIC" | "PRIVATE"; addSlug?: string }): R<{ slug: string; id: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const title = cleanLine(input?.title, 60);
  if (title.length < 3) return { error: "Give the collection a name (at least 3 characters)." };
  const n = await db.cyrusCollection.count({ where: { userId: user.id } });
  if (n >= 20) return { error: "You can have up to 20 collections." };
  const base = slugifyModName(title);
  const taken = new Set((await db.cyrusCollection.findMany({ where: { slug: { startsWith: base.slice(0, 40) } }, select: { slug: true } })).map((r) => r.slug));
  const c = await db.cyrusCollection.create({ data: { userId: user.id, slug: uniqueSlug(base, taken), title, description: cleanLine(input?.description, 400) || null, visibility: input?.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE" } });
  if (input?.addSlug) {
    const page = await pageBySlug(input.addSlug, user);
    if (page) await db.cyrusCollectionItem.create({ data: { collectionId: c.id, pageId: page.id } }).catch(() => null);
  }
  await ensureCreatorHandle(user.id).catch(() => null);
  revalidatePath("/dashboard/nxlabs/cyrus");
  return { ok: true, slug: c.slug, id: c.id };
}

async function ownCollection(id: unknown, user: User) {
  if (typeof id !== "string" || !ID_RE.test(id)) return null;
  const c = await db.cyrusCollection.findUnique({ where: { id } });
  return c && c.userId === user.id ? c : null;
}

export async function setCollectionItem(collectionId: string, slug: string, present: boolean, note?: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (present) {
    const n = await db.cyrusCollectionItem.count({ where: { collectionId: c.id } });
    if (n >= 100) return { error: "A collection holds up to 100 mods." };
    await db.cyrusCollectionItem.upsert({ where: { collectionId_pageId: { collectionId: c.id, pageId: page.id } }, create: { collectionId: c.id, pageId: page.id, note: cleanLine(note, 200) || null, sort: n }, update: note !== undefined ? { note: cleanLine(note, 200) || null } : {} });
  } else {
    await db.cyrusCollectionItem.deleteMany({ where: { collectionId: c.id, pageId: page.id } });
  }
  await db.cyrusCollection.update({ where: { id: c.id }, data: { updatedAt: new Date() } });
  revalidatePath(`/dashboard/nxlabs/cyrus/c/${c.slug}`);
  return { ok: true };
}

export async function updateCyrusCollection(collectionId: string, input: { title?: string; description?: string; visibility?: "PUBLIC" | "PRIVATE" }): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  const data: Prisma.CyrusCollectionUpdateInput = {};
  if (input.title !== undefined) {
    const t = cleanLine(input.title, 60);
    if (t.length < 3) return { error: "Give the collection a name (at least 3 characters)." };
    data.title = t;
  }
  if (input.description !== undefined) data.description = cleanLine(input.description, 400) || null;
  if (input.visibility === "PUBLIC" || input.visibility === "PRIVATE") data.visibility = input.visibility;
  await db.cyrusCollection.update({ where: { id: c.id }, data });
  revalidatePath(`/dashboard/nxlabs/cyrus/c/${c.slug}`);
  return { ok: true };
}

export async function deleteCyrusCollection(collectionId: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  await db.$transaction([db.cyrusCollectionItem.deleteMany({ where: { collectionId: c.id } }), db.cyrusCollection.delete({ where: { id: c.id } })]);
  revalidatePath("/dashboard/nxlabs/cyrus");
  return { ok: true };
}

