// ── reports (pages, photos, collections, profiles) ──────────────────────────

const REPORT_KINDS = ["PAGE", "MEDIA", "COLLECTION", "PROFILE"] as const;
type ReportKind = (typeof REPORT_KINDS)[number];

/** Same rules as thread reports (lib/cyrus-mods/community.ts): not your own, a reason, a daily cap. 3 reports hide a photo until review. */
export async function reportCyrusContent(kind: ReportKind, target: string, reason: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  if (!REPORT_KINDS.includes(kind) || typeof target !== "string" || target.length > 64) return NF;
  let targetId: string | null = null;
  let ownerId: string | null = null;
  let slug: string | null = null;
  if (kind === "PAGE") {
    const p = await pageBySlug(target, user);
    if (p) { targetId = p.id; ownerId = p.userId; slug = p.slug; }
  } else if (kind === "MEDIA") {
    const m = ID_RE.test(target) ? await db.cyrusModMedia.findUnique({ where: { id: target } }) : null;
    const p = m ? await db.cyrusModPage.findUnique({ where: { id: m.pageId } }) : null;
    if (m && p && pageVisibleTo(p, user)) { targetId = m.id; ownerId = m.userId; slug = p.slug; }
  } else if (kind === "COLLECTION") {
    const c = SLUG_RE.test(target) ? await db.cyrusCollection.findUnique({ where: { slug: target } }) : null;
    if (c && (c.visibility === "PUBLIC" || c.userId === user.id)) { targetId = c.id; ownerId = c.userId; }
  } else if (isHandle(target)) {
    const c = await db.cyrusCreator.findUnique({ where: { handle: target } });
    if (c) { targetId = c.userId; ownerId = c.userId; }
  }
  if (!targetId) return NF;
  if (ownerId === user.id) return { error: "You can't report your own content." };
  const why = cleanReason(reason);
  if (!why) return { error: "Say briefly what's wrong with it." };
  const since = new Date(Date.now() - 86400_000);
  const today = (await db.cyrusModReport.count({ where: { userId: user.id, createdAt: { gte: since } } })) + (await db.cyrusCommunityReport.count({ where: { userId: user.id, createdAt: { gte: since } } }));
  const limited = rateLimited("report", today);
  if (limited) return { error: limited };
  try {
    await db.cyrusCommunityReport.create({ data: { targetKind: kind, targetId, userId: user.id, reason: why } });
  } catch {
    return { error: "You've already reported this." };
  }
  if (kind === "MEDIA") {
    const n = await db.cyrusCommunityReport.count({ where: { targetKind: "MEDIA", targetId, resolvedAt: null } });
    if (n >= LIMITS.autoHideReports) await db.cyrusModMedia.updateMany({ where: { id: targetId, hiddenAt: null }, data: { hiddenAt: new Date() } });
  }
  await audit(user.id, "cyrusmods.report", `${kind} ${targetId}: ${why}`);
  if (slug) revalidate(slug);
  return { ok: true };
}

