"use server";

/**
 * Cyrus v6 community (server actions): NxLabs listing editor, remix ("Remix in my Cyrus"),
 * community versions (endorse), stars, ratings, "Add to my Cyrus", collections, creator profiles,
 * reports, and installing a published community mod on your own server.
 *
 * Gated end to end like every Cyrus-mods surface (lib/cyrus-mods/gate.ts): outside the gate every
 * action answers "Not found." WRITES are refused while an admin views as a customer. The pure rules
 * live in lib/cyrus-mods/{listing,remix,tested,rescan}.ts (unit-tested).
 */
import { revalidatePath } from "next/cache";
import { createHash, randomBytes } from "node:crypto";
import { copyFile, mkdir, readFile } from "node:fs/promises";
import type { CyrusModPage, Prisma, User } from "@prisma/client";
import { db } from "./db";
import { currentUser, realUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { cyrusAccessFor, pageVisibleTo } from "./cyrus-mods/gate";
import { currentVersion, readModDoc, slugifyModName, succeededVersions, uniqueSlug, versionLabel } from "./cyrus-mods/doc";
import { cleanReason, LIMITS, rateLimited } from "./cyrus-mods/community";
import { displayUser, syncCyrusModPage } from "./cyrus-mods/pages";
import { ensureCyrusGameMod, loadChain, serviceBuildId } from "./cyrus-mods/registry";
import { validateListing, type ModListingInput } from "./cyrus-mods/listing";
import { remixDecision, remixNotes, remixTitle } from "./cyrus-mods/remix";
import { rescanPaths, rescanVerdict, scanSourceText } from "./cyrus-mods/rescan";
import { isScore, rateDecision } from "./cyrus-mods/tested";
import { communityFor, ensureCreatorHandle, isHandle, libraryFor, myCollections, type LibraryEntry } from "./cyrus-mods/social";
import { applyProjectPatch, readCyrusMeta } from "./cyrus/meta";
import { CATEGORIES } from "./cyrus/data";
import { modBuilderUser } from "./modbuilder/access";
import { svcSource } from "./modbuilder/client";
import { jarPathFor, MODBUILD_DIR } from "./modbuilder/store";
import { modBuilderServers } from "./modbuilder/install";
import { enqueueModOp } from "./mods/queue";
import { SANDBOX } from "./sandbox";
import { CYRUS_SOURCE } from "./mods/installers/cyrus";

type R<T = object> = Promise<({ ok: true } & T) | { ok?: undefined; error: string }>;
const NF = { error: "Not found." } as const;
const SLUG_RE = /^[a-z0-9-]{3,60}$/;
const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;

/** Same contract as lib/actions-cyrus-mods.ts: `user` is null for writes while impersonating. */
async function requireViewer(mode: "read" | "write" = "write"): Promise<{ user: User | null; allowed: boolean }> {
  let user: User | null = null;
  let real: User | null = null;
  try {
    [user, real] = await Promise.all([currentUser(), realUser()]);
  } catch {
    user = null;
  }
  const a = await cyrusAccessFor(user);
  if (mode === "write" && user && (!real || real.id !== user.id)) return { user: null, allowed: a.allowed };
  return { user, allowed: a.allowed };
}

async function pageBySlug(slug: unknown, user: User | null): Promise<CyrusModPage | null> {
  if (typeof slug !== "string" || !SLUG_RE.test(slug)) return null;
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  return page && pageVisibleTo(page, user) ? page : null;
}

function revalidate(slug: string) {
  revalidatePath(`/dashboard/nxlabs/cyrus/${slug}`);
  revalidatePath(`/mods/cyrus/${slug}`);
  revalidatePath("/dashboard/nxlabs/cyrus");
}

const audit = (userId: string, action: string, detail: string) => db.auditLog.create({ data: { userId, action, detail: detail.slice(0, 900) } }).catch(() => {});

/** Does the viewer pass the Cyrus studio gate themselves (not impersonated)? */
async function hasCyrus(user: User | null): Promise<boolean> {
  if (!user) return false;
  const mb = await modBuilderUser().catch(() => null);
  return !!mb && mb.id === user.id;
}

/** The project (any of its builds) -> its page, created when it doesn't exist yet. Owner only. */
async function ownProjectPage(idOrBuild: unknown, user: User): Promise<CyrusModPage | null> {
  if (typeof idOrBuild !== "string" || !ID_RE.test(idOrBuild)) return null;
  const b = await db.modBuild.findUnique({ where: { id: idOrBuild }, select: { id: true, rootBuildId: true, userId: true } });
  if (!b || b.userId !== user.id) return null;
  const root = b.rootBuildId ?? b.id;
  return (await db.cyrusModPage.findUnique({ where: { rootBuildId: root } })) ?? (await syncCyrusModPage(root));
}

// ── Open in NxLabs ──────────────────────────────────────────────────────────

/** From a Cyrus project: its NxLabs listing (the page is created on the spot if it doesn't exist yet). */
export async function openInNxLabs(projectIdOrBuildId: string): R<{ href: string; editHref: string; slug: string }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return { error: "This mod gets its NxLabs page when its first version finishes building." };
  return { ok: true, href: `/dashboard/nxlabs/cyrus/${page.slug}`, editHref: `/dashboard/nxlabs/cyrus/${page.slug}/edit`, slug: page.slug };
}

// ── the listing editor ──────────────────────────────────────────────────────

/**
 * Save the creator's customisation of a Cyrus mod page. `projectIdOrBuildId` = the project's root
 * build id or any build of it. Only the fields present in `input` change.
 */
export async function saveModListing(projectIdOrBuildId: string, input: ModListingInput): R<{ slug: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return NF;
  const rl = checkRateLimit(`cyrus:listing:${user.id}`, { max: 40, windowMs: 10 * 60_000 });
  if (!rl.ok) return { error: `Saving a lot. Try again in ${rl.retryAfterSec}s.` };
  const doc = readModDoc(page.doc);
  const media = await db.cyrusModMedia.findMany({ where: { pageId: page.id }, select: { id: true, kind: true } });
  const v = validateListing(input, { versionIds: (doc?.versions ?? []).map((x) => x.buildId), categories: CATEGORIES.map((c) => c.key), media });
  if (!v.ok) return { error: v.error };
  const c = v.clean;
  const prev = await db.cyrusModListing.findUnique({ where: { pageId: page.id } });

  const listingData: Prisma.CyrusModListingUncheckedCreateInput = { pageId: page.id, userId: user.id };
  if (c.tagline !== undefined) listingData.tagline = c.tagline;
  if (c.description !== undefined) listingData.description = c.description;
  if (c.category !== undefined) listingData.category = c.category;
  if (c.tags !== undefined) listingData.tags = c.tags;
  if (c.links !== undefined) listingData.links = c.links as unknown as Prisma.InputJsonValue;
  if (c.changelog !== undefined) listingData.changelog = c.changelog as unknown as Prisma.InputJsonValue;
  if (c.remixPolicy !== undefined) listingData.remixPolicy = c.remixPolicy;
  if (c.iconMediaId !== undefined) listingData.iconMediaId = c.iconMediaId;
  if (c.bannerMediaId !== undefined) listingData.bannerMediaId = c.bannerMediaId;
  const { pageId: _p, ...update } = listingData;
  void _p;

  const ops: Prisma.PrismaPromise<unknown>[] = [db.cyrusModListing.upsert({ where: { pageId: page.id }, create: listingData, update })];
  const pageData: Prisma.CyrusModPageUpdateInput = {};
  if (c.title !== undefined) pageData.title = c.title;
  if (c.tagline !== undefined) pageData.tagline = c.tagline || doc?.tagline || null;
  if (c.visibility !== undefined) {
    pageData.visibility = c.visibility;
    if (c.visibility === "PUBLIC" && !page.publishedAt) pageData.publishedAt = new Date();
  }
  if (Object.keys(pageData).length) ops.push(db.cyrusModPage.update({ where: { id: page.id }, data: pageData }));
  if (c.photoOrder) c.photoOrder.forEach((id, i) => ops.push(db.cyrusModMedia.update({ where: { id }, data: { sort: i } })));
  if (c.captions) for (const [id, cap] of Object.entries(c.captions)) ops.push(db.cyrusModMedia.update({ where: { id }, data: { caption: cap || null } }));
  // A replaced icon / banner is removed (the gallery keeps its own photos).
  for (const [field, kind] of [["iconMediaId", "icon"], ["bannerMediaId", "banner"]] as const) {
    if (c[field] !== undefined) ops.push(db.cyrusModMedia.deleteMany({ where: { pageId: page.id, kind, ...(c[field] ? { id: { not: c[field]! } } : {}) } }));
  }
  if (c.title !== undefined) {
    const root = await db.modBuild.findUnique({ where: { id: page.rootBuildId }, select: { cyrus: true } });
    const meta = applyProjectPatch(readCyrusMeta(root?.cyrus), { title: c.title });
    ops.push(db.modBuild.update({ where: { id: page.rootBuildId }, data: { cyrus: meta as unknown as Prisma.InputJsonValue } }));
  }
  await db.$transaction(ops);
  if (c.title !== undefined) await syncCyrusModPage(page.rootBuildId); // regenerates doc.name + the engine's GameMod name
  if (c.visibility === "PUBLIC") await ensureCreatorHandle(user.id).catch(() => null);
  await audit(user.id, "cyrusmods.listing", `${page.slug} ${Object.keys(c).join(",")}${prev ? "" : " (first)"}`);
  revalidate(page.slug);
  return { ok: true, slug: page.slug };
}

/** Remove one of the page's images (creator). */
export async function deleteListingMedia(mediaId: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user || typeof mediaId !== "string" || !ID_RE.test(mediaId)) return NF;
  const m = await db.cyrusModMedia.findUnique({ where: { id: mediaId } });
  if (!m) return NF;
  const page = await db.cyrusModPage.findUnique({ where: { id: m.pageId } });
  if (!page || page.userId !== user.id) return NF;
  await db.$transaction([
    db.cyrusModMedia.delete({ where: { id: m.id } }),
    db.cyrusModListing.updateMany({ where: { pageId: page.id, iconMediaId: m.id }, data: { iconMediaId: null } }),
    db.cyrusModListing.updateMany({ where: { pageId: page.id, bannerMediaId: m.id }, data: { bannerMediaId: null } }),
  ]);
  revalidate(page.slug);
  return { ok: true };
}

// ── stars + ratings ─────────────────────────────────────────────────────────

export async function toggleCyrusStar(slug: string): R<{ starred: boolean; count: number }> {
  const { user, allowed } = await requireViewer();
  if (!allowed) return NF;
  if (!user) return { error: "Sign in to star mods." };
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (page.userId === user.id) return { error: "You can't star your own mod." };
  if (page.visibility !== "PUBLIC" || page.hiddenAt) return NF;
  const rl = checkRateLimit(`cyrus:star:${user.id}`, { max: 120, windowMs: 3600_000 });
  if (!rl.ok) return { error: "Slow down a little." };
  const key = { userId_pageId: { userId: user.id, pageId: page.id } };
  const had = await db.cyrusModStar.findUnique({ where: key });
  if (had) await db.cyrusModStar.delete({ where: key });
  else await db.cyrusModStar.create({ data: { userId: user.id, pageId: page.id } }).catch(() => null);
  const count = await db.cyrusModStar.count({ where: { pageId: page.id } });
  revalidate(page.slug);
  return { ok: true, starred: !had, count };
}

export async function rateCyrusMod(slug: string, score: number): R<{ count: number; average: number | null }> {
  const { user, allowed } = await requireViewer();
  if (!allowed) return NF;
  const page = await pageBySlug(slug, user);
  if (!page || page.visibility !== "PUBLIC" || page.hiddenAt) return NF;
  if (!isScore(score)) return { error: "Pick 1 to 5 stars." };
  const installed = user ? await db.serverMod.findFirst({ where: { mod: { source: CYRUS_SOURCE, sourceId: page.rootBuildId }, server: { userId: user.id } }, select: { versionId: true } }) : null;
  const d = rateDecision({ viewerId: user?.id ?? null, creatorId: page.userId, installedByViewer: !!installed });
  if (!d.ok) return { error: d.message };
  await db.cyrusModRating.upsert({ where: { userId_pageId: { userId: user!.id, pageId: page.id } }, create: { userId: user!.id, pageId: page.id, score, buildId: installed?.versionId ?? null }, update: { score, buildId: installed?.versionId ?? null } });
  const agg = await db.cyrusModRating.aggregate({ where: { pageId: page.id, userId: { not: page.userId } }, _avg: { score: true }, _count: { _all: true } });
  await audit(user!.id, "cyrusmods.rate", `${page.slug} ${score}`);
  revalidate(page.slug);
  return { ok: true, count: agg._count._all, average: agg._avg.score === null ? null : Math.round(agg._avg.score * 10) / 10 };
}

// ── remix ───────────────────────────────────────────────────────────────────

/**
 * "Remix in my Cyrus". The creator just opens their own version. Anyone else (when the creator
 * allows remixes) gets their OWN private copy of the chosen version, but only after the copy's code
 * is re-scanned (lib/cyrus-mods/rescan.ts: jar checksum + the service's source rules). The copy is
 * seeded with the original's prompt history (its Notes in Cyrus) and recorded in CyrusFork (so
 * change requests build from the original's source on the service) and CyrusRemix (lineage).
 */
export async function remixCyrusMod(slug: string, buildId?: string | null): R<{ href: string; own: boolean }> {
  const { user, allowed } = await requireViewer();
  if (!allowed) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  const chain = await loadChain(page.rootBuildId);
  const ok = succeededVersions(chain);
  const src = buildId ? ok.find((b) => b.id === buildId) : currentVersion(chain);
  if (!src || !src.jarPath) return { error: "That version can't be remixed." };
  const listing = await db.cyrusModListing.findUnique({ where: { pageId: page.id }, select: { remixPolicy: true } });
  const srcSafety = (src.result as { safety?: { verdict?: "pass" | "warn" | "block" } } | null)?.safety?.verdict ?? null;
  const d = remixDecision({ viewer: user, page, policy: (listing?.remixPolicy as "OPEN" | "CLOSED" | undefined) ?? null, hasCyrus: await hasCyrus(user), scanVerdict: srcSafety });
  if (!d.ok) return { error: d.message };
  if (d.mode === "own") return { ok: true, href: `/dashboard/cyrus/${src.id}`, own: true };
  const me = user!;
  const recent = await db.cyrusFork.count({ where: { userId: me.id, createdAt: { gte: new Date(Date.now() - 3600_000) } } });
  if (recent >= 10) return { error: "You've started a lot of remixes this hour. Try again later." };

  // 1. Re-scan BEFORE anything is copied.
  let bytes: Buffer;
  try {
    bytes = await readFile(src.jarPath);
  } catch {
    return { error: "That version's plugin file is missing from storage." };
  }
  const checksumOk = src.jarSha256 ? createHash("sha256").update(bytes).digest("hex") === src.jarSha256 : null;
  const paths = rescanPaths(((src.result as { files?: { path: string; size: number }[] } | null)?.files) ?? []);
  const svcId = await serviceBuildId(src.id);
  const files: { path: string; text: string }[] = [];
  try {
    for (const p of paths) {
      const r = await svcSource(svcId, p);
      if (!r.ok) throw new Error(`source ${r.status}`);
      files.push({ path: p, text: await r.text() });
    }
  } catch {
    return { error: "Cyrus couldn't fetch this mod's code to safety-check it (the builder is busy or offline). Nothing was copied. Try again in a moment." };
  }
  const scan = rescanVerdict({ stored: srcSafety, findings: scanSourceText(files), checksumOk, files: files.length });
  if (scan.verdict === "block") {
    await audit(me.id, "cyrusmods.remix.blocked", `${page.slug} ${src.id} ${scan.findings.map((f) => f.rule).join(",")}`);
    return { error: `This version didn't pass the re-scan (${scan.findings[0]?.message ?? "safety check"}), so it can't be remixed. Nxeon has been told.` };
  }

  // 2. Lineage: who this page itself came from.
  const parentRemix = await db.cyrusRemix.findUnique({ where: { buildId: page.rootBuildId } });
  const originPageId = parentRemix?.originPageId ?? (page.forkOfPageId ? await legacyOrigin(page) : page.id);
  const depth = (parentRemix?.depth ?? (page.forkOfPageId ? 1 : 0)) + 1;

  // 3. The copy, seeded with the prompt history.
  const doc = readModDoc(page.doc);
  const v = doc?.versions.find((x) => x.buildId === src.id);
  const creator = displayUser(await db.user.findUnique({ where: { id: page.userId }, select: { name: true } }));
  const upTo = chain.filter((b) => b.createdAt.getTime() <= src.createdAt.getTime());
  const notes = remixNotes({ title: page.title, creator, baseLabel: v ? versionLabel(v) : "the current version", license: page.license, slug: page.slug, steps: upTo });
  const id = "mb" + randomBytes(10).toString("hex");
  await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
  await copyFile(src.jarPath, jarPathFor(id));
  await db.modBuild.create({
    data: {
      id,
      userId: me.id,
      status: "succeeded",
      prompt: src.prompt,
      changeRequest: null,
      baseBuildId: null,
      rootBuildId: id,
      mcVersion: src.mcVersion,
      pluginName: src.pluginName,
      version: src.version,
      result: (src.result ?? undefined) as Prisma.InputJsonValue | undefined,
      attempts: 0,
      costUsd: 0,
      durationMs: 0,
      jarName: src.jarName,
      jarSize: src.jarSize,
      jarSha256: src.jarSha256,
      jarPath: jarPathFor(id),
      cyrus: { title: remixTitle(page.title), notes } as Prisma.InputJsonValue,
      finishedAt: new Date(),
    },
  });
  await db.cyrusFork.create({ data: { buildId: id, sourceBuildId: svcId, sourcePageId: page.id, userId: me.id } });
  await db.cyrusRemix.create({ data: { buildId: id, userId: me.id, parentPageId: page.id, parentBuildId: src.id, parentRootBuildId: page.rootBuildId, originPageId, depth, scan: scan as unknown as Prisma.InputJsonValue } });
  await syncCyrusModPage(id);
  await audit(me.id, "cyrusmods.remix", `${page.slug} ${src.id} -> ${id} scan=${scan.verdict}`);
  revalidate(page.slug);
  return { ok: true, href: `/dashboard/cyrus/${id}`, own: false };
}

/** Top of a legacy fork chain (forks made before CyrusRemix existed). */
async function legacyOrigin(page: CyrusModPage): Promise<string> {
  let cur: Pick<CyrusModPage, "id" | "forkOfPageId" | "rootBuildId"> = page;
  for (let i = 0; i < 25 && cur.forkOfPageId; i++) {
    const r = await db.cyrusRemix.findUnique({ where: { buildId: cur.rootBuildId } });
    if (r) return r.originPageId;
    const next = await db.cyrusModPage.findUnique({ where: { id: cur.forkOfPageId }, select: { id: true, forkOfPageId: true, rootBuildId: true } });
    if (!next) break;
    cur = next;
  }
  return cur.id;
}

/** The original's creator pins (or unpins with null) one community version on their page. */
export async function endorseCommunityVersion(slug: string, buildId: string | null): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await pageBySlug(slug, user);
  if (!page || page.userId !== user.id) return NF;
  if (buildId !== null) {
    if (typeof buildId !== "string" || !ID_RE.test(buildId)) return { error: "Pick a version." };
    const c = await communityFor(page, user, { hasCyrus: false });
    if (!c?.versions.some((g) => g.versions.some((v) => v.buildId === buildId))) return { error: "That isn't one of this mod's published community versions." };
  }
  await db.cyrusModListing.upsert({ where: { pageId: page.id }, create: { pageId: page.id, userId: user.id, endorsedBuildId: buildId, endorsedAt: buildId ? new Date() : null }, update: { endorsedBuildId: buildId, endorsedAt: buildId ? new Date() : null } });
  await audit(user.id, "cyrusmods.endorse", `${page.slug} ${buildId ?? "none"}`);
  revalidate(page.slug);
  return { ok: true };
}

// ── "Add to my Cyrus" ───────────────────────────────────────────────────────

export async function addToMyCyrus(slug: string): R<{ href: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed) return NF;
  if (!user) return { error: "Sign in to add mods to your Cyrus." };
  if (!(await hasCyrus(user))) return { error: "Cyrus is in private preview. Adding community mods opens up when it launches." };
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (page.userId === user.id) return { error: "It's yours: it's already on your Cyrus map." };
  if (page.visibility !== "PUBLIC" || page.hiddenAt) return NF;
  const n = await db.cyrusLibraryItem.count({ where: { userId: user.id } });
  if (n >= 60) return { error: "Your Cyrus holds up to 60 community mods. Remove one first." };
  await db.cyrusLibraryItem.upsert({ where: { userId_pageId: { userId: user.id, pageId: page.id } }, create: { userId: user.id, pageId: page.id }, update: {} });
  revalidate(page.slug);
  return { ok: true, href: "/dashboard/cyrus" };
}

export async function removeFromMyCyrus(slug: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user || typeof slug !== "string" || !SLUG_RE.test(slug)) return NF;
  const page = await db.cyrusModPage.findUnique({ where: { slug }, select: { id: true, slug: true } });
  if (!page) return NF;
  await db.cyrusLibraryItem.deleteMany({ where: { userId: user.id, pageId: page.id } });
  revalidate(page.slug);
  return { ok: true };
}

/** The community mods on the viewer's Cyrus map (read-only branch nodes). */
export async function getCyrusLibrary(): R<{ entries: LibraryEntry[] }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  return { ok: true, entries: await libraryFor(user, await hasCyrus(user)) };
}

/** Put a published community mod (or one of its versions) on one of YOUR servers, through the mods engine. */
export async function installCommunityMod(slug: string, buildId: string | null, serverId: string): R<{ serverName: string; jobId: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (page.userId !== user.id && (page.visibility !== "PUBLIC" || page.hiddenAt)) return NF;
  if (typeof serverId !== "string" || !ID_RE.test(serverId)) return { error: "Pick a server." };
  const chain = await loadChain(page.rootBuildId);
  const ok = succeededVersions(chain);
  const b = buildId ? ok.find((x) => x.id === buildId) : currentVersion(chain);
  if (!b || !b.jarPath) return { error: "That version has no plugin file." };
  const servers = await modBuilderServers(user.id);
  const facts = servers.find((s) => s.id === serverId);
  if (!facts) return { error: "That server isn't one of your Minecraft servers." };
  if (!facts.compatible) return { error: facts.reason || "That server can't take this plugin." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { error: "One-click mod changes are paused right now, so nothing was installed." };
  const gm = await ensureCyrusGameMod(page.rootBuildId, chain);
  if (!gm) return { error: "This mod has no finished version yet." };
  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
  if (existing?.status === "DISABLED") return { error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first.` };
  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { error: `${gm.name} is busy on that server. Try again in a moment.` };
  if (existing?.status === "INSTALLED" && existing.versionId === b.id) return { error: `That version is already on ${facts.name}.` };
  const q = await enqueueModOp(serverId, gm.id, existing?.status === "INSTALLED" ? "update" : "install", { userId: user.id, slug: gm.slug }, { targetVersionId: b.id });
  if (!q.ok) return { error: q.error };
  await audit(user.id, "cyrusmods.install", `${page.slug} ${b.id} -> ${serverId}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, serverName: facts.name, jobId: q.jobId };
}

/** Servers the viewer can put a Cyrus plugin on (for the library's install dialog). */
export async function myCyrusServers(): R<{ servers: Awaited<ReturnType<typeof modBuilderServers>> }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  return { ok: true, servers: await modBuilderServers(user.id) };
}

// ── collections ─────────────────────────────────────────────────────────────

const cleanLine = (s: unknown, max: number) => (typeof s === "string" ? s.replace(/[\u0000-\u001f\u007f]/g, " ").replace(/\s+/g, " ").trim().slice(0, max) : "");

export async function createCyrusCollection(input: { title: string; description?: string; visibility?: "PUBLIC" | "PRIVATE"; addSlug?: string }): R<{ slug: string; id: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const title = cleanLine(input?.title, 60);
  if (title.length < 3) return { error: "Give the collection a name (at least 3 characters)." };
  const n = await db.cyrusCollection.count({ where: { userId: user.id } });
  if (n >= 20) return { error: "You can have up to 20 collections." };
  const base = slugifyModName(title);
  const taken = new Set((await db.cyrusCollection.findMany({ where: { slug: { startsWith: base.slice(0, 40) } }, select: { slug: true } })).map((r) => r.slug));
  const c = await db.cyrusCollection.create({ data: { userId: user.id, slug: uniqueSlug(base, taken), title, description: cleanLine(input?.description, 400) || null, visibility: input?.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE" } });
  if (input?.addSlug) {
    const page = await pageBySlug(input.addSlug, user);
    if (page) await db.cyrusCollectionItem.create({ data: { collectionId: c.id, pageId: page.id } }).catch(() => null);
  }
  await ensureCreatorHandle(user.id).catch(() => null);
  revalidatePath("/dashboard/nxlabs/cyrus");
  return { ok: true, slug: c.slug, id: c.id };
}

async function ownCollection(id: unknown, user: User) {
  if (typeof id !== "string" || !ID_RE.test(id)) return null;
  const c = await db.cyrusCollection.findUnique({ where: { id } });
  return c && c.userId === user.id ? c : null;
}

export async function setCollectionItem(collectionId: string, slug: string, present: boolean, note?: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  if (present) {
    const n = await db.cyrusCollectionItem.count({ where: { collectionId: c.id } });
    if (n >= 100) return { error: "A collection holds up to 100 mods." };
    await db.cyrusCollectionItem.upsert({ where: { collectionId_pageId: { collectionId: c.id, pageId: page.id } }, create: { collectionId: c.id, pageId: page.id, note: cleanLine(note, 200) || null, sort: n }, update: note !== undefined ? { note: cleanLine(note, 200) || null } : {} });
  } else {
    await db.cyrusCollectionItem.deleteMany({ where: { collectionId: c.id, pageId: page.id } });
  }
  await db.cyrusCollection.update({ where: { id: c.id }, data: { updatedAt: new Date() } });
  revalidatePath(`/dashboard/nxlabs/cyrus/c/${c.slug}`);
  return { ok: true };
}

export async function updateCyrusCollection(collectionId: string, input: { title?: string; description?: string; visibility?: "PUBLIC" | "PRIVATE" }): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  const data: Prisma.CyrusCollectionUpdateInput = {};
  if (input.title !== undefined) {
    const t = cleanLine(input.title, 60);
    if (t.length < 3) return { error: "Give the collection a name (at least 3 characters)." };
    data.title = t;
  }
  if (input.description !== undefined) data.description = cleanLine(input.description, 400) || null;
  if (input.visibility === "PUBLIC" || input.visibility === "PRIVATE") data.visibility = input.visibility;
  await db.cyrusCollection.update({ where: { id: c.id }, data });
  revalidatePath(`/dashboard/nxlabs/cyrus/c/${c.slug}`);
  return { ok: true };
}

export async function deleteCyrusCollection(collectionId: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const c = await ownCollection(collectionId, user);
  if (!c) return NF;
  await db.$transaction([db.cyrusCollectionItem.deleteMany({ where: { collectionId: c.id } }), db.cyrusCollection.delete({ where: { id: c.id } })]);
  revalidatePath("/dashboard/nxlabs/cyrus");
  return { ok: true };
}

/** The viewer's collections, marked with whether `slug` is in each (the "Add to collection" menu). */
export async function collectionsForMenu(slug: string): R<{ collections: Awaited<ReturnType<typeof myCollections>> }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  const page = await pageBySlug(slug, user);
  if (!page) return NF;
  return { ok: true, collections: await myCollections(user.id, page.id) };
}

// ── creator profile ─────────────────────────────────────────────────────────

export async function myCreatorHandle(): R<{ handle: string }> {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  return { ok: true, handle: await ensureCreatorHandle(user.id) };
}

export async function saveCreatorBio(bio: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const text = typeof bio === "string" ? bio.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "").trim().slice(0, 400) : "";
  const handle = await ensureCreatorHandle(user.id);
  await db.cyrusCreator.update({ where: { userId: user.id }, data: { bio: text || null } });
  revalidatePath(`/dashboard/nxlabs/cyrus/u/${handle}`);
  return { ok: true };
}

// ── reports (pages, photos, collections, profiles) ──────────────────────────

const REPORT_KINDS = ["PAGE", "MEDIA", "COLLECTION", "PROFILE"] as const;
type ReportKind = (typeof REPORT_KINDS)[number];

/** Same rules as thread reports (lib/cyrus-mods/community.ts): not your own, a reason, a daily cap. 3 reports hide a photo until review. */
export async function reportCyrusContent(kind: ReportKind, target: string, reason: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  if (!REPORT_KINDS.includes(kind) || typeof target !== "string" || target.length > 64) return NF;
  let targetId: string | null = null;
  let ownerId: string | null = null;
  let slug: string | null = null;
  if (kind === "PAGE") {
    const p = await pageBySlug(target, user);
    if (p) { targetId = p.id; ownerId = p.userId; slug = p.slug; }
  } else if (kind === "MEDIA") {
    const m = ID_RE.test(target) ? await db.cyrusModMedia.findUnique({ where: { id: target } }) : null;
    const p = m ? await db.cyrusModPage.findUnique({ where: { id: m.pageId } }) : null;
    if (m && p && pageVisibleTo(p, user)) { targetId = m.id; ownerId = m.userId; slug = p.slug; }
  } else if (kind === "COLLECTION") {
    const c = SLUG_RE.test(target) ? await db.cyrusCollection.findUnique({ where: { slug: target } }) : null;
    if (c && (c.visibility === "PUBLIC" || c.userId === user.id)) { targetId = c.id; ownerId = c.userId; }
  } else if (isHandle(target)) {
    const c = await db.cyrusCreator.findUnique({ where: { handle: target } });
    if (c) { targetId = c.userId; ownerId = c.userId; }
  }
  if (!targetId) return NF;
  if (ownerId === user.id) return { error: "You can't report your own content." };
  const why = cleanReason(reason);
  if (!why) return { error: "Say briefly what's wrong with it." };
  const since = new Date(Date.now() - 86400_000);
  const today = (await db.cyrusModReport.count({ where: { userId: user.id, createdAt: { gte: since } } })) + (await db.cyrusCommunityReport.count({ where: { userId: user.id, createdAt: { gte: since } } }));
  const limited = rateLimited("report", today);
  if (limited) return { error: limited };
  try {
    await db.cyrusCommunityReport.create({ data: { targetKind: kind, targetId, userId: user.id, reason: why } });
  } catch {
    return { error: "You've already reported this." };
  }
  if (kind === "MEDIA") {
    const n = await db.cyrusCommunityReport.count({ where: { targetKind: "MEDIA", targetId, resolvedAt: null } });
    if (n >= LIMITS.autoHideReports) await db.cyrusModMedia.updateMany({ where: { id: targetId, hiddenAt: null }, data: { hiddenAt: new Date() } });
  }
  await audit(user.id, "cyrusmods.report", `${kind} ${targetId}: ${why}`);
  if (slug) revalidate(slug);
  return { ok: true };
}

