import fs from "node:fs/promises";
import { KEY_RE, imagePath } from "@/lib/modsync/images";

export const dynamic = "force-dynamic";

/**
 * Serves NX Labs' locally cached mod icons/screenshots (WebP, content-addressed
 * by sha256 so the URL is immutable => cache for a year). No auth: these are
 * public catalog images; the key is validated as 64 hex chars so it can never
 * traverse the filesystem.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ key: string }> }) {
  const { key } = await params;
  if (!KEY_RE.test(key)) return new Response("Not found", { status: 404 });
  try {
    const buf = await fs.readFile(imagePath(key));
    return new Response(new Uint8Array(buf), {
      headers: { "Content-Type": "image/webp", "Cache-Control": "public, max-age=31536000, immutable", "X-Content-Type-Options": "nosniff" },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { checkRateLimit } from "@/lib/rate-limit";
import { CYRUS_MAX_IMAGE_BYTES, saveUpload } from "@/lib/cyrus/uploads";
import { NOT_FOUND } from "../_lib";

export const dynamic = "force-dynamic";

// Cyrus: one reference image pasted / dropped into the prompt (multipart field "file").
// Returns an upload id the create call can attach. The create route forwards the bytes to
// the build service (0.4+), which puts them in front of the AI (lib/cyrus/uploads.ts).
export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rl = checkRateLimit(`mb:upload:${user.id}`, { max: 30, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many images. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const len = Number(req.headers.get("content-length") || 0);
  if (len > CYRUS_MAX_IMAGE_BYTES + 64 * 1024) return NextResponse.json({ error: "Images can be up to 5 MB." }, { status: 413 });
  const form = await req.formData().catch(() => null);
  const file = form?.get("file");
  if (!file || typeof file === "string") return NextResponse.json({ error: "No image." }, { status: 400 });
  const bytes = new Uint8Array(await file.arrayBuffer());
  const r = await saveUpload(user.id, file.name, bytes);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });
  return NextResponse.json({ upload: { id: r.id, name: r.name, type: r.type, size: r.size } }, { status: 201 });
}
import { NextResponse } from "next/server";
import { svcSource } from "@/lib/modbuilder/client";
import { isTerminal } from "@/lib/modbuilder/types";
import { NOT_FOUND, ownedBuild } from "../../../_lib";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";

export const dynamic = "force-dynamic";

// One source file as text, proxied from the build service (the source lives there).
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const path = new URL(req.url).searchParams.get("path") || "";
  if (!/^[A-Za-z0-9_./-]{1,300}$/.test(path) || path.includes("..")) return NextResponse.json({ error: "Bad path" }, { status: 400 });
  try {
    const r = await svcSource(await serviceBuildId(o.build.id), path); // fork copies read the original's source
    if (!r.ok) return NextResponse.json({ error: "File not found" }, { status: 404 });
    // Finished builds never change; an in-flight one may (Cyrus polls it while building).
    const cache = isTerminal(o.build.status) ? "private, max-age=300" : "no-store";
    return new Response(await r.text(), { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": cache, "X-Content-Type-Options": "nosniff" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now." }, { status: 503 });
  }
}

