// Shared guards for the Cyrus community API routes (gate + page visibility + version membership).
import { NextResponse } from "next/server";
import type { CyrusModPage, ModBuild, User } from "@prisma/client";
import { db } from "@/lib/db";
import { currentUser, realUser } from "@/lib/auth";
import { cyrusAccessFor, pageVisibleTo } from "@/lib/cyrus-mods/gate";

export const NF = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });

/** The viewer (null when signed out) if they pass the Cyrus gate, else undefined. `write` also refuses impersonation. */
export async function gatedViewer(mode: "read" | "write" = "read"): Promise<{ user: User | null } | undefined> {
  let user: User | null = null;
  let real: User | null = null;
  try {
    [user, real] = await Promise.all([currentUser(), realUser()]);
  } catch {
    user = null;
  }
  if (!(await cyrusAccessFor(user)).allowed) return undefined;
  if (mode === "write" && user && (!real || real.id !== user.id)) return { user: null };
  return { user };
}

export async function visiblePage(slug: string, user: User | null): Promise<CyrusModPage | null> {
  if (!/^[a-z0-9-]{3,60}$/.test(slug)) return null;
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  return page && pageVisibleTo(page, user) ? page : null;
}

/** A succeeded build of a visible page's chain. */
export async function versionOf(page: CyrusModPage, buildId: string | null): Promise<ModBuild | null> {
  if (!buildId || !/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) return null;
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  return b && (b.rootBuildId ?? b.id) === page.rootBuildId && b.status === "succeeded" ? b : null;
}

/** A succeeded build anywhere, when the viewer may see its mod's page. */
export async function visibleVersion(buildId: string | null, user: User | null): Promise<{ build: ModBuild; page: CyrusModPage } | null> {
  if (!buildId || !/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) return null;
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || b.status !== "succeeded") return null;
  const page = await db.cyrusModPage.findUnique({ where: { rootBuildId: b.rootBuildId ?? b.id } });
  return page && pageVisibleTo(page, user) ? { build: b, page } : null;
}

export const SAFE_PATH = (p: string) => /^[A-Za-z0-9_./-]{1,300}$/.test(p) && !p.includes("..") && p.startsWith("src/");
EOF
