import { db } from "@/lib/db";
import { pageVisibleTo } from "@/lib/cyrus-mods/gate";
import { readListingImage } from "@/lib/cyrus-mods/media";
import { gatedViewer } from "../../_lib";

export const dynamic = "force-dynamic";

const NF = () => new Response("Not found", { status: 404, headers: { "X-Robots-Tag": "noindex" } });

/** One Cyrus mod page image. Same rule as the page: the gate, then PUBLIC + not hidden (creator and admins always). */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  if (!/^[a-z0-9]{20,40}$/i.test(id)) return NF();
  const g = await gatedViewer("read");
  if (!g) return NF();
  const m = await db.cyrusModMedia.findUnique({ where: { id } });
  if (!m) return NF();
  const page = await db.cyrusModPage.findUnique({ where: { id: m.pageId }, select: { userId: true, visibility: true, hiddenAt: true } });
  if (!page || !pageVisibleTo(page, g.user)) return NF();
  const privileged = !!g.user && (g.user.id === page.userId || g.user.role === "ADMIN");
  if (m.hiddenAt && !privileged) return NF();
  const buf = await readListingImage(m.key);
  if (!buf) return NF();
  const isPublic = page.visibility === "PUBLIC" && !page.hiddenAt && !m.hiddenAt;
  return new Response(new Uint8Array(buf), {
    headers: { "Content-Type": "image/webp", "Cache-Control": isPublic ? "public, max-age=3600" : "private, no-store", "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "default-src 'none'" },
  });
}
