import { NextResponse } from "next/server";
import { svcSource } from "@/lib/modbuilder/client";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";
import { checkRateLimit } from "@/lib/rate-limit";
import { gatedViewer, NF, SAFE_PATH, versionOf, visiblePage } from "../../_lib";

export const dynamic = "force-dynamic";

/**
 * One source file of a version of a VISIBLE Cyrus mod (?build=<id>&path=src/...). Used by the
 * read-only library node in Cyrus ("Add to my Cyrus") and the community-version diff. The same code
 * the page already offers as a source download, file by file.
 */
export async function GET(req: Request, { params }: { params: Promise<{ slug: string }> }) {
  const g = await gatedViewer("read");
  if (!g) return NF();
  const page = await visiblePage((await params).slug, g.user);
  if (!page) return NF();
  const url = new URL(req.url);
  const build = await versionOf(page, url.searchParams.get("build"));
