import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { storeListingImage } from "@/lib/cyrus-mods/media";
import { isMediaKind, LISTING_LIMITS, listingMediaUrl } from "@/lib/cyrus-mods/listing";
import { gatedViewer, NF, visiblePage } from "../../_lib";

export const dynamic = "force-dynamic";

/**
 * Upload one image to a Cyrus mod page (creator only): multipart "file" + "kind" (photo | icon |
 * banner) + optional "caption". Re-encoded to WebP (lib/cyrus-mods/media.ts). Photos join the
 * gallery immediately; an icon / banner becomes the page's on the editor's next save.
 */
export async function POST(req: Request, { params }: { params: Promise<{ slug: string }> }) {
  const g = await gatedViewer("write");
  if (!g?.user) return NF();
  const page = await visiblePage((await params).slug, g.user);
  if (!page || page.userId !== g.user.id) return NF();
  const rl = checkRateLimit(`cyrus:media:${g.user.id}`, { max: 40, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many uploads. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const len = Number(req.headers.get("content-length") || 0);
  if (len > LISTING_LIMITS.imageBytes + 64 * 1024) return NextResponse.json({ error: "Images can be up to 8 MB." }, { status: 413 });
  const form = await req.formData().catch(() => null);
  const file = form?.get("file");
  const kind = String(form?.get("kind") ?? "photo");
  if (!file || typeof file === "string") return NextResponse.json({ error: "No image." }, { status: 400 });
  if (!isMediaKind(kind)) return NextResponse.json({ error: "Bad image kind." }, { status: 400 });
  if (kind === "photo" && (await db.cyrusModMedia.count({ where: { pageId: page.id, kind: "photo" } })) >= LISTING_LIMITS.photos) {
    return NextResponse.json({ error: `A page holds up to ${LISTING_LIMITS.photos} photos. Remove one first.` }, { status: 400 });
  }
  const r = await storeListingImage(new Uint8Array(await file.arrayBuffer()), kind);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });
  const caption = String(form?.get("caption") ?? "").replace(/[\u0000-\u001f]/g, " ").trim().slice(0, LISTING_LIMITS.captionMax) || null;
  const sort = kind === "photo" ? await db.cyrusModMedia.count({ where: { pageId: page.id, kind: "photo" } }) : 0;
  const m = await db.cyrusModMedia.create({ data: { pageId: page.id, userId: g.user.id, kind, key: r.image.key, width: r.image.width, height: r.image.height, bytes: r.image.bytes, caption, sort } });
  return NextResponse.json({ media: { id: m.id, url: listingMediaUrl(m.id), kind: m.kind, caption: m.caption, width: m.width, height: m.height, hidden: false } }, { status: 201 });
}
