import "./community.css";

/**
 * The owner's "Built with Cyrus" badges (docs/cyrus/asset-picks.json), dark + light artwork:
 *   pill   = the generic "Built with Cyrus" badge,
 *   laurel = the Community-tested seal (ONLY for mods that earn lib/cyrus-mods/tested.ts),
 *   shield = the compact badge for tight spaces.
 * tone "auto" follows the portal theme (html[data-theme]); "onDark" / "onLight" pin a variant for
 * fixed islands. Files: public/cyrus/community/badge-<variant>-<dark|light>.webp.
 *
 * MERGE NOTE (Cyrus v6): the studio-ui agent owns components/cyrus/brand/BuiltWithCyrusBadge. This
 * is a stand-in with the same idea (variant + tone + height); when both land, keep theirs and point
 * the imports here at it (and drop public/cyrus/community/badge-* if they ship the same art).
 */
export type BadgeVariant = "pill" | "laurel" | "shield";
const RATIO: Record<BadgeVariant, number> = { pill: 360 / 146, laurel: 240 / 218, shield: 160 / 205 };
const LABEL: Record<BadgeVariant, string> = { pill: "Built with Cyrus", laurel: "Community-tested: built with Cyrus", shield: "Built with Cyrus" };

export function BuiltWithCyrusBadge({ variant = "pill", tone = "auto", height = 24, className = "", title }: { variant?: BadgeVariant; tone?: "auto" | "onDark" | "onLight"; height?: number; className?: string; title?: string }) {
  const w = Math.round(height * RATIO[variant]);
  const img = (t: "dark" | "light", cls: string) => (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={`/cyrus/community/badge-${variant}-${t}.webp`} width={w} height={height} alt="" aria-hidden className={cls} style={{ width: w, height, objectFit: "contain" }} draggable={false} />
  );
  return (
    <span className={`cyb-badge inline-flex flex-none ${className}`} title={title ?? LABEL[variant]} role="img" aria-label={title ?? LABEL[variant]} data-badge={variant}>
      {tone !== "onLight" && img("dark", tone === "auto" ? "cyb-on-dark" : "")}
      {tone !== "onDark" && img("light", tone === "auto" ? "cyb-on-light" : "")}
    </span>
  );
}
EOF
