const S = ({ size = 14, className = "", children, fill = "none" }: { size?: number; className?: string; children: React.ReactNode; fill?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill={fill} stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" aria-hidden focusable="false" className={className}>
    {children}
  </svg>
);
export const StarIcon = ({ filled, ...p }: P) => <S {...p} fill={filled ? "currentColor" : "none"}><path d="m12 3.2 2.7 5.5 6 .9-4.35 4.25 1.03 6-5.38-2.83-5.38 2.83 1.03-6L3.3 9.6l6-.9Z" /></S>;
export const RemixIcon = (p: P) => <S {...p}><circle cx="6" cy="5" r="2.2" /><circle cx="6" cy="19" r="2.2" /><circle cx="18" cy="8" r="2.2" /><path d="M6 7.2v9.6M18 10.2c0 4-6 3.2-11 6.8" /></S>;
export const PlusIcon = (p: P) => <S {...p}><path d="M12 5v14M5 12h14" /></S>;
export const CheckIcon = (p: P) => <S {...p}><path d="m5 12.5 4.5 4.5L19 7.5" /></S>;
export const FlagIcon = (p: P) => <S {...p}><path d="M5 21V4M5 4h11l-2 4 2 4H5" /></S>;
export const StackIcon = (p: P) => <S {...p}><path d="m12 3 9 5-9 5-9-5Z" /><path d="m3 13 9 5 9-5" /></S>;
export const UserIcon = (p: P) => <S {...p}><circle cx="12" cy="8" r="3.6" /><path d="M4.5 20.5c1.2-3.8 4-5.6 7.5-5.6s6.3 1.8 7.5 5.6" /></S>;
export const LinkIcon = (p: P) => <S {...p}><path d="M14 5h5v5M19 5l-8 8M10 6H6a1 1 0 0 0-1 1v11a1 1 0 0 0 1 1h11a1 1 0 0 0 1-1v-4" /></S>;
export const PinIcon = (p: P) => <S {...p}><path d="M9 3h6l-1 6 4 3v2H6v-2l4-3Z" /><path d="M12 14v7" /></S>;
export const ServerIcon = (p: P) => <S {...p}><rect x="4" y="4" width="16" height="7" rx="1.6" /><rect x="4" y="13" width="16" height="7" rx="1.6" /><path d="M8 7.5h.01M8 16.5h.01" /></S>;
export const ImageIcon = (p: P) => <S {...p}><rect x="3.5" y="4.5" width="17" height="15" rx="2" /><circle cx="9" cy="10" r="1.8" /><path d="m4 18 5.5-5 4 3.5 2.5-2 4 3.5" /></S>;
export const TrashIcon = (p: P) => <S {...p}><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3" /></S>;
export const ArrowIcon = ({ dir = "left", ...p }: P & { dir?: "left" | "right" | "up" | "down" }) => (
  <S {...p}><path d={dir === "left" ? "M15 5l-7 7 7 7" : dir === "right" ? "M9 5l7 7-7 7" : dir === "up" ? "M5 15l7-7 7 7" : "M5 9l7 7 7-7"} /></S>
);

