"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { CY_CTA } from "./cta";
import { addToMyCyrus, collectionsForMenu, createCyrusCollection, rateCyrusMod, remixCyrusMod, removeFromMyCyrus, reportCyrusContent, setCollectionItem, toggleCyrusStar } from "@/lib/actions-cyrus-community";
import type { RemixDecision } from "@/lib/cyrus-mods/remix";
import { CheckIcon, FlagIcon, PlusIcon, RemixIcon, StackIcon, StarIcon } from "./cxIcons";

const GHOST_DARK = "inline-flex items-center justify-center gap-1.5 rounded-[11px] border border-white/20 bg-white/[0.07] px-3.5 py-2 text-[12.5px] font-semibold text-white transition hover:bg-white/[0.12] disabled:opacity-50";
const GHOST = "inline-flex items-center justify-center gap-1.5 rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx transition hover:border-violet/50 disabled:opacity-50";

type Res = { ok?: true; error?: string };
const reach = (): Res => ({ error: "Couldn't reach Nxeon." });

/** "Remix in my Cyrus" (or "Open in Cyrus" for the creator). Disabled with the reason when not allowed. */
export function RemixButton({ slug, buildId, decision, small = false, onDark = false }: { slug: string; buildId?: string; decision: RemixDecision; small?: boolean; onDark?: boolean }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  if (!decision.ok) {
    if (small) return null;
    return <span className={(onDark ? "border-white/15 bg-white/[0.05] text-white/65" : "border-rim-hi bg-well text-tx-dim") + " max-w-[260px] rounded-[11px] border px-3.5 py-2 text-center text-[11.5px] leading-snug"} data-testid="remix-unavailable">{decision.message}</span>;
  }
  const label = decision.mode === "own" ? (small ? "Open in Cyrus" : "Open in Cyrus") : small ? "Remix this version" : "Remix in my Cyrus";
  const go = async () => {
    setBusy(true);
    setErr(null);
    const r = await remixCyrusMod(slug, buildId ?? null).catch(() => ({ error: "Couldn't reach Nxeon." }) as { error: string; href?: string });
    if ("error" in r && r.error) { setBusy(false); setErr(r.error); return; }
    window.location.assign((r as { href: string }).href); // full load: Cyrus reads the new project on the server
  };
  return (
    <span className="inline-flex flex-col">
      <button type="button" onClick={go} disabled={busy} data-testid="remix-button"
        className={small ? "inline-flex items-center gap-1 font-semibold text-violet hover:underline disabled:opacity-50" : `${CY_CTA} px-4 py-2 text-[12.5px]`}>
        <RemixIcon size={small ? 12 : 14} />
        {busy ? (decision.mode === "own" ? "Opening Cyrus…" : "Safety-checking and copying…") : label}
      </button>
      {err && <span className="mt-1 max-w-[260px] text-[11.5px] text-rose" role="alert">{err}</span>}
    </span>
  );
}

export function StarButton({ slug, starred, count, disabled, onDark = false }: { slug: string; starred: boolean; count: number; disabled?: string | null; onDark?: boolean }) {
  const [on, setOn] = useState(starred);
  const [n, setN] = useState(count);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const click = () =>
    start(async () => {
      setErr(null);
      const r = await toggleCyrusStar(slug).catch(reach);
      if ("error" in r && r.error) { setErr(r.error); return; }
      const ok = r as { starred: boolean; count: number };
      setOn(ok.starred);
      setN(ok.count);
    });
  return (
    <span className="inline-flex flex-col">
      <button type="button" onClick={click} disabled={pending || !!disabled} title={disabled ?? (on ? "Unstar" : "Star this mod")} aria-pressed={on} data-testid="star-button"
        className={onDark ? GHOST_DARK : GHOST}>
        <StarIcon size={14} filled={on} className={on ? "text-amber-300" : ""} />
        <span>{on ? "Starred" : "Star"}</span>
        <span className="num opacity-80">{n}</span>
      </button>
      {err && <span className="mt-1 text-[11.5px] text-rose" role="alert">{err}</span>}
    </span>
  );
}

export function LibraryButton({ slug, inLibrary, onDark = false }: { slug: string; inLibrary: boolean; onDark?: boolean }) {
  const [on, setOn] = useState(inLibrary);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const click = () =>
    start(async () => {
      setErr(null);
      const r = on ? await removeFromMyCyrus(slug).catch(reach) : await addToMyCyrus(slug).catch(reach);
      if ("error" in r && r.error) { setErr(r.error); return; }
      setOn(!on);
    });
  return (
    <span className="inline-flex flex-col">
      <button type="button" onClick={click} disabled={pending} data-testid="library-button" className={onDark ? GHOST_DARK : GHOST}
        title={on ? "Remove it from your Cyrus map" : "Show it on your Cyrus map as a read-only branch: install it or remix it from there. Nothing is copied until you remix."}>
        {on ? <CheckIcon size={14} /> : <PlusIcon size={14} />}
        {on ? "On your Cyrus map" : "Add to my Cyrus"}
      </button>
      {on && <a href="/dashboard/cyrus" className={(onDark ? "text-white/70 hover:text-white" : "text-tx-dim hover:text-tx") + " mt-1 text-center text-[11px] underline-offset-2 hover:underline"}>Open Cyrus</a>}
      {err && <span className="mt-1 max-w-[220px] text-[11.5px] text-rose" role="alert">{err}</span>}
    </span>
  );
}

/** "Save to collection" popover: the viewer's collections + a quick "new collection". */
export function CollectionMenu({ slug, onDark = false }: { slug: string; onDark?: boolean }) {
  const [open, setOpen] = useState(false);
  const [list, setList] = useState<{ id: string; slug: string; title: string; has: boolean; count: number }[] | null>(null);
  const [title, setTitle] = useState("");
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const box = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const away = (e: MouseEvent) => { if (box.current && !box.current.contains(e.target as Node)) setOpen(false); };
    const esc = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", away);
    document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("mousedown", away); document.removeEventListener("keydown", esc); };
  }, [open]);
  const load = () =>
    start(async () => {
      const r = await collectionsForMenu(slug).catch(reach);
      if ("error" in r && r.error) { setErr(r.error); return; }
      setList((r as { collections: NonNullable<typeof list> }).collections);
    });
  const toggle = (id: string, has: boolean) =>
    start(async () => {
      setErr(null);
      const r = await setCollectionItem(id, slug, !has).catch(reach);
      if ("error" in r && r.error) { setErr(r.error); return; }
      setList((l) => l?.map((c) => (c.id === id ? { ...c, has: !has, count: c.count + (has ? -1 : 1) } : c)) ?? null);
    });
  const create = () =>
    start(async () => {
      setErr(null);
      const r = await createCyrusCollection({ title, addSlug: slug }).catch(reach);
      if ("error" in r && r.error) { setErr(r.error); return; }
      const c = r as { id: string; slug: string };
      setList((l) => [{ id: c.id, slug: c.slug, title, has: true, count: 1 }, ...(l ?? [])]);
      setTitle("");
    });
  return (
    <div className="relative inline-flex" ref={box}>
      <button type="button" className={onDark ? GHOST_DARK : GHOST} aria-expanded={open} onClick={() => { setOpen(!open); if (!list) load(); }} data-testid="collection-button">
        <StackIcon size={14} /> Save to collection
      </button>
      {open && (
        <div className="absolute right-0 top-[calc(100%+6px)] z-30 w-[min(300px,calc(100vw-32px))] rounded-[14px] border border-rim-hi bg-surface p-3 text-left shadow-[0_20px_50px_-20px_rgba(0,0,0,.6)]" role="dialog" aria-label="Save to a collection">
          <p className="text-[12.5px] font-extrabold text-tx">Your collections</p>
          {!list ? <p className="mt-2 text-[12px] text-tx-faint">Loading…</p> : list.length === 0 ? <p className="mt-1 text-[12px] text-tx-dim">None yet. Make one below: a modpack, a theme, a server setup.</p> : (
            <ul className="mt-2 flex max-h-[220px] flex-col gap-1 overflow-y-auto">
              {list.map((c) => (
                <li key={c.id}>
                  <label className="flex cursor-pointer items-center gap-2 rounded-[8px] px-2 py-1.5 text-[12.5px] text-tx hover:bg-well">
                    <input type="checkbox" checked={c.has} disabled={pending} onChange={() => toggle(c.id, c.has)} />
                    <span className="min-w-0 flex-1 truncate">{c.title}</span>
                    <span className="num text-[11px] text-tx-faint">{c.count}</span>
                  </label>
                </li>
              ))}
            </ul>
          )}
          <div className="mt-2 flex gap-1.5 border-t border-rim pt-2">
            <input value={title} onChange={(e) => setTitle(e.target.value)} maxLength={60} placeholder="New collection" aria-label="New collection name" className="input h-8 min-w-0 flex-1 py-1 text-[12.5px]" />
            <button type="button" disabled={pending || title.trim().length < 3} onClick={create} className={`${CY_CTA} px-3 py-1 text-[12px]`}>Create</button>
          </div>
          {err && <p className="mt-1.5 text-[11.5px] text-rose" role="alert">{err}</p>}
        </div>
      )}
    </div>
  );
}

