"use client";

import { useEffect, useState } from "react";
import type { MediaView } from "@/lib/cyrus-mods/social";
import { ArrowIcon } from "./cxIcons";
import { ReportLink } from "./CommunityActions";

/** The creator's photo gallery: a responsive grid, a keyboard lightbox, report per photo. */
export function Gallery({ photos, title, canReport }: { photos: MediaView[]; title: string; canReport: boolean }) {
  const [at, setAt] = useState<number | null>(null);
  useEffect(() => {
    if (at === null) return;
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape") setAt(null);
      if (e.key === "ArrowRight") setAt((i) => (i === null ? i : (i + 1) % photos.length));
      if (e.key === "ArrowLeft") setAt((i) => (i === null ? i : (i - 1 + photos.length) % photos.length));
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [at, photos.length]);
  if (!photos.length) return null;
  const cur = at !== null ? photos[at] : null;
  return (
    <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Photos" data-testid="cyrus-gallery">
      <h2 className="text-[15px] font-extrabold text-tx">Photos <span className="num text-[12px] font-semibold text-tx-faint">{photos.length}</span></h2>
      <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">
        {photos.map((p, i) => (
          <button key={p.id} type="button" onClick={() => setAt(i)} className={"group relative overflow-hidden rounded-[12px] border border-rim-hi bg-well " + (i === 0 && photos.length > 2 ? "col-span-2 row-span-2" : "")} aria-label={p.caption ? `Open photo: ${p.caption}` : `Open photo ${i + 1}`}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={p.url} alt={p.caption ?? `${title}, photo ${i + 1}`} loading="lazy" className="aspect-[16/10] h-full w-full object-cover transition group-hover:scale-[1.02]" />
            {p.hidden && <span className="absolute left-2 top-2 rounded-full bg-rose/90 px-2 py-0.5 text-[10px] font-bold uppercase text-[#fff]">Hidden</span>}
            {p.caption && <span className="absolute inset-x-0 bottom-0 truncate bg-gradient-to-t from-black/70 to-transparent px-2.5 pb-1.5 pt-5 text-left text-[11.5px] text-[#fff]">{p.caption}</span>}
          </button>
        ))}
      </div>
      {cur && (
        <div className="cyx-lightbox" role="dialog" aria-modal="true" aria-label={cur.caption ?? "Photo"} onMouseDown={(e) => { if (e.target === e.currentTarget) setAt(null); }}>
          <div className="flex w-full max-w-[1200px] flex-col items-center gap-3">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={cur.url} alt={cur.caption ?? title} />
            <div className="flex w-full flex-wrap items-center justify-between gap-2 text-[12.5px] text-[#e5e9ff]">
              <span className="min-w-0 flex-1 truncate">{cur.caption ?? `${title} · ${at! + 1} / ${photos.length}`}</span>
              <span className="flex items-center gap-2">
                {canReport && <span className="rounded-[8px] bg-white/10 px-2 py-1"><ReportLink kind="MEDIA" target={cur.id} label="Report photo" /></span>}
                {photos.length > 1 && <>
                  <button type="button" className="grid h-9 w-9 place-items-center rounded-full bg-white/10 hover:bg-white/20" aria-label="Previous photo" onClick={() => setAt((at! - 1 + photos.length) % photos.length)}><ArrowIcon dir="left" size={16} /></button>
                  <button type="button" className="grid h-9 w-9 place-items-center rounded-full bg-white/10 hover:bg-white/20" aria-label="Next photo" onClick={() => setAt((at! + 1) % photos.length)}><ArrowIcon dir="right" size={16} /></button>
                </>}
                <button type="button" className="rounded-full bg-white/10 px-3 py-1.5 font-semibold hover:bg-white/20" onClick={() => setAt(null)}>Close</button>
              </span>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}
