"use client";

import Link from "next/link";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { CommunityVersion, CommunityVersionGroup } from "@/lib/cyrus-mods/social";
import { endorseCommunityVersion } from "@/lib/actions-cyrus-community";
import { PinIcon, RemixIcon, StarIcon } from "./cxIcons";

type FileDiff = { path: string; status: "added" | "removed" | "changed"; additions: number; deletions: number; ops: { t: "eq" | "add" | "del"; a: number | null; b: number | null; text: string }[] };

const day = (s: string) => new Date(s).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });

/** Test status from facts only: it compiled (every listed version did), the safety verdict, open bugs, the remix re-scan. */
function TestStatus({ v, scan }: { v: CommunityVersion; scan: string | null }) {
  const chip = (ok: boolean | null, text: string) => (
    <span className={"rounded-full border px-2 py-0.5 text-[10.5px] font-semibold " + (ok === null ? "border-rim-hi bg-well text-tx-dim" : ok ? "border-mint/40 bg-mint/10 text-mint" : "border-amber/40 bg-amber/10 text-amber")}>{text}</span>
  );
  return (
    <span className="flex flex-wrap gap-1.5" aria-label="Test status">
      {chip(true, "Compiled")}
      {chip(v.safety === "pass" ? true : v.safety === "warn" ? null : false, v.safety === "pass" ? "Safety check passed" : v.safety === "warn" ? "Safety check: notes" : "Not scanned")}
      {scan && chip(scan === "pass" ? true : scan === "warn" ? null : false, scan === "pass" ? "Remix re-scan passed" : scan === "warn" ? "Remix re-scan: notes" : "Remix re-scan failed")}
      {chip(v.openBugs === 0, v.openBugs ? `${v.openBugs} open bug${v.openBugs === 1 ? "" : "s"}` : "No open bugs")}
    </span>
  );
}

function DiffView({ slug, build, against, onClose }: { slug: string; build: string; against: string; onClose: () => void }) {
  const [state, setState] = useState<{ files?: FileDiff[]; error?: string } | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  if (state === null) {
    fetch(`/api/nxlabs/cyrus/${slug}/diff?build=${encodeURIComponent(build)}&against=${encodeURIComponent(against)}`)
      .then(async (r) => setState(r.ok ? await r.json() : { error: (await r.json().catch(() => ({}))).error || "Couldn't compare these versions." }))
      .catch(() => setState({ error: "Couldn't reach Nxeon." }));
    setState({});
  }
  const files = state?.files;
  return (
    <div className="mt-3 rounded-[12px] border border-rim-hi bg-well p-3" data-testid="community-diff">
      <div className="flex items-center gap-2">
        <p className="text-[12.5px] font-extrabold text-tx">What changed</p>
        {files && <span className="text-[11.5px] text-tx-faint">{files.length} file{files.length === 1 ? "" : "s"} · <span className="text-mint">+{files.reduce((a, f) => a + f.additions, 0)}</span> <span className="text-rose">−{files.reduce((a, f) => a + f.deletions, 0)}</span></span>}
        <button type="button" onClick={onClose} className="ml-auto text-[11.5px] font-semibold text-tx-dim hover:text-tx">Hide</button>
      </div>
      {state?.error ? <p className="mt-2 text-[12px] text-rose">{state.error}</p> : !files ? <p className="mt-2 text-[12px] text-tx-faint">Comparing the source…</p> : files.length === 0 ? <p className="mt-2 text-[12px] text-tx-dim">No source changes (only the build itself differs).</p> : (
        <ul className="mt-2 flex flex-col gap-1.5">
          {files.map((f) => (
            <li key={f.path} className="overflow-hidden rounded-[9px] border border-rim-hi bg-surface">
              <button type="button" onClick={() => setOpen(open === f.path ? null : f.path)} className="flex w-full items-center gap-2 px-2.5 py-1.5 text-left text-[12px]" aria-expanded={open === f.path}>
                <span className={"rounded px-1.5 text-[10px] font-bold uppercase " + (f.status === "added" ? "bg-mint/15 text-mint" : f.status === "removed" ? "bg-rose/15 text-rose" : "bg-violet/15 text-violet")}>{f.status}</span>
                <span className="min-w-0 flex-1 truncate font-mono text-[11.5px] text-tx">{f.path.replace(/^src\/main\//, "")}</span>
                <span className="num text-[11px] text-mint">+{f.additions}</span>
                <span className="num text-[11px] text-rose">−{f.deletions}</span>
              </button>
              {open === f.path && (
                <div className="cyx-diff border-t border-rim-hi">
                  {f.ops.map((o, i) => (
                    <div key={i} className={"r " + (o.t === "add" ? "add" : o.t === "del" ? "del" : o.a === null && o.b === null ? "gap" : "")}>
                      <span className="n">{o.a ?? ""}</span><span className="n">{o.b ?? ""}</span><span className="text-tx-faint">{o.t === "add" ? "+" : o.t === "del" ? "−" : ""}</span><span className="text-tx">{o.text}</span>
                    </div>
                  ))}
                </div>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * "Community versions": published remixes built on this mod (and remixes of those), each with the
 * version of THIS mod it started from, its own versions, test status and a source diff against
 * that base. The original's creator can pin one.
 */
export function CommunityVersions({ slug, base, groups, endorsedBuildId, isCreator, title }: { slug: string; base: string; groups: CommunityVersionGroup[]; endorsedBuildId: string | null; isCreator: boolean; title: string }) {
  const [diff, setDiff] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  const router = useRouter();
  const endorse = (id: string | null) =>
    start(async () => {
      setErr(null);
      const r = await endorseCommunityVersion(slug, id).catch(() => ({ error: "Couldn't reach Nxeon." }));
      if ("error" in r && r.error) setErr(r.error);
      router.refresh();
    });
  if (!groups.length) {
    return (
      <section className="rounded-[16px] border border-rim-hi bg-surface px-5 py-10 text-center" aria-label="Community versions" data-testid="community-versions-empty">
        <span className="mx-auto grid h-11 w-11 place-items-center rounded-full border border-violet/35 bg-violet/10 text-violet"><RemixIcon size={20} /></span>
        <p className="mt-3 text-[14px] font-bold text-tx">No community versions yet</p>
        <p className="mx-auto mt-1 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">When someone remixes {title} in their Cyrus and publishes their changes, their versions show up here with what they changed and how they tested.</p>
      </section>
    );
  }
  return (
    <section className="flex flex-col gap-3" aria-label="Community versions" data-testid="community-versions">
      <p className="text-[12.5px] leading-relaxed text-tx-dim">Remixes of {title} that their creators published. Every version listed compiled and went through the safety check; open the changes to see exactly what differs from the version it was built on.</p>
      {err && <p className="text-[12px] text-rose" role="alert">{err}</p>}
      {groups.map((g) => (
        <article key={g.pageId} className={"rounded-[16px] border bg-surface p-4 " + (g.versions.some((v) => v.buildId === endorsedBuildId) ? "border-violet/50" : "border-rim-hi")}>
          <header className="flex flex-wrap items-start gap-x-3 gap-y-1">
            <div className="min-w-0 flex-1">
              <Link href={`${base}/${g.slug}`} prefetch={false} className="text-[14.5px] font-extrabold text-tx hover:text-violet">{g.title}</Link>
              <p className="text-[11.5px] text-tx-faint">
                by {g.creatorHandle ? <Link href={`${base}/u/${g.creatorHandle}`} prefetch={false} className="font-semibold text-tx-dim hover:text-tx">{g.creator}</Link> : <span className="font-semibold text-tx-dim">{g.creator}</span>}
                {g.baseLabel && <> · built on <span className="num font-semibold text-tx-dim">{g.baseLabel}</span></>}
                {g.depth > 1 && <> · {g.via ? <>via <Link href={`${base}/${g.via.slug}`} prefetch={false} className="font-semibold text-tx-dim hover:text-tx">{g.via.title}</Link></> : "via another remix"}</>}
              </p>
            </div>
            <span className="flex items-center gap-3 text-[11.5px] text-tx-faint">
              <span className="inline-flex items-center gap-1"><StarIcon size={11} />{g.stars}</span>
              <span>{g.installers} installer{g.installers === 1 ? "" : "s"}</span>
            </span>
          </header>
          <ol className="mt-3 flex flex-col divide-y divide-[var(--color-rim)]">
            {g.versions.map((v) => {
              const pinned = v.buildId === endorsedBuildId;
              return (
                <li key={v.buildId} className="py-2.5 first:pt-0 last:pb-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="num text-[13px] font-extrabold text-tx">{v.label}</span>
                    {pinned && <span className="inline-flex items-center gap-1 rounded-full border border-violet/40 bg-violet/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-violet"><PinIcon size={10} />Pinned by the creator</span>}
                    <span className="text-[11.5px] text-tx-faint">{day(v.at)} · MC {v.mcVersion}</span>
                  </div>
                  <p className="mt-1 whitespace-pre-line text-[12.5px] leading-relaxed text-tx-body">{v.notes}</p>
                  <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-2">
                    <TestStatus v={v} scan={g.scan} />
                    {g.baseBuildId && <button type="button" onClick={() => setDiff(diff === v.buildId ? null : v.buildId)} className="text-[12px] font-semibold text-violet hover:underline" aria-expanded={diff === v.buildId}>{diff === v.buildId ? "Hide changes" : "View changes"}</button>}
                    <a href={`/api/nxlabs/cyrus/${g.slug}/download?what=source&build=${v.buildId}`} rel="nofollow" className="text-[12px] font-semibold text-violet hover:underline">source</a>
                    {isCreator && (pinned
                      ? <button type="button" disabled={pending} onClick={() => endorse(null)} className="text-[12px] font-semibold text-tx-dim hover:text-tx">Unpin</button>
                      : <button type="button" disabled={pending} onClick={() => endorse(v.buildId)} className="inline-flex items-center gap-1 text-[12px] font-semibold text-tx-dim hover:text-violet"><PinIcon size={11} />Pin on my page</button>)}
                  </div>
                  {diff === v.buildId && g.baseBuildId && <DiffView slug={g.slug} build={v.buildId} against={g.baseBuildId} onClose={() => setDiff(null)} />}
                </li>
              );
            })}
          </ol>
        </article>
      ))}
    </section>
  );
}

