import Link from "next/link";
import type { TreeNode } from "@/lib/cyrus-mods/remix";
import { treeSize } from "@/lib/cyrus-mods/remix";
import { RemixIcon, StarIcon } from "./cxIcons";

/** The remix family of a mod: the original at the top, every visible remix below it (private ones only as placeholders that keep a branch readable). */
export function RemixTree({ tree, base, currentPageId }: { tree: TreeNode; base: string; currentPageId: string }) {
  const Row = ({ n }: { n: TreeNode }) => (
    <li>
      <div className={"my-1 flex min-w-0 items-center gap-2 rounded-[10px] border px-2.5 py-1.5 " + (n.pageId === currentPageId ? "border-violet/50 bg-violet/[0.07]" : "border-rim-hi bg-surface")}>
        <span className={"grid h-6 w-6 flex-none place-items-center rounded-full " + (n.depth === 0 ? "bg-violet/15 text-violet" : "bg-well text-tx-dim")}><RemixIcon size={12} /></span>
        {n.anonymous ? (
          <span className="min-w-0 flex-1 truncate text-[12.5px] italic text-tx-faint">A private remix</span>
        ) : (
          <span className="min-w-0 flex-1 truncate text-[12.5px]">
            {n.pageId === currentPageId ? <strong className="font-extrabold text-tx">{n.title}</strong> : <Link href={`${base}/${n.slug}`} prefetch={false} className="font-bold text-tx hover:text-violet">{n.title}</Link>}
            <span className="text-tx-faint"> by {n.creator}</span>
            {n.baseLabel && <span className="num text-tx-faint"> · from {n.baseLabel}</span>}
          </span>
        )}
        {!n.anonymous && <span className="hidden flex-none items-center gap-2 text-[11px] text-tx-faint sm:flex"><span className="inline-flex items-center gap-0.5"><StarIcon size={10} />{n.stars ?? 0}</span><span>{n.versions ?? 0} v</span></span>}
        {n.depth === 0 && <span className="flex-none rounded-full border border-violet/40 bg-violet/10 px-1.5 py-0.5 text-[9.5px] font-bold uppercase tracking-wide text-violet">Original</span>}
      </div>
      {n.children.length > 0 && <ul>{n.children.map((c) => <Row key={c.pageId} n={c} />)}</ul>}
    </li>
  );
  return (
    <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-label="Remix tree" data-testid="remix-tree">
      <h2 className="text-[15px] font-extrabold text-tx">Remix tree <span className="num text-[12px] font-semibold text-tx-faint">{treeSize(tree)} mods</span></h2>
      <p className="mt-1 text-[12px] text-tx-dim">Who built on whom. Each remix keeps the credit of everything above it.</p>
      <ul className="cyx-tree mt-3 !ml-0 !border-l-0 !pl-0">
        <Row n={tree} />
      </ul>
    </section>
  );
}
EOF
