// ── fork / build on this mod ────────────────────────────────────────────────

/**
 * "Build on this mod": the creator just opens their own version in Cyrus. Anyone
 * else gets their OWN copy of the chosen version (jar + generated docs copied,
 * status succeeded), recorded in CyrusFork so change requests on it go to the
 * build service with the ORIGINAL build as base. Needs Cyrus access (private
 * preview today). The copy's own page is private until they publish it.
 */
export async function forkCyrusMod(slug: string, buildId?: string | null): Promise<{ ok?: true; error?: string; href?: string }> {
  // Cyrus v6: one path for building on someone's mod. remixCyrusMod adds the creator's remix
  // setting, the re-scan of the copied code, the prompt history and the lineage row.
  const r = await remixCyrusMod(slug, buildId);
  return "error" in r && r.error ? { error: r.error } : { ok: true, href: (r as { href: string }).href };
}
