"use client";

import Link from "next/link";
import { useMemo, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { CY_CTA } from "./cta";
import { deleteListingMedia, saveModListing } from "@/lib/actions-cyrus-community";
import { LISTING_LIMITS, listingHtml, normaliseTag, type ListingLink, type RemixPolicy } from "@/lib/cyrus-mods/listing";
import type { MediaView } from "@/lib/cyrus-mods/social";
import type { CategoryKey } from "@/lib/cyrus/types";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { ArrowIcon, ImageIcon, PlusIcon, TrashIcon } from "./cxIcons";

export type EditorInit = {
  slug: string;
  rootBuildId: string;
  title: string;
  generatedTagline: string | null;
  tagline: string;
  description: string;
  category: string | null;
  autoCategory: string | null;
  tags: string[];
  links: ListingLink[];
  changelog: Record<string, string>;
  visibility: "PUBLIC" | "PRIVATE";
  remixPolicy: RemixPolicy;
  license: string;
  icon: MediaView | null;
  banner: MediaView | null;
  photos: MediaView[];
  versions: { buildId: string; label: string; notes: string }[];
  categories: { key: string; label: string; description: string }[];
};

const L = LISTING_LIMITS;
const Section = ({ title, sub, children, id }: { title: string; sub?: string; children: React.ReactNode; id: string }) => (
  <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-labelledby={id}>
    <h2 id={id} className="text-[15px] font-extrabold text-tx">{title}</h2>
    {sub && <p className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">{sub}</p>}
    <div className="mt-3.5 flex flex-col gap-3.5">{children}</div>
  </section>
);
const Field = ({ label, hint, children, count }: { label: string; hint?: string; children: React.ReactNode; count?: string }) => (
  <label className="flex flex-col gap-1.5">
    <span className="flex items-baseline gap-2 text-[12.5px] font-bold text-tx">{label}{count && <span className="num ml-auto text-[11px] font-normal text-tx-faint">{count}</span>}</span>
    {children}
    {hint && <span className="text-[11.5px] leading-relaxed text-tx-faint">{hint}</span>}
  </label>
);

/** NxLabs "Edit listing": everything the creator can change about their mod's page. */
export function ListingEditor({ init }: { init: EditorInit }) {
  const router = useRouter();
  const [title, setTitle] = useState(init.title);
  const [tagline, setTagline] = useState(init.tagline);
  const [description, setDescription] = useState(init.description);
  const [preview, setPreview] = useState(false);
  const [category, setCategory] = useState<string | null>(init.category);
  const [tags, setTags] = useState<string[]>(init.tags);
  const [tagDraft, setTagDraft] = useState("");
  const [links, setLinks] = useState<ListingLink[]>(init.links.length ? init.links : []);
  const [changelog, setChangelog] = useState<Record<string, string>>(init.changelog);
  const [visibility, setVisibility] = useState(init.visibility);
  const [remixPolicy, setRemixPolicy] = useState<RemixPolicy>(init.remixPolicy);
  const [icon, setIcon] = useState<MediaView | null>(init.icon);
  const [banner, setBanner] = useState<MediaView | null>(init.banner);
  const [photos, setPhotos] = useState<MediaView[]>(init.photos);
  const [uploading, setUploading] = useState<string | null>(null);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, start] = useTransition();
  const iconInput = useRef<HTMLInputElement>(null);
  const bannerInput = useRef<HTMLInputElement>(null);
  const photoInput = useRef<HTMLInputElement>(null);
  const html = useMemo(() => (preview ? listingHtml(description) : ""), [preview, description]);

  const upload = async (files: FileList | null, kind: "icon" | "banner" | "photo") => {
    if (!files?.length) return;
    setMsg(null);
    for (const f of Array.from(files).slice(0, kind === "photo" ? L.photos - photos.length : 1)) {
      setUploading(kind);
      const fd = new FormData();
      fd.append("file", f);
      fd.append("kind", kind);
      const r = await fetch(`/api/nxlabs/cyrus/${init.slug}/media`, { method: "POST", body: fd }).catch(() => null);
      const j = r ? await r.json().catch(() => ({})) : {};
      if (!r?.ok) { setMsg({ ok: false, text: j.error || "That upload didn't go through." }); break; }
      if (kind === "icon") setIcon(j.media);
      else if (kind === "banner") setBanner(j.media);
      else setPhotos((p) => [...p, j.media]);
    }
    setUploading(null);
  };

  const removePhoto = (id: string) =>
    start(async () => {
      const r = await deleteListingMedia(id).catch(() => ({ error: "Couldn't reach Nxeon." }));
      if ("error" in r && r.error) { setMsg({ ok: false, text: r.error }); return; }
      setPhotos((p) => p.filter((x) => x.id !== id));
    });
  const move = (i: number, d: -1 | 1) => setPhotos((p) => {
    const j = i + d;
    if (j < 0 || j >= p.length) return p;
    const n = [...p];
    [n[i], n[j]] = [n[j], n[i]];
    return n;
  });
  const addTag = (raw: string) => {
    const parts = raw.split(/[,\n]/).map(normaliseTag).filter((t) => t.length >= L.tagMin);
    if (parts.length) setTags((t) => [...new Set([...t, ...parts])].slice(0, L.tags));
    setTagDraft("");
  };

  const save = () =>
    start(async () => {
      setMsg(null);
      const r = await saveModListing(init.rootBuildId, {
        title,
        tagline,
        description,
        category,
        tags,
        links: links.filter((l) => l.label.trim() || l.url.trim()),
        changelog,
        visibility,
        remixPolicy,
        iconMediaId: icon?.id ?? null,
        bannerMediaId: banner?.id ?? null,
        photoOrder: photos.map((p) => p.id),
        captions: Object.fromEntries(photos.map((p) => [p.id, p.caption ?? ""])),
      }).catch(() => ({ error: "Couldn't reach Nxeon." }));
      if ("error" in r && r.error) { setMsg({ ok: false, text: r.error }); return; }
      setMsg({ ok: true, text: "Saved." });
      router.push(`/dashboard/nxlabs/cyrus/${init.slug}`);
      router.refresh();
    });

  const goingPublic = visibility === "PUBLIC" && init.visibility !== "PUBLIC";
  return (
    <div className="flex flex-col gap-4 pb-24" data-testid="listing-editor">
      <Section id="ed-basics" title="Basics" sub="What people see first, on the card and at the top of the page.">
        <Field label="Name" count={`${title.length}/${L.titleMax}`} hint="Also renames the project in your Cyrus.">
          <input className="input" value={title} maxLength={L.titleMax} onChange={(e) => setTitle(e.target.value)} data-testid="ed-title" />
        </Field>
        <Field label="Short description" count={`${tagline.length}/${L.taglineMax}`} hint={init.generatedTagline ? `Leave empty to use Cyrus's: “${init.generatedTagline}”` : undefined}>
          <input className="input" value={tagline} maxLength={L.taglineMax} placeholder={init.generatedTagline ?? "One line about what it does"} onChange={(e) => setTagline(e.target.value)} data-testid="ed-tagline" />
        </Field>
        <div className="flex flex-col gap-1.5">
          <span className="text-[12.5px] font-bold text-tx">Category</span>
          <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-3 lg:grid-cols-4" role="radiogroup" aria-label="Category">
            <button type="button" role="radio" aria-checked={category === null} onClick={() => setCategory(null)} className={"flex items-center gap-2 rounded-[10px] border px-2.5 py-2 text-left text-[12px] " + (category === null ? "border-violet/60 bg-violet/10 text-tx" : "border-rim-hi bg-well text-tx-dim hover:text-tx")}>
              <span className="text-[11px] font-bold uppercase text-violet">Auto</span>
              <span className="min-w-0 truncate">{init.autoCategory ? init.categories.find((c) => c.key === init.autoCategory)?.label ?? "Cyrus decides" : "Cyrus decides"}</span>
            </button>
            {init.categories.map((c) => (
              <button key={c.key} type="button" role="radio" aria-checked={category === c.key} title={c.description} onClick={() => setCategory(c.key)} className={"flex items-center gap-2 rounded-[10px] border px-2.5 py-2 text-left text-[12px] " + (category === c.key ? "border-violet/60 bg-violet/10 text-tx" : "border-rim-hi bg-well text-tx-dim hover:text-tx")}>
                <CategoryIcon k={c.key as CategoryKey} width={16} height={16} className="flex-none text-violet" />
                <span className="min-w-0 truncate">{c.label}</span>
              </button>
            ))}
          </div>
          <span className="text-[11.5px] text-tx-faint">Cyrus sorts mods by what they do. Pick one only when it got yours wrong.</span>
        </div>
        <div className="flex flex-col gap-1.5">
          <span className="flex items-baseline text-[12.5px] font-bold text-tx">Tags <span className="num ml-auto text-[11px] font-normal text-tx-faint">{tags.length}/{L.tags}</span></span>
          <div className="flex flex-wrap items-center gap-1.5 rounded-[11px] border border-rim-hi bg-well p-1.5">
            {tags.map((t) => (
              <span key={t} className="inline-flex items-center gap-1 rounded-full border border-rim-hi bg-surface px-2 py-0.5 text-[11.5px] text-tx">#{t}
                <button type="button" aria-label={`Remove tag ${t}`} onClick={() => setTags(tags.filter((x) => x !== t))} className="text-tx-faint hover:text-rose">×</button>
              </span>
            ))}
            {tags.length < L.tags && <input value={tagDraft} onChange={(e) => setTagDraft(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === ",") { e.preventDefault(); addTag(tagDraft); } }} onBlur={() => tagDraft && addTag(tagDraft)} placeholder={tags.length ? "Add a tag" : "pvp, economy, boss…"} aria-label="Add a tag" className="min-w-[120px] flex-1 bg-transparent px-1.5 py-1 text-[12.5px] text-tx outline-none placeholder:text-tx-faint" data-testid="ed-tags" />}
          </div>
        </div>
      </Section>

      <Section id="ed-images" title="Icon, banner and photos" sub="PNG, JPG, WebP or GIF up to 8 MB. Nxeon re-encodes every image (and strips its metadata) before anyone sees it.">
        <div className="grid gap-4 sm:grid-cols-[auto_minmax(0,1fr)]">
          <div className="flex flex-col items-start gap-2">
            <span className="text-[12.5px] font-bold text-tx">Icon</span>
            <button type="button" onClick={() => iconInput.current?.click()} className="grid h-[88px] w-[88px] place-items-center overflow-hidden rounded-[20px] border border-dashed border-rim-hi bg-well text-tx-faint hover:border-violet/50" aria-label={icon ? "Replace the icon" : "Upload an icon"} data-testid="ed-icon">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {icon ? <img src={icon.url} alt="Icon" className="h-full w-full object-cover" /> : uploading === "icon" ? <span className="text-[11px]">Uploading…</span> : <ImageIcon size={22} />}
            </button>
            <input ref={iconInput} type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={(e) => { void upload(e.target.files, "icon"); e.target.value = ""; }} />
            {icon && <button type="button" onClick={() => setIcon(null)} className="text-[11.5px] font-semibold text-tx-dim hover:text-rose">Remove</button>}
          </div>
          <div className="flex min-w-0 flex-col items-stretch gap-2">
            <span className="text-[12.5px] font-bold text-tx">Banner <span className="font-normal text-tx-faint">wide, behind the title</span></span>
            <button type="button" onClick={() => bannerInput.current?.click()} className="grid aspect-[10/3] w-full place-items-center overflow-hidden rounded-[14px] border border-dashed border-rim-hi bg-well text-tx-faint hover:border-violet/50" aria-label={banner ? "Replace the banner" : "Upload a banner"} data-testid="ed-banner">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {banner ? <img src={banner.url} alt="Banner" className="h-full w-full object-cover" /> : uploading === "banner" ? <span className="text-[11px]">Uploading…</span> : <span className="flex items-center gap-2 text-[12px]"><ImageIcon size={18} />Upload a banner</span>}
            </button>
            <input ref={bannerInput} type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={(e) => { void upload(e.target.files, "banner"); e.target.value = ""; }} />
            {banner && <button type="button" onClick={() => setBanner(null)} className="self-start text-[11.5px] font-semibold text-tx-dim hover:text-rose">Remove</button>}
          </div>
        </div>
        <div className="flex flex-col gap-2">
          <span className="flex items-baseline text-[12.5px] font-bold text-tx">Photo gallery <span className="ml-2 font-normal text-tx-faint">first photo is the cover</span><span className="num ml-auto text-[11px] font-normal text-tx-faint">{photos.length}/{L.photos}</span></span>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4" data-testid="ed-photos">
            {photos.map((p, i) => (
              <div key={p.id} className="flex flex-col gap-1.5 rounded-[12px] border border-rim-hi bg-well p-1.5">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={p.url} alt={p.caption ?? `Photo ${i + 1}`} className="aspect-[16/10] w-full rounded-[8px] object-cover" />
                <input value={p.caption ?? ""} maxLength={L.captionMax} placeholder="Caption" aria-label={`Caption for photo ${i + 1}`} onChange={(e) => setPhotos((ps) => ps.map((x) => (x.id === p.id ? { ...x, caption: e.target.value } : x)))} className="input h-8 py-1 text-[12px]" />
                <div className="flex items-center gap-1">
                  <button type="button" disabled={i === 0} onClick={() => move(i, -1)} aria-label="Move earlier" className="grid h-7 w-7 place-items-center rounded-[8px] border border-rim-hi text-tx-dim hover:text-tx disabled:opacity-30"><ArrowIcon dir="left" size={13} /></button>
                  <button type="button" disabled={i === photos.length - 1} onClick={() => move(i, 1)} aria-label="Move later" className="grid h-7 w-7 place-items-center rounded-[8px] border border-rim-hi text-tx-dim hover:text-tx disabled:opacity-30"><ArrowIcon dir="right" size={13} /></button>
                  {i === 0 && <span className="text-[10.5px] font-bold uppercase text-violet">Cover</span>}
                  <button type="button" disabled={pending} onClick={() => removePhoto(p.id)} aria-label={`Delete photo ${i + 1}`} className="ml-auto grid h-7 w-7 place-items-center rounded-[8px] border border-rim-hi text-tx-dim hover:border-rose/50 hover:text-rose"><TrashIcon size={13} /></button>
                </div>
              </div>
            ))}
            {photos.length < L.photos && (
              <button type="button" onClick={() => photoInput.current?.click()} className="grid min-h-[120px] place-items-center rounded-[12px] border border-dashed border-rim-hi bg-well text-[12px] text-tx-faint hover:border-violet/50 hover:text-tx" data-testid="ed-add-photo">
                {uploading === "photo" ? "Uploading…" : <span className="flex flex-col items-center gap-1"><PlusIcon size={18} />Add photos</span>}
              </button>
            )}
          </div>
          <input ref={photoInput} type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden onChange={(e) => { void upload(e.target.files, "photo"); e.target.value = ""; }} />
          <span className="text-[11.5px] text-tx-faint">Show it running: screenshots of the menus, the scoreboard, a boss fight. Photos you upload appear on the page right away; order and captions save with the button below.</span>
        </div>
      </Section>

      <Section id="ed-desc" title="Description" sub="Markdown: headings, lists, **bold**, `code`, links. Images go in the gallery above.">
        <div className="flex gap-1 self-start rounded-[10px] border border-rim-hi bg-well p-0.5" role="tablist" aria-label="Description editor">
          {["Write", "Preview"].map((t, i) => <button key={t} type="button" role="tab" aria-selected={preview === !!i} onClick={() => setPreview(!!i)} className={"rounded-[8px] px-3 py-1 text-[12px] font-bold " + (preview === !!i ? "bg-surface text-tx" : "text-tx-dim")}>{t}</button>)}
        </div>
        {preview ? (
          html ? <div className="cyx-prose min-h-[160px] rounded-[11px] border border-rim-hi bg-well p-4" dangerouslySetInnerHTML={{ __html: html }} /> : <p className="rounded-[11px] border border-rim-hi bg-well p-4 text-[12.5px] text-tx-faint">Nothing to preview yet.</p>
        ) : (
          <Field label="Long description" count={`${description.length.toLocaleString("en-US")}/${L.descriptionMax.toLocaleString("en-US")}`}>
            <textarea className="input min-h-[220px] font-mono text-[12.5px] leading-relaxed" value={description} maxLength={L.descriptionMax} onChange={(e) => setDescription(e.target.value)} placeholder={"## What it does\n\nTell people why their server wants this.\n\n## Setup\n\n1. Install it\n2. Run /..."} data-testid="ed-description" />
          </Field>
        )}
      </Section>

      <Section id="ed-links" title="Links" sub="https only. A Discord, a wiki, a video of it in action.">
        {links.map((l, i) => (
          <div key={i} className="grid gap-2 sm:grid-cols-[minmax(0,180px)_minmax(0,1fr)_auto]">
            <input className="input" value={l.label} maxLength={L.linkLabelMax} placeholder="Label" aria-label={`Link ${i + 1} label`} onChange={(e) => setLinks(links.map((x, j) => (j === i ? { ...x, label: e.target.value } : x)))} />
            <input className="input" value={l.url} maxLength={L.linkUrlMax} placeholder="https://" aria-label={`Link ${i + 1} address`} inputMode="url" onChange={(e) => setLinks(links.map((x, j) => (j === i ? { ...x, url: e.target.value } : x)))} />
            <button type="button" onClick={() => setLinks(links.filter((_, j) => j !== i))} className="rounded-[10px] border border-rim-hi px-3 text-[12px] font-semibold text-tx-dim hover:text-rose" aria-label={`Remove link ${i + 1}`}>Remove</button>
          </div>
        ))}
        {links.length < L.links && <button type="button" onClick={() => setLinks([...links, { label: "", url: "" }])} className="inline-flex items-center gap-1.5 self-start rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim hover:text-tx"><PlusIcon size={12} />Add a link</button>}
      </Section>

      <Section id="ed-changelog" title="Changelog" sub="Cyrus writes release notes for every version. Add your own words on top: they show first, marked as yours.">
        {init.versions.map((v) => (
          <details key={v.buildId} className="rounded-[11px] border border-rim-hi bg-well p-3" open={!!changelog[v.buildId]}>
            <summary className="cursor-pointer text-[12.5px] font-bold text-tx"><span className="num">{v.label}</span> <span className="font-normal text-tx-faint">· {v.notes.slice(0, 90)}{v.notes.length > 90 ? "…" : ""}</span></summary>
            <textarea className="input mt-2 min-h-[80px] text-[12.5px]" value={changelog[v.buildId] ?? ""} maxLength={L.changelogMax} placeholder="Your notes for this version" aria-label={`Your notes for ${v.label}`} onChange={(e) => setChangelog({ ...changelog, [v.buildId]: e.target.value })} />
          </details>
        ))}
      </Section>

      <Section id="ed-sharing" title="Visibility and remixing">
        <div className="grid gap-2 sm:grid-cols-2" role="radiogroup" aria-label="Visibility">
          {(["PRIVATE", "PUBLIC"] as const).map((v) => (
            <button key={v} type="button" role="radio" aria-checked={visibility === v} onClick={() => setVisibility(v)} className={"rounded-[12px] border p-3 text-left " + (visibility === v ? "border-violet/60 bg-violet/10" : "border-rim-hi bg-well")} data-testid={`ed-vis-${v}`}>
              <span className="block text-[13px] font-extrabold text-tx">{v === "PUBLIC" ? "Public on NxLabs" : "Private"}</span>
              <span className="mt-0.5 block text-[11.5px] leading-relaxed text-tx-dim">{v === "PUBLIC" ? `Anyone can read the page and download the plugin and its source under ${init.license}.` : "Only you can see the page."}</span>
            </button>
          ))}
        </div>
        {goingPublic && <p className="rounded-[10px] border border-amber/40 bg-amber/10 px-3 py-2 text-[12px] leading-relaxed text-tx">Publishing shows your display name as the creator (never your email). Copies people download stay out there if you make it private later.</p>}
        <div className="grid gap-2 sm:grid-cols-2" role="radiogroup" aria-label="Remixing">
          {(["OPEN", "CLOSED"] as const).map((v) => (
            <button key={v} type="button" role="radio" aria-checked={remixPolicy === v} onClick={() => setRemixPolicy(v)} className={"rounded-[12px] border p-3 text-left " + (remixPolicy === v ? "border-violet/60 bg-violet/10" : "border-rim-hi bg-well")} data-testid={`ed-remix-${v}`}>
              <span className="block text-[13px] font-extrabold text-tx">{v === "OPEN" ? "Anyone can remix it" : "No remixes"}</span>
              <span className="mt-0.5 block text-[11.5px] leading-relaxed text-tx-dim">{v === "OPEN" ? "People with Cyrus can build their own version on top of it. Yours stays yours, they credit you, and their published versions show up under Community versions on this page." : "Only you build on it in Cyrus. The source download and its licence don't change."}</span>
            </button>
          ))}
        </div>
      </Section>

      <div className="sticky bottom-3 z-20 flex flex-wrap items-center gap-3 rounded-[16px] border border-rim-hi bg-surface/95 px-4 py-3 shadow-[0_20px_50px_-24px_rgba(0,0,0,.7)] backdrop-blur">
        <button type="button" onClick={save} disabled={pending || !!uploading} className={`${CY_CTA} px-5 py-2 text-[13px]`} data-testid="ed-save">{pending ? "Saving…" : goingPublic ? "Save and publish" : "Save listing"}</button>
        <Link href={`/dashboard/nxlabs/cyrus/${init.slug}`} prefetch={false} className="text-[12.5px] font-semibold text-tx-dim hover:text-tx">Cancel</Link>
        {msg && <span className={"text-[12px] " + (msg.ok ? "text-mint" : "text-rose")} role="status">{msg.text}</span>}
      </div>
    </div>
  );
}

toolu_01RbBmVDXKArzjs7LvitoFHG.content:
"use client";

import Link from "next/link";
import { useMemo, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { CY_CTA } from "./cta";
import { deleteListingMedia, saveModListing } from "@/lib/actions-cyrus-community";
import { LISTING_LIMITS, listingHtml, normaliseTag, type ListingLink, type RemixPolicy } from "@/lib/cyrus-mods/listing";
import type { MediaView } from "@/lib/cyrus-mods/social";
import type { CategoryKey } from "@/lib/cyrus/types";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { ArrowIcon, ImageIcon, PlusIcon, TrashIcon } from "./cxIcons";

export type EditorInit = {
  slug: string;
  rootBuildId: string;
  title: string;
  generatedTagline: string | null;
  tagline: string;
  description: string;
  category: string | null;
  autoCategory: string | null;
  tags: string[];
  links: ListingLink[];
  changelog: Record<string, string>;
  visibility: "PUBLIC" | "PRIVATE";
  remixPolicy: RemixPolicy;
  license: string;
  icon: MediaView | null;
  banner: MediaView | null;
  photos: MediaView[];
  versions: { buildId: string; label: string; notes: string }[];
  categories: { key: string; label: string; description: string }[];
};

const L = LISTING_LIMITS;
const Section = ({ title, sub, children, id }: { title: string; sub?: string; children: React.ReactNode; id: string }) => (
  <section className="rounded-[16px] border border-rim-hi bg-surface p-5" aria-labelledby={id}>
    <h2 id={id} className="text-[15px] font-extrabold text-tx">{title}</h2>
    {sub && <p className="mt-0.5 text-[12px] leading-relaxed text-tx-dim">{sub}</p>}
    <div className="mt-3.5 flex flex-col gap-3.5">{children}</div>
  </section>
);
const Field = ({ label, hint, children, count }: { label: string; hint?: string; children: React.ReactNode; count?: string }) => (
  <label className="flex flex-col gap-1.5">
    <span className="flex items-baseline gap-2 text-[12.5px] font-bold text-tx">{label}{count && <span className="num ml-auto text-[11px] font-normal text-tx-faint">{count}</span>}</span>
    {children}
    {hint && <span className="text-[11.5px] leading-relaxed text-tx-faint">{hint}</span>}
  </label>
);

/** NxLabs "Edit listing": everything the creator can change about their mod's page. */
export function ListingEditor({ init }: { init: EditorInit }) {
  const router = useRouter();
  const [title, setTitle] = useState(init.title);
  const [tagline, setTagline] = useState(init.tagline);
  const [description, setDescription] = useState(init.description);
  const [preview, setPreview] = useState(false);
  const [category, setCategory] = useState<string | null>(init.category);
  const [tags, setTags] = useState<string[]>(init.tags);
  const [tagDraft, setTagDraft] = useState("");
  const [links, setLinks] = useState<ListingLink[]>(init.links.length ? init.links : []);
  const [changelog, setChangelog] = useState<Record<string, string>>(init.changelog);
  const [visibility, setVisibility] = useState(init.visibility);
  const [remixPolicy, setRemixPolicy] = useState<RemixPolicy>(init.remixPolicy);
  const [icon, setIcon] = useState<MediaView | null>(init.icon);
  const [banner, setBanner] = useState<MediaView | null>(init.banner);
  const [photos, setPhotos] = useState<MediaView[]>(init.photos);
  const [uploading, setUploading] = useState<string | null>(null);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, start] = useTransition();
  const iconInput = useRef<HTMLInputElement>(null);
  const bannerInput = useRef<HTMLInputElement>(null);
  const photoInput = useRef<HTMLInputElement>(null);
  const html = useMemo(() => (preview ? listingHtml(description) : ""), [preview, description]);

  const upload = async (files: FileList | null, kind: "icon" | "banner" | "photo") => {
    if (!files?.length) return;
    setMsg(null);
    for (const f of Array.from(files).slice(0, kind === "photo" ? L.photos - photos.length : 1)) {
      setUploading(kind);
      const fd = new FormData();
      fd.append("file", f);
      fd.append("kind", kind);
      const r = await fetch(`/api/nxlabs/cyrus/${init.slug}/media`, { method: "POST", body: fd }).catch(() => null);
      const j = r ? await r.json().catch(() => ({})) : {};
      if (!r?.ok) { setMsg({ ok: false, text: j.error || "That upload didn't go through." }); break; }
      if (kind === "icon") setIcon(j.media);
      else if (kind === "banner") setBanner(j.media);
      else setPhotos((p) => [...p, j.media]);
    }
    setUploading(null);
  };

  const removePhoto = (id: string) =>
    start(async () => {
      const r = await deleteListingMedia(id).catch(() => ({ error: "Couldn't reach Nxeon." }));
      if ("error" in r && r.error) { setMsg({ ok: false, text: r.error }); return; }
      setPhotos((p) => p.filter((x) => x.id !== id));
    });
  const move = (i: number, d: -1 | 1) => setPhotos((p) => {
    const j = i + d;
    if (j < 0 || j >= p.length) return p;
    const n = [...p];
    [n[i], n[j]] = [n[j], n[i]];
    return n;
  });
  const addTag = (raw: string) => {
    const parts = raw.split(/[,\n]/).map(normaliseTag).filter((t) => t.length >= L.tagMin);
    if (parts.length) setTags((t) => [...new Set([...t, ...parts])].slice(0, L.tags));
    setTagDraft("");
  };

  const save = () =>
    start(async () => {
      setMsg(null);
      const r = await saveModListing(init.rootBuildId, {
        title,
        tagline,
        description,
        category,
        tags,
        links: links.filter((l) => l.label.trim() || l.url.trim()),
        changelog,
        visibility,
        remixPolicy,
        iconMediaId: icon?.id ?? null,
        bannerMediaId: banner?.id ?? null,
        photoOrder: photos.map((p) => p.id),
        captions: Object.fromEntries(photos.map((p) => [p.id, p.caption ?? ""])),
      }).catch(() => ({ error: "Couldn't reach Nxeon." }));
      if ("error" in r && r.error) { setMsg({ ok: false, text: r.error }); return; }
      setMsg({ ok: true, text: "Saved." });
      router.push(`/dashboard/nxlabs/cyrus/${init.slug}`);
      router.refresh();
    });

  const goingPublic = visibility === "PUBLIC" && init.visibility !== "PUBLIC";
  return (
    <div className="flex flex-col gap-4 pb-24" data-testid="listing-editor">
      <Section id="ed-basics" title="Basics" sub="What people see first, on the card and at the top of the page.">
        <Field label="Name" count={`${title.length}/${L.titleMax}`} hint="Also renames the project in your Cyrus.">
          <input className="input" value={title} maxLength={L.titleMax} onChange={(e) => setTitle(e.target.value)} data-testid="ed-title" />
        </Field>
        <Field label="Short description" count={`${tagline.length}/${L.taglineMax}`} hint={init.generatedTagline ? `Leave empty to use Cyrus's: “${init.generatedTagline}”` : undefined}>
          <input className="input" value={tagline} maxLength={L.taglineMax} placeholder={init.generatedTagline ?? "One line about what it does"} onChange={(e) => setTagline(e.target.value)} data-testid="ed-tagline" />
        </Field>
        <div className="flex flex-col gap-1.5">
          <span className="text-[12.5px] font-bold text-tx">Category</span>
          <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-3 lg:grid-cols-4" role="radiogroup" aria-label="Category">
            <button type="button" role="radio" aria-checked={category === null} onClick={() => setCategory(null)} className={"flex items-center gap-2 rounded-[10px] border px-2.5 py-2 text-left text-[12px] " + (category === null ? "border-violet/60 bg-violet/10 text-tx" : "border-rim-hi bg-well text-tx-dim hover:text-tx")}>
              <span className="text-[11px] font-bold uppercase text-violet">Auto</span>
              <span className="min-w-0 truncate">{init.autoCategory ? init.categories.find((c) => c.key === init.autoCategory)?.label ?? "Cyrus decides" : "Cyrus decides"}</span>
            </button>
            {init.categories.map((c) => (
              <button key={c.key} type="button" role="radio" aria-checked={category === c.key} title={c.description} onClick={() => setCategory(c.key)} className={"flex items-center gap-2 rounded-[10px] border px-2.5 py-2 text-left text-[12px] " + (category === c.key ? "border-violet/60 bg-violet/10 text-tx" : "border-rim-hi bg-well text-tx-dim hover:text-tx")}>
                <CategoryIcon k={c.key as CategoryKey} width={16} height={16} className="flex-none text-violet" />
                <span className="min-w-0 truncate">{c.label}</span>
              </button>
            ))}
          </div>
          <span className="text-[11.5px] text-tx-faint">Cyrus sorts mods by what they do. Pick one only when it got yours wrong.</span>
        </div>
        <div className="flex flex-col gap-1.5">
          <span className="flex items-baseline text-[12.5px] font-bold text-tx">Tags <span className="num ml-auto text-[11px] font-normal text-tx-faint">{tags.length}/{L.tags}</span></span>
          <div className="flex flex-wrap items-center gap-1.5 rounded-[11px] border border-rim-hi bg-well p-1.5">
            {tags.map((t) => (
              <span key={t} className="inline-flex items-center gap-1 rounded-full border border-rim-hi bg-surface px-2 py-0.5 text-[11.5px] text-tx">#{t}
                <button type="button" aria-label={`Remove tag ${t}`} onClick={() => setTags(tags.filter((x) => x !== t))} className="text-tx-faint hover:text-rose">×</button>
              </span>
            ))}
            {tags.length < L.tags && <input value={tagDraft} onChange={(e) => setTagDraft(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === ",") { e.preventDefault(); addTag(tagDraft); } }} onBlur={() => tagDraft && addTag(tagDraft)} placeholder={tags.length ? "Add a tag" : "pvp, economy, boss…"} aria-label="Add a tag" className="min-w-[120px] flex-1 bg-transparent px-1.5 py-1 text-[12.5px] text-tx outline-none placeholder:text-tx-faint" data-testid="ed-tags" />}
          </div>
        </div>
      </Section>

      <Section id="ed-images" title="Icon, banner and photos" sub="PNG, JPG, WebP or GIF up to 8 MB. Nxeon re-encodes every image (and strips its metadata) before anyone sees it.">
        <div className="grid gap-4 sm:grid-cols-[auto_minmax(0,1fr)]">
          <div className="flex flex-col items-start gap-2">
            <span className="text-[12.5px] font-bold text-tx">Icon</span>
            <button type="button" onClick={() => iconInput.current?.click()} className="grid h-[88px] w-[88px] place-items-center overflow-hidden rounded-[20px] border border-dashed border-rim-hi bg-well text-tx-faint hover:border-violet/50" aria-label={icon ? "Replace the icon" : "Upload an icon"} data-testid="ed-icon">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {icon ? <img src={icon.url} alt="Icon" className="h-full w-full object-cover" /> : uploading === "icon" ? <span className="text-[11px]">Uploading…</span> : <ImageIcon size={22} />}
            </button>
            <input ref={iconInput} type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={(e) => { void upload(e.target.files, "icon"); e.target.value = ""; }} />
            {icon && <button type="button" onClick={() => setIcon(null)} className="text-[11.5px] font-semibold text-tx-dim hover:text-rose">Remove</button>}
          </div>
          <div className="flex min-w-0 flex-col items-stretch gap-2">
            <span className="text-[12.5px] font-bold text-tx">Banner <span className="font-normal text-tx-faint">wide, behind the title</span></span>
            <button type="button" onClick={() => bannerInput.current?.click()} className="grid aspect-[10/3] w-full place-items-center overflow-hidden rounded-[14px] border border-dashed border-rim-hi bg-well text-tx-faint hover:border-violet/50" aria-label={banner ? "Replace the banner" : "Upload a banner"} data-testid="ed-banner">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {banner ? <img src={banner.url} alt="Banner" className="h-full w-full object-cover" /> : uploading === "banner" ? <span className="text-[11px]">Uploading…</span> : <span className="flex items-center gap-2 text-[12px]"><ImageIcon size={18} />Upload a banner</span>}
            </button>
            <input ref={bannerInput} type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={(e) => { void upload(e.target.files, "banner"); e.target.value = ""; }} />
            {banner && <button type="button" onClick={() => setBanner(null)} className="self-start text-[11.5px] font-semibold text-tx-dim hover:text-rose">Remove</button>}
          </div>
        </div>
        <div className="flex flex-col gap-2">
          <span className="flex items-baseline text-[12.5px] font-bold text-tx">Photo gallery <span className="ml-2 font-normal text-tx-faint">first photo is the cover</span><span className="num ml-auto text-[11px] font-normal text-tx-faint">{photos.length}/{L.photos}</span></span>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4" data-testid="ed-photos">
            {photos.map((p, i) => (
              <div key={p.id} className="flex flex-col gap-1.5 rounded-[12px] border border-rim-hi bg-well p-1.5">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={p.url} alt={p.caption ?? `Photo ${i + 1}`} className="aspect-[16/10] w-full rounded-[8px] object-cover" />
