import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { requireCyrusAccess } from "@/lib/cyrus-mods/gate";
import { readModDoc, versionLabel } from "@/lib/cyrus-mods/doc";
import { listingsFor, toListingView } from "@/lib/cyrus-mods/social";
import { scoreCategory } from "@/lib/cyrus/real";
import { CATEGORIES } from "@/lib/cyrus/data";
import { LabsTabs } from "@/components/nx/labs/LabsBits";
import { ListingEditor } from "@/components/nx/labs/cyrus/ListingEditor";
import "@/components/cyrus-mods/community.css";
import "../../../labs.css";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Edit listing · Cyrus Mods", robots: { index: false, follow: false } };

/** NxLabs → a Cyrus mod → "Edit listing". The creator only (404 for everyone else, and while an admin views as a customer). */
export default async function EditCyrusListing({ params }: { params: Promise<{ slug: string }> }) {
  const { user } = await requireCyrusAccess();
  const { slug } = await params;
  if (!user || !/^[a-z0-9-]{3,60}$/.test(slug)) notFound();
  const real = await realUser().catch(() => null);
  const page = await db.cyrusModPage.findUnique({ where: { slug } });
  if (!page || page.userId !== user.id || !real || real.id !== user.id) notFound();
  const doc = readModDoc(page.doc);
  if (!doc) notFound();
  const { listings, media } = await listingsFor([page.id]);
  const row = listings.get(page.id) ?? null;
  const lv = toListingView(row, media.get(page.id) ?? [], true);
  return (
    <div className="nxl-root mx-auto flex w-full max-w-[980px] flex-col gap-5">
      <LabsTabs active="cyrus" installedCount={0} cyrus />
      <header className="flex flex-wrap items-end gap-3">
        <div className="min-w-0 flex-1">
          <nav className="text-[11.5px] text-tx-faint" aria-label="Breadcrumb"><Link href="/dashboard/nxlabs/cyrus" className="hover:text-tx" prefetch={false}>Cyrus Mods</Link> / <Link href={`/dashboard/nxlabs/cyrus/${page.slug}`} className="hover:text-tx" prefetch={false}>{page.title}</Link></nav>
          <h1 className="text-[24px] font-extrabold tracking-[-0.02em] text-tx">Edit listing</h1>
          <p className="text-[12.5px] text-tx-dim">Everything Cyrus generated (commands, permissions, config, versions) stays and keeps updating with every build. This is yours on top.</p>
        </div>
        <Link href={`/dashboard/cyrus/${doc.currentBuildId ?? page.rootBuildId}`} prefetch={false} className="rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim hover:text-tx">Open in Cyrus</Link>
      </header>
      <ListingEditor
        init={{
          slug: page.slug,
          rootBuildId: page.rootBuildId,
          title: page.title,
          generatedTagline: doc.tagline,
          tagline: row?.tagline ?? "",
          description: row?.description ?? "",
          category: row?.category ?? null,
          autoCategory: scoreCategory([page.title, doc.tagline, doc.summary].filter(Boolean).join(" \n ")),
          tags: lv.tags,
          links: lv.links,
          changelog: lv.changelog,
          visibility: page.visibility === "PUBLIC" ? "PUBLIC" : "PRIVATE",
          remixPolicy: lv.remixPolicy,
          license: page.license,
          icon: lv.icon,
          banner: lv.banner,
          photos: lv.photos,
          versions: doc.versions.map((v) => ({ buildId: v.buildId, label: versionLabel(v), notes: v.notes })),
          categories: CATEGORIES.map((c) => ({ key: c.key, label: c.label, description: c.description })),
        }}
      />
    </div>
  );
}
EOF

