cd /tank/dev-worktrees/cyrus-v6-community && cat > components/nx/labs/cyrus/CreatorBits.tsx <<'EOF'
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { CY_CTA } from "./cta";
import { deleteCyrusCollection, saveCreatorBio, setCollectionItem, updateCyrusCollection } from "@/lib/actions-cyrus-community";

/** The creator's own bio on their profile. */
export function BioEditor({ bio }: { bio: string | null }) {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState(bio ?? "");
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const router = useRouter();
  if (!open) return <button type="button" onClick={() => setOpen(true)} className="rounded-[10px] border border-white/20 bg-white/[0.07] px-3 py-1.5 text-[12px] font-semibold text-white hover:bg-white/[0.12]" data-testid="bio-edit">{bio ? "Edit bio" : "Add a bio"}</button>;
  return (
    <div className="flex w-full flex-col gap-2">
      <textarea value={text} onChange={(e) => setText(e.target.value)} maxLength={400} className="input min-h-[80px] text-[12.5px]" aria-label="Bio" placeholder="What you build, what servers you run…" />
      <div className="flex items-center gap-2">
        <button type="button" disabled={pending} onClick={() => start(async () => { const r = await saveCreatorBio(text).catch(() => ({ error: "Couldn't reach Nxeon." })); if ("error" in r && r.error) { setErr(r.error); return; } setOpen(false); router.refresh(); })} className={`${CY_CTA} px-3.5 py-1.5 text-[12px]`}>Save</button>
        <button type="button" onClick={() => setOpen(false)} className="text-[12px] font-semibold text-white/70 hover:text-white">Cancel</button>
        <span className="num ml-auto text-[11px] text-white/50">{text.length}/400</span>
      </div>
      {err && <p className="text-[11.5px] text-rose" role="alert">{err}</p>}
    </div>
  );
}

/** Owner controls on a collection page: visibility, delete; per item: remove. */
export function CollectionOwnerBar({ id, visibility, title }: { id: string; visibility: "PUBLIC" | "PRIVATE"; title: string }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  const [confirm, setConfirm] = useState(false);
  const router = useRouter();
  const run = (fn: () => Promise<{ error?: string }>, after?: () => void) => start(async () => { const r = await fn().catch(() => ({ error: "Couldn't reach Nxeon." })); if (r.error) { setErr(r.error); return; } after?.(); router.refresh(); });
  return (
    <div className="flex flex-wrap items-center gap-2" data-testid="collection-owner">
      <button type="button" disabled={pending} onClick={() => run(() => updateCyrusCollection(id, { visibility: visibility === "PUBLIC" ? "PRIVATE" : "PUBLIC" }) as Promise<{ error?: string }>)} className="rounded-[10px] border border-white/20 bg-white/[0.07] px-3 py-1.5 text-[12px] font-semibold text-white hover:bg-white/[0.12]">{visibility === "PUBLIC" ? "Make private" : "Make public"}</button>
      {confirm ? (
        <>
          <span className="text-[12px] text-white/80">Delete “{title}”? The mods themselves stay.</span>
