import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { currentUser } from "@/lib/auth";
import { cyrusMetadata, requireCyrusAccess } from "@/lib/cyrus-mods/gate";
import { creatorProfile } from "@/lib/cyrus-mods/social";
import { CreatorProfileView } from "@/components/nx/labs/cyrus/CommunityPages";
import "@/components/cyrus-mods/community.css";
import { LabsTabs } from "@/components/nx/labs/LabsBits";
import "../../../labs.css";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }: { params: Promise<{ handle: string }> }): Promise<Metadata> {
  const v = await creatorProfile((await params).handle, await currentUser().catch(() => null)).catch(() => null);
  const m = await cyrusMetadata(v ? `${v.name} · Cyrus creator` : "Page not found", v?.bio ?? undefined);
  return { ...m, robots: { index: false, follow: true } };
}

/** A Cyrus creator's profile: their published mods, collections and real totals. Display name only, never the email. */
export default async function CyrusCreatorPage({ params }: { params: Promise<{ handle: string }> }) {
  const { user } = await requireCyrusAccess();
  const v = await creatorProfile((await params).handle, user);
  if (!v) notFound();
  return (
    <div className="nxl-root mx-auto flex w-full max-w-[1320px] flex-col gap-6">
      <LabsTabs active="cyrus" installedCount={0} cyrus />
      <CreatorProfileView v={v} base="/dashboard/nxlabs/cyrus" />
    </div>
  );
}

