// Cyrus v6 community: the "Add to my Cyrus" library on the studio map. Kept in its own small store
// (the shared studio store only holds the Mod nodes, `libraryMods`). Entries come from the server
// action getCyrusLibrary(); nothing is copied until the viewer remixes.
import { create } from "zustand";
