import { knownCategory } from "@/lib/cyrus/real";
import type { Mod, ModFile } from "@/lib/cyrus/types";

export const LIB_PREFIX = "lib-";
export const libraryModId = (pageId: string) => `${LIB_PREFIX}${pageId}`;
export const isLibraryModId = (id: string | null | undefined): id is string => !!id && id.startsWith(LIB_PREFIX);

type LibState = {
  entries: Record<string, LibraryEntry>;
  files: Record<string, ModFile[] | "loading" | "error">;
