"use client";

import { useEffect } from "react";
import { getCyrusLibrary } from "@/lib/actions-cyrus-community";
import { GAMES } from "@/lib/cyrus/data";
import { useStore } from "@/lib/cyrus/store";
import { libraryMod, useLibrary } from "./library";

const REAL_GAME = GAMES.find((g) => g.real) ?? GAMES[0];

/** Loads the viewer's community library once (and when the tab comes back) and puts it on the map. Renders nothing. */
export function CyrusLibrarySync() {
  useEffect(() => {
    let live = true;
    const load = async () => {
      const r = await getCyrusLibrary().catch(() => null);
      if (!live || !r || !("entries" in r)) return;
      useLibrary.getState().set(r.entries);
      useStore.getState().setLibraryMods(r.entries.map((e) => libraryMod(e, REAL_GAME.id)));
    };
    void load();
    const vis = () => { if (document.visibilityState === "visible") void load(); };
    document.addEventListener("visibilitychange", vis);
    return () => { live = false; document.removeEventListener("visibilitychange", vis); };
  }, []);
  return null;
}
