"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { CloseIcon, CodeIcon, HistoryIcon, NoteIcon } from "@/components/cyrus/icons/ui";
import { CodeView, FileTabs } from "@/components/cyrus/preview/CodeView";
import { Markdown } from "@/components/cyrus/preview/Markdown";
import { Modal } from "@/components/cyrus/kit/InstallModal";
import { CyIcon } from "@/components/cyrus/kit/icons";
import { installCommunityMod, myCyrusServers, remixCyrusMod, removeFromMyCyrus } from "@/lib/actions-cyrus-community";
import { CATEGORY_BY_KEY } from "@/lib/cyrus/data";
import { toModFile } from "@/lib/cyrus/real";
import { getGame, useMod, useStore } from "@/lib/cyrus/store";
import type { MbServer } from "@/lib/modbuilder/install";
import { useLibrary } from "./library";

type Tab = "code" | "versions" | "about";

/**
 * A community mod on the viewer's map ("Add to my Cyrus"): READ-ONLY. Its code, versions and notes
 * come from its public NxLabs page; the actions are install (on your own server) and remix (your
 * own copy, re-scanned first). Nothing is copied until you remix.
 */
export function LibraryPanel({ modId, onClose }: { modId: string; onClose: () => void }) {
  const mod = useMod(modId);
  const e = useLibrary((s) => s.entries[modId]);
  const files = useLibrary((s) => s.files[modId]);
  const [tab, setTab] = useState<Tab>("code");
  const [active, setActive] = useState<string | null>(null);
  const [install, setInstall] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const toast = useStore((s) => s.toast);

  // Source of the current version, from the public page's own source route.
  useEffect(() => {
    if (!e || files) return;
    const paths = e.files.filter((f) => /^src\//.test(f.path)).slice(0, 40);
    const build = e.currentBuildId;
    if (!build || !paths.length) { useLibrary.getState().setFiles(modId, []); return; }
    useLibrary.getState().setFiles(modId, "loading");
    void Promise.all(paths.map(async (f) => {
      const r = await fetch(`/api/nxlabs/cyrus/${e.slug}/source?build=${build}&path=${encodeURIComponent(f.path)}`).catch(() => null);
      return r?.ok ? toModFile(f.path, await r.text()) : null;
    })).then((list) => {
      const ok = list.filter((x): x is NonNullable<typeof x> => !!x);
      useLibrary.getState().setFiles(modId, ok.length ? ok : "error");
    });
  }, [e, files, modId]);

  if (!mod || !e) {
    return (
      <aside className="cy5-glass animate-slide-right fixed inset-x-2 bottom-2 top-[68px] z-40 grid place-items-center rounded-[22px] p-8 text-[13px] text-cy-muted lg:inset-x-auto lg:bottom-5 lg:right-5 lg:top-[76px] lg:w-[min(540px,calc(40cqw-20px))]" aria-label="Preview panel">
        <span>Loading this community mod…</span>
      </aside>
    );
  }
  const game = getGame(mod.gameId);
  const cat = CATEGORY_BY_KEY[mod.category];
  const list = Array.isArray(files) ? files : [];
  const current = list.find((f) => f.path === active) ?? list.find((f) => /\.java$/.test(f.path)) ?? list[0];
  const remix = async (buildId?: string) => {
    setBusy("remix");
    const r = await remixCyrusMod(e.slug, buildId ?? null).catch(() => ({ error: "Couldn't reach Nxeon." }));
    if ("error" in r && r.error) { setBusy(null); toast({ tone: "error", title: "Couldn't remix it", body: r.error }); return; }
    window.location.assign((r as { href: string }).href);
  };
  const remove = async () => {
    setBusy("remove");
    await removeFromMyCyrus(e.slug).catch(() => null);
    useLibrary.getState().set(Object.values(useLibrary.getState().entries).filter((x) => x.pageId !== e.pageId));
    useStore.getState().setLibraryMods(useStore.getState().libraryMods.filter((m) => m.id !== modId));
    setBusy(null);
    onClose();
  };
  const about = [
    `# ${e.title}`,
    "",
    `By **${e.creator}** · licence ${e.license} · a community mod on your map (read-only).`,
    ...(e.summary ? ["", e.summary] : []),
    "",
    "## What you can do",
    "- **Install** it on one of your Paper / Purpur servers. It updates when its creator publishes a new version.",
    e.remix.ok ? "- **Remix** it: Cyrus safety-checks the code again, then gives you your own copy with the original's prompt history. Your published changes show under Community versions on its page." : `- Remix: ${e.remix.ok ? "" : e.remix.message}`,
  ].join("\n");
  const tabs: { id: Tab; label: string; icon: React.ReactNode }[] = [
    { id: "code", label: "Code", icon: <CodeIcon /> },
    { id: "versions", label: "Versions", icon: <HistoryIcon /> },
    { id: "about", label: "About", icon: <NoteIcon /> },
  ];
  return (
    <aside className="cy5-glass animate-slide-right fixed inset-x-2 bottom-2 top-[68px] z-40 flex flex-col overflow-hidden rounded-[22px] lg:inset-x-auto lg:bottom-5 lg:right-5 lg:top-[76px] lg:w-[min(540px,calc(40cqw-20px))]" aria-label="Community mod" data-testid="library-panel">
      <header className="tint hairline-top px-5 pt-5" style={{ ["--c" as string]: cat.rgb }}>
        <div className="flex items-start gap-3">
          {e.iconUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={e.iconUrl} alt="" className="mt-0.5 h-11 w-11 shrink-0 rounded-[13px] object-cover" />
          ) : (
            <span className="mt-0.5 grid h-11 w-11 shrink-0 rotate-45 place-items-center rounded-[13px] text-[21px]" style={{ color: "var(--cc)", background: `rgb(${cat.rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${cat.rgb} / 0.45)` }}>
              <CategoryIcon k={cat.key} className="-rotate-45" />
            </span>
          )}
          <div className="min-w-0 flex-1">
