function CommunityInstallModal({ slug, buildId, title, label, onClose }: { slug: string; buildId: string; title: string; label: string; onClose: () => void }) {
  const [servers, setServers] = useState<MbServer[] | null>(null);
  const [sel, setSel] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);
  useEffect(() => {
    void myCyrusServers().then((r) => {
      const list = "servers" in r ? r.servers : [];
      setServers(list);
      setSel(list.find((s) => s.compatible)?.id ?? null);
    }).catch(() => setServers([]));
  }, []);
  const go = async () => {
    if (!sel) return;
    setBusy(true);
    setErr(null);
    const r = await installCommunityMod(slug, buildId, sel).catch(() => ({ error: "Couldn't reach Nxeon." }));
    setBusy(false);
    if ("error" in r && r.error) { setErr(r.error); return; }
    setDone((r as { serverName: string }).serverName);
  };
  if (done) {
    return (
      <Modal title="Installing" onClose={onClose}>
        <div className="cy-done">
          <span className="cy-done-orb"><CyIcon name="check" size={22} strokeWidth={2.4} /></span>
          <p className="cy-done-t">{title} is going onto {done}.</p>
