          <div className="flex flex-wrap justify-center gap-2">
            <Link href={`/dashboard/servers/${sel}`} className="cy-btn primary">Open server <CyIcon name="chevr" size={13} /></Link>
            <button type="button" className="cy-btn" onClick={onClose}>Done</button>
          </div>
        </div>
      </Modal>
    );
  }
  return (
    <Modal title="Install on my server" sub={`${title} ${label} · a community mod (published on NxLabs).`} onClose={onClose}>
      {servers === null ? <p className="cy-sub">Loading your servers…</p> : servers.length === 0 ? (
        <div className="cy-done">
          <span className="cy-done-orb dim"><CyIcon name="server" size={20} /></span>
          <p className="cy-done-t">You don&apos;t have a Minecraft server yet</p>
          <Link href="/dashboard/deploy" className="cy-btn primary">Get a Minecraft server</Link>
        </div>
      ) : (
        <>
          <div className="cy-srvs" role="radiogroup" aria-label="Server">
            {servers.map((s) => (
              <label key={s.id} className={`cy-srv ${sel === s.id ? "on" : ""} ${s.compatible ? "" : "off"}`}>
                <input type="radio" name="cy-lib-srv" className="sr-only" disabled={!s.compatible} checked={sel === s.id} onChange={() => setSel(s.id)} />
                <span className={`cy-srv-dot ${s.status === "RUNNING" ? "up" : ""}`} />
                <span className="flex min-w-0 flex-1 flex-col"><b className="truncate">{s.name}</b><span className="cy-sub">{s.compatible ? `${s.variant ?? ""} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span></span>
                {sel === s.id && <CyIcon name="check" size={15} />}
              </label>
            ))}
          </div>
          <p className="cy-sub">Community mods run on your server like your own: check what it does on its page first. Restart the server afterwards to load it.</p>
