  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const text = prompt.trim();
  if (!text) return;
  const model = MODEL_BY_ID[state.model];

  const sel = state.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  // An idea pill is a prompt, not a mod: a forge from it is a brand-new mod in its category.
  const refineMod = picked?.idea ? undefined : picked;
  if (refineMod?.real && !refineMod.real.headBuildId) {
