// Cyrus v6 community: the pure rules behind listings, remixes, credit, Community-tested, the
// remix re-scan and installs of published mods. No DB.
import { test } from "node:test";
import assert from "node:assert/strict";

import { validateListing, cleanLinkUrl, normaliseTag, listingHtml, readLinks, readChangelog, DEFAULT_REMIX_POLICY, LISTING_LIMITS, isMediaKind } from "../lib/cyrus-mods/listing.ts";
import { remixDecision, creditChain, creditLine, buildRemixTree, treeSize, remixNotes, remixTitle, originOf, remixDepth, type LineageNode } from "../lib/cyrus-mods/remix.ts";
import { evaluateCommunityTested, compareMc, compatTags, rateDecision, countInstallers, averageScore, isScore, COMMUNITY_TESTED, type TestedInput } from "../lib/cyrus-mods/tested.ts";
import { scanSourceText, rescanVerdict, rescanPaths } from "../lib/cyrus-mods/rescan.ts";
import { mayInstallChain } from "../lib/cyrus-mods/doc.ts";

const ctx = { versionIds: ["b1", "b2"], categories: ["weapons", "mechanics"], media: [{ id: "m1", kind: "photo" }, { id: "m2", kind: "photo" }, { id: "i1", kind: "icon" }, { id: "x1", kind: "banner" }] };

/* ── listing ───────────────────────────────────────────────────────────── */

test("listing: only sent fields are validated and returned", () => {
  const r = validateListing({ title: "  Frost   Blade ", tagline: "Freezes\nthings" }, ctx);
  assert.ok(r.ok);
  if (!r.ok) return;
  assert.deepEqual(r.clean, { title: "Frost Blade", tagline: "Freezes things" });
  assert.equal(validateListing({}, ctx).ok, false);
  assert.equal(validateListing(null, ctx).ok, false);
});

test("listing: title, tagline and description limits", () => {
  assert.equal(validateListing({ title: "ab" }, ctx).ok, false);
  assert.equal(validateListing({ title: "x".repeat(LISTING_LIMITS.titleMax + 1) }, ctx).ok, false);
  assert.equal(validateListing({ tagline: "x".repeat(LISTING_LIMITS.taglineMax + 1) }, ctx).ok, false);
  assert.equal(validateListing({ description: "x".repeat(LISTING_LIMITS.descriptionMax + 1) }, ctx).ok, false);
  const empty = validateListing({ tagline: "   ", description: "" }, ctx);
  assert.ok(empty.ok && empty.clean.tagline === null && empty.clean.description === null, "empty clears");
});

test("listing: category must be a known one (or null = auto)", () => {
  assert.ok(validateListing({ category: "weapons" }, ctx).ok);
  const auto = validateListing({ category: null }, ctx);
  assert.ok(auto.ok && auto.clean.category === null);
  const bad = validateListing({ category: "hacks" }, ctx);
  assert.ok(!bad.ok && bad.field === "category");
});

test("listing: tags are normalised, deduped, capped", () => {
  assert.equal(normaliseTag("  Boss Fights!! "), "boss-fights");
  assert.equal(normaliseTag("Épée"), "epee");
  const r = validateListing({ tags: ["PvP", "pvp", "x", "Economy"] }, ctx);
  assert.ok(r.ok && JSON.stringify(r.clean.tags) === JSON.stringify(["pvp", "economy"]));
  assert.equal(validateListing({ tags: Array.from({ length: 9 }, (_, i) => `tag${i}`) }, ctx).ok, false);
});

test("listing: links are https only, no credentials, no javascript:", () => {
  assert.equal(cleanLinkUrl("discord.gg/abc"), "https://discord.gg/abc");
  assert.equal(cleanLinkUrl("http://example.com/x"), "https://example.com/x");
  assert.equal(cleanLinkUrl("javascript:alert(1)"), null);
  assert.equal(cleanLinkUrl("https://user:pw@example.com"), null);
  assert.equal(cleanLinkUrl("data:text/html,hi"), null);
  assert.equal(cleanLinkUrl("localhost"), null);
  const r = validateListing({ links: [{ label: "", url: "example.com" }, { label: "", url: "" }] }, ctx);
  assert.ok(r.ok && r.clean.links?.length === 1 && r.clean.links[0].label === "example.com");
  assert.equal(validateListing({ links: [{ label: "x", url: "javascript:alert(1)" }] }, ctx).ok, false);
  assert.deepEqual(readLinks([{ label: "a", url: "javascript:x" }, { label: "b", url: "https://ok.example" }]), [{ label: "b", url: "https://ok.example/" }]);
});

test("listing: changelog only for this mod's versions; empty notes drop out", () => {
  const r = validateListing({ changelog: { b1: "Fixed the trail", b2: "  " } }, ctx);
  assert.ok(r.ok && JSON.stringify(r.clean.changelog) === JSON.stringify({ b1: "Fixed the trail" }));
  assert.equal(validateListing({ changelog: { other: "x" } }, ctx).ok, false);
  assert.deepEqual(readChangelog({ b1: "a", "bad id!": "b", b2: 3 }), { b1: "a" });
});

test("listing: media must belong to the page and be the right kind", () => {
  assert.ok(validateListing({ iconMediaId: "i1", bannerMediaId: "x1", photoOrder: ["m2", "m1"] }, ctx).ok);
  assert.equal(validateListing({ iconMediaId: "m1" }, ctx).ok, false, "a photo is not an icon");
  assert.equal(validateListing({ photoOrder: ["m1", "zz"] }, ctx).ok, false);
  const clear = validateListing({ iconMediaId: null }, ctx);
  assert.ok(clear.ok && clear.clean.iconMediaId === null);
  assert.equal(validateListing({ captions: { nope: "x" } }, ctx).ok, false);
  assert.ok(isMediaKind("banner") && !isMediaKind("video"));
});

test("listing: visibility + remix policy; OPEN is the default", () => {
  assert.equal(DEFAULT_REMIX_POLICY, "OPEN");
  assert.ok(validateListing({ visibility: "PUBLIC", remixPolicy: "CLOSED" }, ctx).ok);
  assert.equal(validateListing({ visibility: "WORLD" as never }, ctx).ok, false);
  assert.equal(validateListing({ remixPolicy: "MAYBE" as never }, ctx).ok, false);
});

test("listing: description html is escaped and never carries images or script", () => {
  const html = listingHtml("## Hi\n\n<script>alert(1)</script>\n\n![x](https://evil.example/pixel.png)\n\n<img src=\"https://evil.example/a.png\">\n\n**bold** [link](javascript:alert(2))");
  assert.ok(!/<script/i.test(html), "no script");
  assert.ok(!/<img/i.test(html), "no images");
  assert.ok(/<h3/.test(html) && /<strong/.test(html));
  assert.ok(!/javascript:/i.test(html.replace(/&lt;script&gt;alert\(1\)&lt;\/script&gt;/, "")) || !/href="javascript:/i.test(html), "no javascript: href");
  assert.equal(listingHtml(""), "");
});

/* ── remix permissions ─────────────────────────────────────────────────── */

const pub = { userId: "ana", visibility: "PUBLIC", hiddenAt: null };

test("remix: who may remix", () => {
  assert.deepEqual(remixDecision({ viewer: null, page: pub, policy: "OPEN", hasCyrus: true }).ok, false);
  const noCyrus = remixDecision({ viewer: { id: "bo" }, page: pub, policy: "OPEN", hasCyrus: false });
  assert.ok(!noCyrus.ok && noCyrus.reason === "no-cyrus");
  const own = remixDecision({ viewer: { id: "ana" }, page: { ...pub, visibility: "PRIVATE" }, policy: "CLOSED", hasCyrus: true });
  assert.ok(own.ok && own.mode === "own", "the creator always opens their own, even private/closed");
  assert.ok(remixDecision({ viewer: { id: "bo" }, page: pub, policy: "OPEN", hasCyrus: true }).ok);
  assert.ok(remixDecision({ viewer: { id: "bo" }, page: pub, policy: null, hasCyrus: true }).ok, "no listing = OPEN default");
  const closed = remixDecision({ viewer: { id: "bo" }, page: pub, policy: "CLOSED", hasCyrus: true });
  assert.ok(!closed.ok && closed.reason === "closed");
  const priv = remixDecision({ viewer: { id: "bo" }, page: { ...pub, visibility: "PRIVATE" }, policy: "OPEN", hasCyrus: true });
  assert.ok(!priv.ok && priv.reason === "not-found");
  const hidden = remixDecision({ viewer: { id: "bo" }, page: { ...pub, hiddenAt: new Date() }, policy: "OPEN", hasCyrus: true });
  assert.ok(!hidden.ok && hidden.reason === "not-found");
  const unsafe = remixDecision({ viewer: { id: "bo" }, page: pub, policy: "OPEN", hasCyrus: true, scanVerdict: "block" });
  assert.ok(!unsafe.ok && unsafe.reason === "unsafe");
});

/* ── credit chain ──────────────────────────────────────────────────────── */

const node = (id: string, parent: string | null, o: Partial<LineageNode> = {}): LineageNode => ({ pageId: id, slug: `s-${id}`, title: `T${id}`, creator: `C${id}`, parentPageId: parent, visible: true, ...o });
const map = (ns: LineageNode[]) => new Map(ns.map((n) => [n.pageId, n]));

test("credit: preserved down the chain, parent first, origin last", () => {
  const ns = map([node("a", null), node("b", "a", { baseLabel: "v2 · 1.1.0" }), node("c", "b", { baseLabel: "v1" })]);
  const ch = creditChain("c", ns);
  assert.deepEqual(ch.map((x) => x.pageId), ["b", "a"]);
  assert.equal(ch[0].baseLabel, "v1", "the version of the parent this was built on");
  assert.equal(creditLine(ch), "Remixed from Tb by Cb · originally Ta by Ca");
  assert.equal(creditLine(creditChain("b", ns)), "Remixed from Ta by Ca");
  assert.equal(creditLine(creditChain("a", ns)), null);
  assert.equal(originOf("c", ns), "a");
  assert.equal(remixDepth("b", ns), 2, "a remix of b is two levels down");
});

test("credit: a private ancestor keeps its creator's name but not its title or link", () => {
  const ns = map([node("a", null, { visible: false }), node("b", "a")]);
  const ch = creditChain("b", ns);
  assert.equal(ch[0].slug, null);
  assert.equal(ch[0].title, null);
  assert.equal(ch[0].creator, "Ca");
  assert.match(creditLine(ch)!, /a mod by Ca that is no longer public/);
});

test("credit: cycles and missing parents stop safely", () => {
  const ns = map([node("a", "b"), node("b", "a")]);
  assert.equal(creditChain("a", ns).length, 1);
  assert.deepEqual(creditChain("x", map([node("x", "gone")])), []);
});

test("remix tree: invisible leaves dropped, invisible branches kept anonymous", () => {
  const ns = [node("a", null), node("b", "a", { visible: false }), node("c", "b"), node("d", "a", { visible: false }), node("e", "a", { stars: 5 })];
  const t = buildRemixTree("a", ns)!;
  assert.equal(treeSize(t), 4, "a, b (anon), c, e — d dropped");
  assert.equal(t.children[0].pageId, "e", "most-starred first");
  const b = t.children.find((x) => x.pageId === "b")!;
  assert.ok(b.anonymous && b.children[0].pageId === "c");
  assert.equal(buildRemixTree("zz", ns), null);
});

test("remix notes: history of succeeded steps, capped", () => {
  const steps = [
    { prompt: "A frost sword", changeRequest: null, status: "succeeded", createdAt: new Date() },
    { prompt: "A frost sword", changeRequest: "Add an ice trail", status: "succeeded", createdAt: new Date() },
    { prompt: "A frost sword", changeRequest: "Broken attempt", status: "failed", createdAt: new Date() },
  ];
  const n = remixNotes({ title: "Frost", creator: "Ana", baseLabel: "v2", license: "MIT", slug: "frost", steps });
  assert.match(n, /# Remixed from Frost/);
  assert.match(n, /1\. A frost sword/);
  assert.match(n, /2\. Add an ice trail/);
  assert.ok(!/Broken attempt/.test(n));
  const long = remixNotes({ title: "X", creator: "Y", baseLabel: "v1", license: "MIT", slug: "x", steps: Array.from({ length: 50 }, () => ({ prompt: "p".repeat(500), changeRequest: "c".repeat(500), status: "succeeded", createdAt: new Date() })) });
  assert.ok(long.length <= 4000 && /more step/.test(long));
  assert.equal(remixTitle("Frost Blade (fork)"), "Frost Blade (remix)");
});

/* ── Community-tested ──────────────────────────────────────────────────── */

const now = new Date("2026-10-20T12:00:00Z");
const good: TestedInput = { isPublic: true, installers: 5, ratings: { count: 3, average: 4.3 }, openBugs: 0, currentMc: "1.21.11", newestMc: "1.21.11", safety: "pass", currentAt: "2026-10-10T12:00:00Z", now };

test("community-tested: earned only when every check passes", () => {
  const t = evaluateCommunityTested(good);
  assert.ok(t.earned);
  assert.equal(t.passed, t.checks.length);
  const fails: [Partial<TestedInput>, string][] = [
    [{ isPublic: false }, "public"],
    [{ installers: COMMUNITY_TESTED.minInstallers - 1 }, "installs"],
    [{ ratings: { count: 2, average: 5 } }, "ratings"],
    [{ ratings: { count: 9, average: 3.9 } }, "ratings"],
    [{ ratings: { count: 0, average: null } }, "ratings"],
    [{ openBugs: 1 }, "bugs"],
    [{ currentMc: "1.21.8" }, "version"],
    [{ currentMc: null }, "version"],
    [{ safety: "block" }, "safety"],
    [{ safety: null }, "safety"],
    [{ currentAt: "2026-10-15T12:00:00Z" }, "time"],
  ];
  for (const [patch, id] of fails) {
    const r = evaluateCommunityTested({ ...good, ...patch });
    assert.equal(r.earned, false, `fails on ${id}`);
    assert.equal(r.checks.find((c) => c.id === id)?.ok, false, `${id} is the failing check`);
  }
  assert.ok(evaluateCommunityTested({ ...good, safety: "warn" }).earned, "passed with notes still counts");
});

test("community-tested helpers: installers, ratings, versions", () => {
  assert.equal(countInstallers([{ userId: "ana" }, { userId: "bo" }, { userId: "bo" }, { userId: "cy" }], "ana"), 2, "distinct accounts, creator excluded");
  assert.equal(averageScore([5, 4, 4]), 4.3);
  assert.equal(averageScore([]), null);
  assert.equal(averageScore([0, 6, 3]), 3);
  assert.ok(isScore(5) && !isScore(0) && !isScore(4.5));
  assert.equal(compareMc("1.21.11", "1.21.8"), 1);
  assert.equal(compareMc("1.21.1", "1.21.1"), 0);
  assert.equal(compareMc("1.20.6", "1.21"), -1);
});

test("rating: only installers, never the creator", () => {
  assert.equal(rateDecision({ viewerId: null, creatorId: "ana", installedByViewer: false }).ok, false);
  assert.equal(rateDecision({ viewerId: "ana", creatorId: "ana", installedByViewer: true }).ok, false);
  assert.equal(rateDecision({ viewerId: "bo", creatorId: "ana", installedByViewer: false }).ok, false);
  assert.ok(rateDecision({ viewerId: "bo", creatorId: "ana", installedByViewer: true }).ok);
});

test("compat tags: facts only, out-of-date warning", () => {
  const cur = compatTags({ currentMc: "1.21.11", builtFor: ["1.21.11", "1.21.8"], newestMc: "1.21.11", software: ["Paper"], serversOnCurrent: 0 });
  assert.deepEqual(cur.map((t) => t.label), ["Built for MC 1.21.11", "Earlier builds: MC 1.21.8", "Paper"]);
  const run = compatTags({ currentMc: "1.21.11", builtFor: ["1.21.11"], newestMc: "1.21.11", software: [], serversOnCurrent: 2 });
  assert.ok(run.some((t) => t.label === "Running on 2 servers"));
  const old = compatTags({ currentMc: "1.21.4", builtFor: ["1.21.4"], newestMc: "1.21.11", software: [] });
  assert.ok(old.some((t) => t.tone === "old" && /Needs an update for 1\.21\.11/.test(t.label)));
});

/* ── remix re-scan ─────────────────────────────────────────────────────── */

test("rescan: the service's source rules, run on text", () => {
  const ok = scanSourceText([{ path: "src/main/java/A.java", text: 'getDataFolder();\nplayer.sendMessage("hi");' }]);
  assert.deepEqual(ok, []);
  const bad = scanSourceText([{ path: "src/main/java/B.java", text: 'new File("/etc/passwd");\nString b = "' + "A".repeat(210) + '";' }]);
  assert.deepEqual(bad.map((f) => f.rule).sort(), ["encoded-blob", "file-outside"]);
  const uuidWarn = scanSourceText([{ path: "src/main/java/C.java", text: 'UUID u = UUID.fromString("123e4567-e89b-12d3-a456-426614174000");' }]);
  assert.equal(uuidWarn[0].severity, "warn");
  const uuidBlock = scanSourceText([{ path: "src/main/java/D.java", text: 'if (p.getUniqueId().equals(UUID.fromString("123e4567-e89b-12d3-a456-426614174000"))) p.setOp(true);' }]);
  assert.equal(uuidBlock[0].severity, "block");
  const name = scanSourceText([{ path: "src/main/java/E.java", text: 'if (p.getName().equals("Notch")) p.setOp(true);' }]);
  assert.ok(name.some((f) => f.rule === "hardcoded-name" && f.severity === "block"));
  const secret = scanSourceText([{ path: "src/main/resources/config.yml", text: "key: [REDACTED]" }]);
  assert.ok(secret.some((f) => f.rule === "secret"));
  assert.deepEqual(scanSourceText([{ path: "README.md", text: 'new File("/etc/x")' }]), [], "only .java gets the code rules");
});

test("rescan: verdict combines stored verdict, findings and the jar checksum", () => {
  assert.equal(rescanVerdict({ stored: "pass", findings: [], checksumOk: true, files: 3 }).verdict, "pass");
  assert.equal(rescanVerdict({ stored: "warn", findings: [], checksumOk: true, files: 3 }).verdict, "warn");
  assert.equal(rescanVerdict({ stored: "block", findings: [], checksumOk: true, files: 3 }).verdict, "block");
  const mismatch = rescanVerdict({ stored: "pass", findings: [], checksumOk: false, files: 3 });
  assert.equal(mismatch.verdict, "block");
  assert.equal(mismatch.findings[0].rule, "checksum");
  assert.equal(rescanVerdict({ stored: "pass", findings: [], checksumOk: null, files: 3 }).verdict, "pass", "old builds without a hash: not a block");
  assert.equal(rescanVerdict({ stored: "pass", findings: [{ severity: "block", rule: "x", where: "a", message: "m", evidence: "e" }], checksumOk: true, files: 1 }).verdict, "block");
});

test("rescan: reads source + resources only, bounded", () => {
  const files = [{ path: "src/main/java/A.java", size: 10 }, { path: "build/libs/x.jar", size: 1 }, { path: "src/main/resources/plugin.yml", size: 5 }, { path: "src/main/resources/logo.png", size: 5 }, { path: "modbuilder.json", size: 1 }];
  assert.deepEqual(rescanPaths(files), ["src/main/java/A.java", "src/main/resources/plugin.yml"]);
  assert.equal(rescanPaths(Array.from({ length: 100 }, (_, i) => ({ path: `src/main/java/F${i}.java`, size: 10 }))).length, 80);
  assert.equal(rescanPaths([{ path: "src/main/java/Big.java", size: 2_000_000 }]).length, 0);
});

/* ── installs of published mods ────────────────────────────────────────── */

test("install: own servers always; others only while the page is public and not hidden", () => {
  assert.ok(mayInstallChain({ chainOwnerId: "ana", serverOwnerId: "ana", page: null }));
  assert.ok(mayInstallChain({ chainOwnerId: "ana", serverOwnerId: "bo", page: { visibility: "PUBLIC", hiddenAt: null } }));
  assert.equal(mayInstallChain({ chainOwnerId: "ana", serverOwnerId: "bo", page: { visibility: "PRIVATE", hiddenAt: null } }), false);
  assert.equal(mayInstallChain({ chainOwnerId: "ana", serverOwnerId: "bo", page: { visibility: "PUBLIC", hiddenAt: new Date() } }), false);
  assert.equal(mayInstallChain({ chainOwnerId: "ana", serverOwnerId: "bo", page: null }), false);
});

