  for (const k of ["ana", "bo"]) {
    const token = await new SignJWT({ sub: U[k].id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
    await db.userSession.create({ data: { userId: U[k].id, tokenHash: createHash("sha256").update(token).digest("hex") } });
    tok[k] = token;
  }
  writeFileSync(".next.cyrus-community-session.json", JSON.stringify(tok));
  const pages = await db.cyrusModPage.findMany({ select: { slug: true, visibility: true, rootBuildId: true } });
  console.log("seeded pages:", pages.map((p) => `${p.slug}(${p.visibility})`).join(" "));
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });

