// THROWAWAY Playwright run ON node-2 (devhost run) against the node-2 dev server. Never committed.
// BASE=http://127.0.0.1:<port> OUT=dir ONLY=a,b
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE;
const OUT = process.env.OUT || ".community-shots";
const ONLY = (process.env.ONLY || "").split(",").filter(Boolean);
const tok = JSON.parse(readFileSync(".next.cyrus-community-session.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const log = [];
const note = (...a) => { const l = a.join(" "); log.push(l); console.log(l); };
const want = (k) => !ONLY.length || ONLY.includes(k);

const browser = await chromium.launch({ args: ["--disable-dev-shm-usage"] });
async function ctx(who, w, theme) {
  const mobile = w < 600;
  const c = await browser.newContext({ viewport: { width: w, height: mobile ? 844 : 900 }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const host = new URL(BASE).hostname;
  if (who) await c.addCookies([{ name: "nxeon_session", value: tok[who], domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  await c.addInitScript((t) => {
    try {
      localStorage.setItem("nx-theme", t);
      for (const k of ["nx-whatsnew-seen", "nx-tour-done", "heard-about-us-dismissed", "promo-trial-dismissed"]) localStorage.setItem(k, "1");
    } catch {}
  }, theme);
  const p = await c.newPage();
  p.on("pageerror", (e) => note("PAGEERROR", who, w, theme, e.message.slice(0, 300)));
  p.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource: the server responded with a status of 404/.test(m.text())) note("CONSOLE", who, m.text().slice(0, 240)); });
  return { c, p };
}
async function go(p, url) {
  for (let i = 0; i < 8; i++) {
    try {
      const r = await p.goto(BASE + url, { waitUntil: "domcontentloaded", timeout: 240000 });
      note("GET", url, r?.status());
      await p.waitForLoadState("networkidle", { timeout: 60000 }).catch(() => {});
      return r;
    } catch (e) {
      if (i === 7) throw e;
      await p.waitForTimeout(8000);
    }
  }
}
async function popups(p) {
  for (const name of ["Got it", "Close", "Not now", "Skip", "Dismiss"]) {
    const b = p.getByRole("button", { name, exact: true });
    if ((await b.count()) && (await b.first().isVisible().catch(() => false))) await b.first().click().catch(() => {});
  }
}
const shot = async (p, name, opts = {}) => {
  await p.waitForTimeout(opts.wait ?? 900);
  const sw = await p.evaluate(() => [document.documentElement.scrollWidth, window.innerWidth]);
  if (sw[0] > sw[1] + 1) note("OVERFLOW", name, `scrollWidth ${sw[0]} > ${sw[1]}`);
  await p.screenshot({ path: `${OUT}/${name}.png`, fullPage: !!opts.full, timeout: 180000 });
  note("shot", name);
};
const FROST = "/dashboard/nxlabs/cyrus/frostbite-blade";

if (want("page")) {
  for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390], ["light", 390]]) {
    const { c, p } = await ctx("ana", w, theme);
    await go(p, FROST);
    await popups(p);
    note("laurel in header:", await p.locator('[data-testid="cyrus-mod-header"] [data-badge="laurel"]').count());
    note("tested earned:", await p.locator('[data-testid="tested-panel"]').getAttribute("data-earned").catch(() => "?"));
    await shot(p, `page-overview-${theme}-${w}`, { full: true });
    await p.getByRole("tab", { name: /Community versions/ }).click();
    await p.waitForTimeout(600);
    const view = p.getByRole("button", { name: "View changes" }).first();
    if (await view.count()) { await view.click(); await p.locator('[data-testid="community-diff"] li button').first().waitFor({ timeout: 30000 }).catch(() => note("diff: no files")); await p.locator('[data-testid="community-diff"] li button').first().click().catch(() => {}); }
    await shot(p, `page-community-versions-${theme}-${w}`, { full: true, wait: 1500 });
    await c.close();
  }
}

if (want("edit")) {
  for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390]]) {
    const { c, p } = await ctx("ana", w, theme);
    await go(p, `${FROST}/edit`);
    await popups(p);
    await shot(p, `editor-${theme}-${w}`, { full: true });
    if (theme === "dark" && w === 1440) {
      await p.getByRole("tab", { name: "Preview" }).click();
      await shot(p, `editor-preview-${theme}-${w}`, { full: false, wait: 600 });
      note("script rendered in preview:", await p.locator(".cyx-prose script").count());
      // a real save: tags + a caption edit, back to the page
      await p.getByRole("tab", { name: "Write" }).click();
      await p.locator('[data-testid="ed-tags"]').fill("ice");
      await p.keyboard.press("Enter");
      await p.locator('[data-testid="ed-save"]').click();
      await p.waitForURL(/frostbite-blade$/, { timeout: 60000 }).catch(() => note("save: no redirect"));
      note("after save tags:", await p.locator('a[href*="?q=ice"]').count());
    }
    await c.close();
  }
}

if (want("viewer")) {
  const { c, p } = await ctx("bo", 1440, "dark");
  await go(p, FROST);
  await popups(p);
  await shot(p, "viewer-page-dark-1440", { full: false });
  const star = p.locator('[data-testid="star-button"]');
  note("star before:", await star.innerText());
  await star.click();
  await p.waitForTimeout(1500);
  note("star after:", await star.innerText());
  await go(p, "/dashboard/nxlabs/cyrus");
  await shot(p, "index-dark-1440", { full: true });
  await go(p, "/dashboard/nxlabs/cyrus/c/winter-pvp-pack");
  await shot(p, "collection-dark-1440", { full: true });
  const prof = await p.evaluate(() => fetch("/dashboard/nxlabs/cyrus").then((r) => r.text()));
  void prof;
  await c.close();
}

if (want("profile")) {
  for (const [theme, w] of [["dark", 1440], ["light", 390]]) {
    const { c, p } = await ctx("ana", w, theme);
    await go(p, "/dashboard/nxlabs/cyrus");
    const href = await p.locator('[data-testid="my-profile-link"]').getAttribute("href").catch(() => null);
    note("profile link:", href);
    if (href) { await go(p, href); await shot(p, `profile-${theme}-${w}`, { full: true }); }
    await go(p, "/dashboard/nxlabs/cyrus/coin-shop");
    await shot(p, `untested-checklist-${theme}-${w}`, { full: true });
    await c.close();
  }
}

if (want("remix")) {
  const { c, p } = await ctx("bo", 1440, "dark");
  await go(p, "/dashboard/nxlabs/cyrus/coin-shop");
  await popups(p);
  await p.locator('[data-testid="cyrus-mod-header"] [data-testid="remix-button"]').click();
  await p.waitForURL(/\/dashboard\/cyrus\/mb[0-9a-f]+/, { timeout: 120000 }).catch(() => note("remix: no redirect"));
  note("remix landed on", p.url());
  await p.waitForTimeout(6000);
  await shot(p, "remix-landed-cyrus-dark-1440", { wait: 1500 });
  const notes = p.getByRole("tab", { name: /Notes/ });
  if (await notes.count()) { await notes.first().click(); await shot(p, "remix-notes-dark-1440", { wait: 1200 }); }
  // its new page credits the original
  const r = await p.evaluate(() => fetch("/dashboard/nxlabs/cyrus").then((x) => x.text()));
  note("index mentions remix:", /remix of Coin Shop/.test(r));
  await c.close();
}

if (want("library")) {
  for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390]]) {
    const { c, p } = await ctx("bo", w, theme);
    await go(p, "/dashboard/cyrus");
    await popups(p);
    await p.waitForTimeout(7000);
    const pill = p.getByRole("button", { name: /Community mod: Frostbite Blade/ });
    note("library pill:", await pill.count());
    await shot(p, `cyrus-map-library-${theme}-${w}`, { wait: 1500 });
    if (await pill.count()) {
      await pill.first().click({ force: true });
      await p.locator('[data-testid="library-panel"]').waitFor({ timeout: 30000 }).catch(() => note("library panel: not shown"));
      await p.waitForTimeout(3000);
      await shot(p, `library-panel-${theme}-${w}`, { wait: 1200 });
      if (theme === "dark" && w === 1440) {
        await p.locator('[data-testid="library-install"]').click();
        await p.waitForTimeout(2500);
        await shot(p, "library-install-modal-dark-1440", { wait: 600 });
        const btn = p.locator(".cy-modal").getByRole("button", { name: "Install" });
        if (await btn.count()) { await btn.click(); await p.waitForTimeout(4000); await shot(p, "library-install-done-dark-1440", { wait: 600 }); }
      }
    }
    await c.close();
  }
}

if (want("public")) {
  const { c, p } = await ctx("bo", 1440, "dark");
  await go(p, "/mods/cyrus/frostbite-blade");
  await shot(p, "public-page-dark-1440", { full: true });
  await c.close();
  const anon = await ctx(null, 1440, "dark");
  const r = await go(anon.p, "/mods/cyrus/frostbite-blade");
  note("anonymous (gate off) status:", r?.status());
  await anon.c.close();
}

await browser.close();
writeFileSync(`${OUT}/log.txt`, log.join("\n"));

