    await shot(p, `page-overview-${theme}-${w}`, { full: true });
    await p.getByRole("tab", { name: /Community versions/ }).click();
    await p.waitForTimeout(600);
    const view = p.getByRole("button", { name: "View changes" }).first();
    if (await view.count()) { await view.click(); await p.locator('[data-testid="community-diff"] li button').first().waitFor({ timeout: 30000 }).catch(() => note("diff: no files")); await p.locator('[data-testid="community-diff"] li button').first().click().catch(() => {}); }
    await shot(p, `page-community-versions-${theme}-${w}`, { full: true, wait: 1500 });
