  const r = await go(anon.p, "/mods/cyrus/frostbite-blade");
  note("anonymous (gate off) status:", r?.status());
  await anon.c.close();
}

await browser.close();
writeFileSync(`${OUT}/log.txt`, log.join("\n"));

